def _openai_tts_speech_json(input_text: str) -> dict[str, Any]:
    """JSON body for OpenAI POST /v1/audio/speech."""
    body: dict[str, Any] = {
        "model": OPENAI_TTS_MODEL,
        "input": input_text,
        "voice": OPENAI_TTS_VOICE,
        "response_format": "wav",
    }
    if "gpt-4o-mini-tts" in OPENAI_TTS_MODEL.lower():
        instr_env = os.getenv("OPENAI_TTS_INSTRUCTIONS")
        if instr_env is None:
            body["instructions"] = (
                "Speak like a real human tutor in a relaxed one-on-one call. "
                "Sound warm, casual, and clear. "
                "Use natural pauses, light conversational emphasis, and gentle variety in pacing. "
                "Never sound like you are reading a textbook or performing dramatically."
            )
        elif instr_env.strip():
            body["instructions"] = instr_env.strip()
        # empty string env = omit instructions (API default delivery)
    return body


def _openai_generate_image_bytes(
    prompt: str,
    *,
    size: str = "1536x1024",
    quality: str = "high",
) -> tuple[bytes, str, str]:
    """Generate an image with OpenAI. Returns (bytes, mime, error_message)."""
    if not OPENAI_API_KEY:
        return b"", "", "OPENAI_API_KEY not set"

    # Try the configured model first, then fall back to currently-supported ones.
    candidates: list[str] = []
    for m in (OPENAI_IMAGE_MODEL, "gpt-image-2", "gpt-image-1.5", "gpt-image-1", "gpt-image-1-mini", "dall-e-3"):
        if m and m not in candidates:
            candidates.append(m)

    last_error = ""
    for model_name in candidates:
        payload: dict[str, Any] = {
            "model": model_name,
            "prompt": prompt,
            "size": size,
        }
        # dall-e-3 uses different quality values and no 1536x1024 size.
        if model_name == "dall-e-3":
            payload["size"] = "1792x1024" if size.startswith("1536") else (
                "1024x1792" if size.startswith("1024x1536") else "1024x1024"
            )
            payload["quality"] = "hd"
            payload["response_format"] = "b64_json"
        else:
            payload["quality"] = quality

        try:
            with httpx.Client(timeout=httpx.Timeout(180.0, read=180.0)) as http:
                resp = http.post(
                    "https://api.openai.com/v1/images/generations",
                    headers={
                        "Authorization": f"Bearer {OPENAI_API_KEY}",
                        "Content-Type": "application/json",
                    },
                    json=payload,
                )
                if resp.status_code >= 400:
                    try:
                        body = resp.json()
                        err_obj = body.get("error", {}) if isinstance(body, dict) else {}
                        err_msg = str(err_obj.get("message") or err_obj.get("code") or body)[:300]
                    except Exception:
                        err_msg = (resp.text or "")[:300]
                    last_error = f"{model_name}: HTTP {resp.status_code} - {err_msg}"
                    logger.warning("OpenAI image generation failed on %s: %s", model_name, last_error)
                    continue

                data = resp.json()
                items = data.get("data", []) if isinstance(data, dict) else []
                item = items[0] if isinstance(items, list) and items else {}
                if not isinstance(item, dict):
                    last_error = f"{model_name}: empty response"
                    continue
                b64_json = str(item.get("b64_json", "") or "").strip()
                if b64_json:
                    image_bytes = base64.b64decode(b64_json)
                    mime = _sniff_image_mime(image_bytes) or "image/png"
                    logger.info("OpenAI image generation succeeded with %s", model_name)
                    return image_bytes, mime, ""
                image_url = str(item.get("url", "") or "").strip()
                if image_url:
                    img_resp = http.get(image_url)
                    img_resp.raise_for_status()
                    image_bytes = img_resp.content
                    mime = (
                        (img_resp.headers.get("content-type") or "").split(";", 1)[0].strip()
                        or _sniff_image_mime(image_bytes)
                        or "image/png"
                    )
                    logger.info("OpenAI image generation succeeded with %s (url)", model_name)
                    return image_bytes, mime, ""
                last_error = f"{model_name}: no image data in response"
        except Exception as e:
            last_error = f"{model_name}: {type(e).__name__}: {e}"
            logger.warning("OpenAI image generation exception on %s: %s", model_name, e)
            continue

    return b"", "", last_error or "all image models failed"


_VOICE_FILLER_OPENERS = (
    "Okay",
    "Alright",
    "So",
    "Right",
    "Now",
)
_VOICE_FILLER_MIDDLES = (
    "now",
    "think about this",
    "so",
    "here's the idea",
    "let's take it step by step",
)


def _split_for_voice(text: str) -> list[str]:
    text = re.sub(r"\s+", " ", (text or "").strip())
    if not text:
        return []

    chunks: list[str] = []
    for sentence in re.split(r"(?<=[.!?])\s+", text):
        s = sentence.strip(" \t\r\n")
        if not s:
            continue
        parts = re.split(r"(?<=[,;:])\s+|\s+(?=(?:and|but|so|because|which|that|then)\b)", s, flags=re.IGNORECASE)
        for part in parts:
            p = part.strip(" ,;:")
            if p:
                chunks.append(p)
    return chunks


def _split_long_voice_chunk(chunk: str, target_words: int = 10) -> list[str]:
    words = chunk.split()
    if len(words) <= 15:
        return [chunk.strip()]

    pieces: list[str] = []
    current: list[str] = []
    soft_breaks = {"and", "but", "because", "so", "then", "which", "that", "if", "when", "while"}

    for word in words:
        current.append(word)
        clean_word = word.strip(".,;:!?").lower()
        should_break = (
            len(current) >= target_words
            and clean_word in soft_breaks
        ) or len(current) >= 14
        if should_break:
            segment = " ".join(current).strip(" ,;:")
            if segment:
                pieces.append(segment)
            current = []

    if current:
        segment = " ".join(current).strip(" ,;:")
        if segment:
            pieces.append(segment)
    return pieces or [chunk.strip()]


def _normalize_spoken_piece(piece: str) -> str:
    p = re.sub(r"\s+", " ", (piece or "").strip())
    if not p:
        return ""
    p = re.sub(r"\bfor example\b", "for example", p, flags=re.IGNORECASE)
    p = re.sub(r"\be\.g\.\b", "for example", p, flags=re.IGNORECASE)
    return p


def rewrite_for_voice(text: str) -> str:
    """Make tutor text easier to speak aloud without changing its meaning."""
    chunks = _split_for_voice(text)
    if not chunks:
        return (text or "").strip()

    opener = random.choice(_VOICE_FILLER_OPENERS)
    bridge = random.choice(_VOICE_FILLER_MIDDLES)
    spoken_parts: list[str] = []

    for chunk in chunks:
        for piece in _split_long_voice_chunk(chunk):
            clean_piece = _normalize_spoken_piece(piece)
            if clean_piece:
                spoken_parts.append(clean_piece)

    if not spoken_parts:
        return text.strip()

    first_core = spoken_parts[0].rstrip(".!?")
    spoken_parts[0] = f"{opener}... {first_core}."

    if len(spoken_parts) >= 3:
        insert_at = 2 if len(spoken_parts) > 3 else 1
        spoken_parts.insert(insert_at, f"{bridge}.")

    voice_parts: list[str] = []
    for idx, part in enumerate(spoken_parts):
        part = part.strip()
        if not part:
            continue
        if re.fullmatch(rf"(?:{'|'.join(re.escape(x) for x in _VOICE_FILLER_MIDDLES)})\.", part, flags=re.IGNORECASE):
            voice_parts.append(part)
            continue
        clean = part.rstrip(".!? ")
        word_count = len(clean.split())
        if idx == 0:
            voice_parts.append(part)
        elif part.endswith("?"):
            voice_parts.append(f"{clean}?")
        elif word_count <= 3:
            voice_parts.append(f"{clean}...")
        elif word_count <= 8 and idx < len(spoken_parts) - 1:
            voice_parts.append(f"{clean},")
        else:
            voice_parts.append(f"{clean}.")

    voice_text = " ".join(voice_parts)
    voice_text = re.sub(r"\s+([,.!?])", r"\1", voice_text)
    voice_text = re.sub(r"\s+", " ", voice_text).strip()
    return voice_text or text.strip()


def _openrouter_llm_ready() -> bool:
    return bool(OPENROUTER_API_KEY)


def _openrouter_headers() -> dict[str, str]:
    referer = (os.getenv("OPENROUTER_HTTP_REFERER") or os.getenv("APP_BASE_URL") or "http://localhost:3000").strip()
    title = (os.getenv("OPENROUTER_APP_TITLE") or "Alex AI").strip() or "Alex AI"
    h: dict[str, str] = {
        "Authorization": f"Bearer {OPENROUTER_API_KEY}",
        "Content-Type": "application/json",
    }
    if referer:
        h["HTTP-Referer"] = referer
    h["X-Title"] = title
    return h


