def _repair_svg_marker_glitches(svg: str) -> str:
    """Drop SVG markers + marker-end/start/mid — thick strokes + markers double-draw in WebKit/Blink."""
    if not svg or "marker" not in svg.lower():
        return svg
    s = re.sub(r"(?is)<marker\b[^>]*>.*?</marker>", "", svg)
    s = re.sub(r"\s+marker-end\s*=\s*(?:\"[^\"]*\"|'[^']*'|[^\s>]+)", "", s)
    s = re.sub(r"\s+marker-start\s*=\s*(?:\"[^\"]*\"|'[^']*'|[^\s>]+)", "", s)
    s = re.sub(r"\s+marker-mid\s*=\s*(?:\"[^\"]*\"|'[^']*'|[^\s>]+)", "", s)
    s = re.sub(r"(?is)<defs>\s*</defs>", "", s)
    return s


def _sanitize_svg_markup(svg: str) -> str:
    raw = (svg or "").strip()
    if not raw or "<svg" not in raw.lower():
        return ""
    raw = _repair_svg_marker_glitches(raw)
    # Remove risky content from model-generated SVG before rendering.
    raw = re.sub(r"(?is)<script[^>]*>.*?</script>", "", raw)
    raw = re.sub(r"(?is)<foreignObject[^>]*>.*?</foreignObject>", "", raw)
    raw = re.sub(r"(?i)\son[a-z0-9_-]+\s*=\s*(\"[^\"]*\"|'[^']*'|[^\s>]+)", "", raw)
    raw = re.sub(
        r"(?i)\s(?:href|xlink:href)\s*=\s*(\"javascript:[^\"]*\"|'javascript:[^']*')",
        "",
        raw,
    )
    raw = re.sub(
        r"(?i)\s(?:href|xlink:href)\s*=\s*(\"data:text/html[^\"]*\"|'data:text/html[^']*')",
        "",
        raw,
    )
    return raw[:20000]


def _upgrade_human_stick_body(svg: str) -> str:
    s = svg or ""
    if "#f6c7a6" not in s:
        return s
    torso_line = re.search(
        r"<line x1='(\d+)' y1='(\d+)' x2='\1' y2='(\d+)' stroke='#0b0b0b' stroke-width='4'/>",
        s,
    )
    if not torso_line:
        return s
    cx = int(torso_line.group(1))
    leg_top = int(torso_line.group(2))
    # remove old stick-limb lines
    s = re.sub(
        r"<line x1='[^']+' y1='[^']+' x2='[^']+' y2='[^']+' stroke='#0b0b0b' stroke-width='4'(?:'| [^>]*)/>",
        "",
        s,
    )
    torso_rect = re.search(
        r"<rect x='(\d+)' y='(\d+)' width='(52|56)' height='(38|40|42|44|46|56)' rx='(\d+)' [^>]*stroke='#0b0b0b' stroke-width='4'/>",
        s,
    )
    if torso_rect:
        tx = int(torso_rect.group(1))
        ty = int(torso_rect.group(2))
        tw = int(torso_rect.group(3))
    else:
        tx = cx - 28
        ty = max(96, leg_top - 26)
        tw = 56
    arm_y = ty + 8
    left_arm_x = tx - 10
    right_arm_x = tx + tw
    left_leg_x = cx - 22
    right_leg_x = cx + 4
    limbs = (
        f"<rect x='{left_arm_x}' y='{arm_y}' width='10' height='40' rx='5' fill='#f6c7a6' stroke='#0b0b0b' stroke-width='3'/>"
        f"<rect x='{right_arm_x}' y='{arm_y}' width='10' height='40' rx='5' fill='#f6c7a6' stroke='#0b0b0b' stroke-width='3'/>"
        f"<rect x='{left_leg_x}' y='{leg_top}' width='18' height='48' rx='8' fill='#1d4ed8' stroke='#0b0b0b' stroke-width='4'/>"
        f"<rect x='{right_leg_x}' y='{leg_top}' width='18' height='48' rx='8' fill='#1d4ed8' stroke='#0b0b0b' stroke-width='4'/>"
        f"<rect x='{left_leg_x - 4}' y='{leg_top + 46}' width='26' height='10' rx='5' fill='#111827'/>"
        f"<rect x='{right_leg_x - 4}' y='{leg_top + 46}' width='26' height='10' rx='5' fill='#111827'/>"
    )
    return s.replace("</svg>", limbs + "</svg>")


def _is_allowed_external_svg_url(url: str) -> bool:
    try:
        parsed = urlparse((url or "").strip())
        if parsed.scheme not in {"https"}:
            return False
        host = (parsed.netloc or "").lower()
        return host in ALLOWED_EXTERNAL_SVG_HOSTS
    except Exception:
        return False


def _visual_asset_src(url: str) -> str:
    raw = (url or "").strip()
    if not raw:
        return ""
    if raw.startswith(("data:", "http://", "https://")):
        return raw
    if raw.startswith("/"):
        return f"{BACKEND_PUBLIC_ORIGIN}{raw}"
    return raw


def _render_visual_html(visual_type: str, visual_json: str) -> str:
    try:
        data = json.loads(visual_json or "{}")
    except Exception:
        return ""
    if not isinstance(data, dict):
        return ""

    title = _esc_html(data.get("title", ""))
    card = (
        "width:100%;background:linear-gradient(180deg, rgba(16,24,39,0.92), rgba(7,12,21,0.96));"
        "border:1px solid rgba(125,211,252,0.12);border-radius:20px;padding:18px 20px;margin:0;"
        "box-shadow:0 20px 60px rgba(2,6,23,0.32), inset 0 1px 0 rgba(255,255,255,0.04);"
    )
    title_style = (
        "font-size:0.76rem;font-weight:700;color:rgba(190,220,245,0.78);margin-bottom:12px;"
        "letter-spacing:.12em;text-transform:uppercase;"
    )

    if visual_type == "model3d":
        return _render_model3d_html(data)

    if visual_type == "illustration":
        image_url = str(data.get("image_url", "") or data.get("data_url", "")).strip()
        focus_points = data.get("focus_points", [])
        if not isinstance(focus_points, list):
            focus_points = []
        focus_points = [str(point).strip() for point in focus_points[:4] if str(point).strip()]
        focus_html = ""
        if focus_points:
            items = "".join(
                f"<li style='margin:0 0 8px 0;color:rgba(226,232,240,0.92);line-height:1.45;'>{_esc_html(point)}</li>"
                for point in focus_points
            )
            focus_html = (
                "<div style='margin-top:14px;padding:14px 16px;border-radius:14px;"
                "background:rgba(15,23,42,0.64);border:1px solid rgba(148,163,184,0.14);'>"
                "<div style='font-size:0.72rem;font-weight:700;letter-spacing:.10em;text-transform:uppercase;"
                "color:rgba(148,163,184,0.9);margin-bottom:10px;'>What to Notice</div>"
                f"<ul style='margin:0;padding-left:18px;'>{items}</ul>"
                "</div>"
            )
        if image_url:
            safe_url = _esc_html(_visual_asset_src(_signed_media_url(image_url)))
            if safe_url:
                title_html = f"<div style='{title_style}'>{title}</div>" if title else ""
                return (
                    f"<div style='{card}'>{title_html}"
                    f"<img src='{safe_url}' alt='generated illustration' "
                    "style='width:100%;height:auto;display:block;border-radius:10px;' "
                    "loading='lazy' decoding='async' referrerpolicy='no-referrer' />"
                    f"{focus_html}"
                    "</div>"
                )
        ext_url = str(data.get("url", "")).strip()
        if ext_url and _is_allowed_external_svg_url(ext_url):
            title_html = f"<div style='{title_style}'>{title}</div>" if title else ""
            safe_url = _esc_html(ext_url)
            return (
                f"<div style='{card}'>{title_html}"
                f"<img src='{safe_url}' alt='generated illustration' "
                "style='width:100%;height:auto;display:block;border-radius:10px;' "
                "loading='lazy' decoding='async' referrerpolicy='no-referrer' />"
                f"{focus_html}"
                "</div>"
            )
        svg_clean = _sanitize_svg_markup(str(data.get("svg", "")))
        svg_clean = _upgrade_human_stick_body(svg_clean)
        if not svg_clean:
            return ""
        svg_data_uri = "data:image/svg+xml;utf8," + quote(svg_clean, safe="")
        title_html = f"<div style='{title_style}'>{title}</div>" if title else ""
        return (
            f"<div style='{card}'>{title_html}"
            f"<img src='{svg_data_uri}' alt='generated illustration' "
            "style='width:100%;height:auto;display:block;border-radius:10px;"
            "background:#ffffff;' "
            "loading='lazy' decoding='async' />"
            f"{focus_html}"
            "</div>"
        )

    if visual_type == "diagram":
        steps = data.get("steps", [])
        if not isinstance(steps, list):
            steps = []
        steps = [str(s) for s in steps[:10] if s]
        if not steps:
            return ""
        desc = _esc_html(data.get("description", ""))
        n = len(steps)
        box_w = 440
        box_h = 44
        gap = 18
        arrow_h = 22
        pad_x = 30
        pad_top = 50 if desc else 20
        row_h = box_h + gap + arrow_h
        total_h = pad_top + n * (box_h + gap + arrow_h) - arrow_h - gap + 24
        svg_w = box_w + pad_x * 2
        cx = svg_w / 2
        colors = [
            ("rgba(59,130,246,0.18)", "rgba(96,165,250,0.7)"),
            ("rgba(16,185,129,0.18)", "rgba(52,211,153,0.7)"),
            ("rgba(245,158,11,0.18)", "rgba(251,191,36,0.7)"),
            ("rgba(239,68,68,0.18)", "rgba(248,113,113,0.7)"),
            ("rgba(168,85,247,0.18)", "rgba(196,131,255,0.7)"),
            ("rgba(236,72,153,0.18)", "rgba(244,114,182,0.7)"),
            ("rgba(20,184,166,0.18)", "rgba(45,212,191,0.7)"),
            ("rgba(99,102,241,0.18)", "rgba(129,140,248,0.7)"),
            ("rgba(234,179,8,0.18)", "rgba(250,204,21,0.7)"),
            ("rgba(6,182,212,0.18)", "rgba(34,211,238,0.7)"),
        ]
        hue_seed = "|".join(steps) + "|" + (data.get("description") or "") + "|" + (data.get("title") or "")
        color_offset = int(hashlib.md5(hue_seed.encode("utf-8")).hexdigest()[:8], 16) % len(colors)
        boxes = ""
        for i, step in enumerate(steps):
            y = pad_top + i * (box_h + gap + arrow_h)
            bg, border = colors[(i + color_offset) % len(colors)]
            rx = box_h // 2 if i == 0 or i == n - 1 else 10
            text_lines = []
            words = _esc_html(step).split()
            line = ""
            for w in words:
                if len(line) + len(w) + 1 > 55:
                    text_lines.append(line.strip())
                    line = w + " "
                else:
                    line += w + " "
            if line.strip():
                text_lines.append(line.strip())
            text_lines = text_lines[:3]
            line_h = 15
            text_block_h = len(text_lines) * line_h
            text_start_y = y + (box_h - text_block_h) / 2 + 12
            text_svg = "".join(
                f"<text x='{cx}' y='{text_start_y + j * line_h}' text-anchor='middle' "
                f"font-family='system-ui,sans-serif' font-size='12.5' fill='rgba(230,237,245,0.92)' font-weight='500'>{ln}</text>"
                for j, ln in enumerate(text_lines)
            )
            num_badge = (
                f"<circle cx='{pad_x + 18}' cy='{y + box_h / 2}' r='12' fill='{border}' opacity='0.25'/>"
                f"<text x='{pad_x + 18}' y='{y + box_h / 2 + 4.5}' text-anchor='middle' "
                f"font-family='system-ui,sans-serif' font-size='11' fill='{border}' font-weight='700'>{i + 1}</text>"
            )
            boxes += (
                f"<rect x='{pad_x}' y='{y}' width='{box_w}' height='{box_h}' rx='{rx}' "
                f"fill='{bg}' stroke='{border}' stroke-width='1.5'/>"
                f"{num_badge}{text_svg}"
            )
            if i < n - 1:
                ay1 = y + box_h
                ay2 = ay1 + gap + arrow_h
                amid = (ay1 + ay2) / 2
                boxes += (
                    f"<line x1='{cx}' y1='{ay1 + 2}' x2='{cx}' y2='{ay2 - 8}' "
                    f"stroke='rgba(148,163,184,0.45)' stroke-width='2' stroke-dasharray='6,4'/>"
                    f"<polygon points='{cx - 5},{ay2 - 12} {cx},{ay2 - 4} {cx + 5},{ay2 - 12}' "
                    f"fill='rgba(148,163,184,0.55)'/>"
                )
        desc_svg = ""
        if desc:
            desc_svg = (
                f"<text x='{cx}' y='28' text-anchor='middle' font-family='system-ui,sans-serif' "
                f"font-size='13' fill='rgba(180,195,210,0.65)' font-style='italic'>{desc}</text>"
            )
        diagram_svg = (
            f"<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 {svg_w} {total_h}' "
            f"style='width:100%;height:auto;display:block;'>"
            f"{desc_svg}{boxes}</svg>"
        )
        title_html = f"<div style='{title_style}'>{title}</div>" if title else ""
        return f"<div style='{card}'>{title_html}{diagram_svg}</div>"

    labels = data.get("x" if visual_type == "graph" else "labels", [])
    if not isinstance(labels, list):
        labels = []
    labels = [str(x) for x in labels][:8]
    vals = _to_num_list(data.get("y" if visual_type == "graph" else "values", []))[:8]
    if len(labels) == 0 or len(vals) == 0:
        return ""
    n = min(len(labels), len(vals))
    labels, vals = labels[:n], vals[:n]
    mn, mx = min(vals), max(vals)
    if abs(mx - mn) < 1e-9:
        mx = mn + 1.0

    w, h = 500, 210
    l, r, t, b = 36, 14, 14, 30
    pw, ph = w - l - r, h - t - b

    def x_at(i: int) -> float:
        return l + (i * (pw / (max(1, n - 1) if visual_type == "graph" else n))) + (0 if visual_type == "graph" else pw / (n * 2))

    def y_at(v: float) -> float:
        return t + (mx - v) * ph / (mx - mn)

    if visual_type == "graph":
        pts = " ".join(f"{x_at(i):.1f},{y_at(v):.1f}" for i, v in enumerate(vals))
        circles = "".join(
            f"<circle cx='{x_at(i):.1f}' cy='{y_at(v):.1f}' r='3.5' fill='rgba(120,175,255,0.95)'/>" for i, v in enumerate(vals)
        )
        xlabels = "".join(
            f"<text x='{x_at(i):.1f}' y='{h-8}' text-anchor='middle' font-size='10' fill='rgba(170,182,196,0.75)'>{_esc_html(lbl)}</text>"
            for i, lbl in enumerate(labels)
        )
        svg = (
            f"<svg viewBox='0 0 {w} {h}' style='width:100%;height:auto;display:block;'>"
            f"<line x1='{l}' y1='{h-b}' x2='{w-r}' y2='{h-b}' stroke='rgba(255,255,255,.12)'/>"
            f"<line x1='{l}' y1='{t}' x2='{l}' y2='{h-b}' stroke='rgba(255,255,255,.12)'/>"
            f"<polyline fill='none' stroke='rgba(120,175,255,0.9)' stroke-width='2.2' points='{pts}'/>"
            f"{circles}{xlabels}</svg>"
        )
    else:
        bar_w = pw / max(1, n) * 0.62
        rects = "".join(
            f"<rect x='{x_at(i)-bar_w/2:.1f}' y='{y_at(v):.1f}' width='{bar_w:.1f}' height='{(h-b)-y_at(v):.1f}' rx='5' fill='rgba(120,175,255,0.78)'/>"
            for i, v in enumerate(vals)
        )
        xlabels = "".join(
            f"<text x='{x_at(i):.1f}' y='{h-8}' text-anchor='middle' font-size='10' fill='rgba(170,182,196,0.75)'>{_esc_html(lbl)}</text>"
            for i, lbl in enumerate(labels)
        )
        svg = (
            f"<svg viewBox='0 0 {w} {h}' style='width:100%;height:auto;display:block;'>"
            f"<line x1='{l}' y1='{h-b}' x2='{w-r}' y2='{h-b}' stroke='rgba(255,255,255,.12)'/>"
            f"<line x1='{l}' y1='{t}' x2='{l}' y2='{h-b}' stroke='rgba(255,255,255,.12)'/>"
            f"{rects}{xlabels}</svg>"
        )

    title_html = f"<div style='{title_style}'>{title}</div>" if title else ""
    return f"<div style='{card}'>{title_html}{svg}</div>"


def _sniff_image_mime(file_bytes: bytes) -> str:
    if file_bytes.startswith(b"\x89PNG\r\n\x1a\n"):
        return "image/png"
    if file_bytes.startswith(b"\xff\xd8\xff"):
        return "image/jpeg"
    if file_bytes[:4] == b"RIFF" and file_bytes[8:12] == b"WEBP":
        return "image/webp"
    # ISO BMFF family (HEIC/HEIF) used by some mobile cameras.
    if len(file_bytes) >= 12 and file_bytes[4:8] == b"ftyp":
        brand = file_bytes[8:12]
        if brand in {b"heic", b"heix", b"hevc", b"hevx"}:
            return "image/heic"
        if brand in {b"mif1", b"msf1"}:
            return "image/heif"
    return ""


def _is_allowed_image_upload(filename: str, mime_type: str, file_bytes: bytes) -> bool:
    suffix = Path(filename or "").suffix.lower()
    claimed_mime = (mime_type or "").lower().strip()
    detected_mime = _sniff_image_mime(file_bytes)
    if claimed_mime and claimed_mime not in ALLOWED_IMAGE_TYPES and not claimed_mime.startswith("image/"):
        return False
    if not detected_mime:
        return False
    if suffix in ALLOWED_IMAGE_EXTENSIONS:
        if suffix in {".jpg", ".jpeg"} and detected_mime != "image/jpeg":
            return False
        if suffix == ".png" and detected_mime != "image/png":
            return False
        if suffix == ".webp" and detected_mime != "image/webp":
            return False
    else:
        # Mobile camera capture sometimes provides no/odd extension. Trust content sniff.
        if detected_mime not in {"image/png", "image/jpeg", "image/webp", "image/heic", "image/heif"}:
            return False
    return True


def _is_allowed_document_upload(filename: str, mime_type: str) -> bool:
    suffix = Path(filename or "").suffix.lower()
    mime = (mime_type or "").lower().strip()
    if suffix not in ALLOWED_DOCUMENT_EXTENSIONS:
        return False
    if suffix == ".pdf":
        return mime in {"", "application/pdf", "application/x-pdf", "application/octet-stream"}
    if suffix == ".docx":
        return mime in {
            "",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            "application/zip",
            "application/octet-stream",
        }
    if suffix == ".txt":
        return mime == "" or mime.startswith("text/") or mime == "application/octet-stream"
    return mime in ALLOWED_DOCUMENT_TYPES


def _clean_document_text(text: str) -> str:
    cleaned = (text or "").replace("\r\n", "\n").replace("\r", "\n")
    cleaned = "\n".join(
        re.sub(r"[ \t]+", " ", line).strip()
        for line in cleaned.split("\n")
    )
    cleaned = re.sub(r"\n{3,}", "\n\n", cleaned)
    return cleaned.strip()


def _cap_document_text(text: str) -> str:
    if len(text) <= MAX_DOCUMENT_TEXT_CHARS:
        return text
    truncated = text[:MAX_DOCUMENT_TEXT_CHARS].rsplit(" ", 1)[0].rstrip()
    if not truncated:
        truncated = text[:MAX_DOCUMENT_TEXT_CHARS].rstrip()
    return f"{truncated}\n\n[Document text truncated]"


def _extract_pdf_text_with_ocr(file_bytes: bytes) -> str:
    if fitz is None or not _openrouter_llm_ready() or not file_bytes:
        return ""

    try:
        doc = fitz.open(stream=file_bytes, filetype="pdf")
    except Exception as e:
        logger.error(f"PDF_OCR_OPEN_ERROR: {e}")
        return ""

    parts: list[str] = []
    total_chars = 0

    try:
        for page_index in range(min(doc.page_count, PDF_OCR_MAX_PAGES)):
            page = doc.load_page(page_index)
            pix = page.get_pixmap(matrix=fitz.Matrix(2, 2), alpha=False)
            ocr_text = (_openrouter_read_image(pix.tobytes("png"), "image/png", PDF_OCR_PROMPT) or "").strip()
            if not ocr_text or ocr_text in {RATE_LIMIT_UI_MESSAGE, GENERIC_ERROR_UI_MESSAGE, "API not ready"}:
                continue
            parts.append(ocr_text)
            total_chars += len(ocr_text)
            if total_chars >= MAX_DOCUMENT_TEXT_CHARS:
                break
    except Exception as e:
        logger.error(f"PDF_OCR_ERROR: {e}")
        return ""
    finally:
        doc.close()

    return _clean_document_text("\n\n".join(parts))


def _extract_pdf_text(file_bytes: bytes) -> str:
    if fitz is None:
        logger.warning("PyMuPDF is not installed - PDF support disabled")
        return DOCUMENT_READ_ERROR_MESSAGE

    if not file_bytes:
        logger.debug("PDF extract called with empty bytes")
        return DOCUMENT_READ_ERROR_MESSAGE

    try:
        logger.debug(f"PDF byte length: {len(file_bytes)}")
        logger.debug(f"PDF first 8 bytes: {file_bytes[:8]}")

        doc = fitz.open(stream=file_bytes, filetype="pdf")
        parts = []

        try:
            for page_index in range(doc.page_count):
                page = doc.load_page(page_index)
                txt = (page.get_text("text") or "").strip()
                logger.debug(f"PDF page {page_index} text length: {len(txt)}")
                if txt:
                    parts.append(txt)
        finally:
            doc.close()

        text = _clean_document_text("\n\n".join(parts))
        if text:
            return text

        ocr_text = _extract_pdf_text_with_ocr(file_bytes)
        if ocr_text:
            logger.debug(f"PDF OCR fallback text length: {len(ocr_text)}")
            return ocr_text

        return PDF_NO_TEXT_MESSAGE
    except Exception as e:
        logger.error(f"PDF_EXTRACT_ERROR: {e}")
        return DOCUMENT_READ_ERROR_MESSAGE


def _extract_docx_text(file_bytes: bytes) -> str:
    if DocxDocument is None:
        return DOCUMENT_READ_ERROR_MESSAGE
    try:
        doc = DocxDocument(BytesIO(file_bytes))
        parts = [paragraph.text for paragraph in doc.paragraphs if (paragraph.text or "").strip()]
        for table in doc.tables:
            for row in table.rows:
                row_text = " | ".join((cell.text or "").strip() for cell in row.cells if (cell.text or "").strip())
                if row_text:
                    parts.append(row_text)
        cleaned = _clean_document_text("\n".join(parts))
        return cleaned or DOCUMENT_EMPTY_TEXT_MESSAGE
    except Exception:
        return DOCUMENT_READ_ERROR_MESSAGE


def _extract_txt_text(file_bytes: bytes) -> str:
    text = ""
    for encoding in ("utf-8-sig", "utf-8", "utf-16", "latin-1"):
        try:
            text = file_bytes.decode(encoding)
            break
        except UnicodeDecodeError:
            continue
    if not text:
        text = file_bytes.decode("utf-8", errors="ignore")
    cleaned = _clean_document_text(text)
    return cleaned or DOCUMENT_EMPTY_TEXT_MESSAGE


def _extract_document_text(file_bytes: bytes, filename: str, mime_type: str) -> str:
    suffix = Path(filename or "").suffix.lower()
    mime = (mime_type or "").lower().strip()
    
    # Updated routing logic
    is_pdf = mime == "application/pdf" or (filename or "").lower().endswith(".pdf")
    is_docx = suffix == ".docx" or mime == "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    is_txt = suffix == ".txt" or mime.startswith("text/")

    if is_pdf:
        extracted = _extract_pdf_text(file_bytes)
    elif is_docx:
        extracted = _extract_docx_text(file_bytes)
    elif is_txt:
        extracted = _extract_txt_text(file_bytes)
    else:
        return DOCUMENT_UNSUPPORTED_MESSAGE

    if extracted in DOCUMENT_FAILURE_MESSAGES:
        return extracted
        
    cleaned = _clean_document_text(extracted)
    if not cleaned:
        return PDF_NO_TEXT_MESSAGE if is_pdf else DOCUMENT_EMPTY_TEXT_MESSAGE
    return _cap_document_text(cleaned)


MEDIA_ROUTE_PREFIX = "/media/chat"
CHAT_MEDIA_ROOT = Path(__file__).resolve().parent.parent / ".chat_media"


def _safe_filename_fragment(name: str) -> str:
    cleaned = re.sub(r"[^A-Za-z0-9._-]+", "-", (name or "").strip())
    cleaned = cleaned.strip(".-")
    return cleaned[:80] or "file"


def _store_note_attachment(uid: int, bucket: str, filename: str, file_bytes: bytes) -> str:
    """Write note attachment under .chat_media/{uid}/notes/{bucket}/. Returns relative path (no /media/chat prefix)."""
    suffix = Path(filename or "").suffix.lower()[:12]
    stem = _safe_filename_fragment(Path(filename or "file").stem)
    tok = secrets.token_hex(8)
    rel_dir = Path(str(uid)) / "notes" / (bucket or "misc")
    target_dir = CHAT_MEDIA_ROOT / rel_dir
    target_dir.mkdir(parents=True, exist_ok=True)
    stored_name = f"{stem}-{tok}{suffix}"
    target_path = target_dir / stored_name
    target_path.write_bytes(file_bytes)
    return f"{rel_dir.as_posix()}/{stored_name}"


def _delete_note_attachment_paths(uid: int, rel_paths: list[str]) -> None:
    root = CHAT_MEDIA_ROOT.resolve()
    for rel in rel_paths:
        p = (CHAT_MEDIA_ROOT / rel).resolve()
        if str(p).startswith(str(root)) and p.is_file():
            try:
                p.unlink()
            except OSError:
                pass


def _classify_note_attachment(filename: str, content_type: str, file_bytes: bytes, expect: str) -> tuple[str, str, str] | tuple[None, None, str]:
    """Returns (storage_kind, mime, error). storage_kind is image|audio|video|file."""
    name = filename or "file"
    suffix = Path(name).suffix.lower()
    if suffix in NOTE_UPLOAD_BLOCKED_EXT:
        return None, None, "That file type is not allowed for security reasons."
    if len(file_bytes) > MAX_NOTE_ATTACHMENT_BYTES:
        return None, None, f"File too large (max {MAX_NOTE_ATTACHMENT_BYTES // (1024 * 1024)} MB)."
    if expect == "image":
        if not _is_allowed_image_upload(name, content_type, file_bytes):
            return None, None, "Use a real PNG, JPG, WebP, HEIC, or HEIF image."
        mime = _sniff_image_mime(file_bytes) or content_type or "image/png"
        return "image", mime, ""
    if expect == "audio":
        if suffix not in NOTE_AUDIO_EXTENSIONS and suffix != ".webm":
            return None, None, "Use MP3, WAV, M4A, OGG, FLAC, or WebM audio."
        mime = SAFE_MEDIA_TYPES.get(suffix, content_type or "application/octet-stream")
        if suffix == ".webm":
            mime = "audio/webm"
        return "audio", mime, ""
    if expect == "file":
        if suffix in NOTE_AUDIO_EXTENSIONS:
            return None, None, "Add audio with the same Media control (pick an audio file)."
        if suffix in ALLOWED_IMAGE_EXTENSIONS:
            return None, None, "Add images with the same Media control (pick an image file)."
        if suffix not in NOTE_FILE_EXTENSIONS:
            return None, None, "Unsupported type. Try PDF, Office, ZIP, JSON, CSV, MD, MP4, or WebM."
        mime = SAFE_MEDIA_TYPES.get(suffix, content_type or "application/octet-stream")
        kind: str = "file"
        if suffix in NOTE_VIDEO_EXTENSIONS:
            kind = "video"
        return kind, mime, ""
    return None, None, "Invalid upload."


def _note_media_upload_expect(filename: str, content_type: str) -> str:
    """Pick classify channel for unified note media upload: image | audio | file."""
    name = filename or "file"
    suffix = Path(name).suffix.lower()
    ct = (content_type or "").lower().strip()
    if suffix in ALLOWED_IMAGE_EXTENSIONS or ct.startswith("image/"):
        return "image"
    if suffix in NOTE_VIDEO_EXTENSIONS:
        return "file"
    if suffix in NOTE_AUDIO_EXTENSIONS or suffix == ".webm":
        return "audio"
    if ct.startswith("audio/"):
        return "audio"
    if ct.startswith("video/"):
        return "file"
    return "file"


def _store_chat_media(uid: int, session_id: str, filename: str, file_bytes: bytes) -> str:
    suffix = Path(filename or "").suffix.lower()[:12]
    stem = _safe_filename_fragment(Path(filename or "file").stem)
    token = secrets.token_hex(12)
    rel_dir = Path(str(uid)) / str(session_id)
    target_dir = CHAT_MEDIA_ROOT / rel_dir
    target_dir.mkdir(parents=True, exist_ok=True)
    stored_name = f"{stem}-{token}{suffix}"
    target_path = target_dir / stored_name
    target_path.write_bytes(file_bytes)
    return f"{MEDIA_ROUTE_PREFIX}/{rel_dir.as_posix()}/{stored_name}"


def _safe_chat_media_type(path: Path) -> str:
    return SAFE_MEDIA_TYPES.get(path.suffix.lower(), "")


def _normalize_person_name(name: str) -> str:
    cleaned = re.sub(r"\s+", " ", (name or "").strip().lower())
    if not cleaned:
        return ""
    return re.sub(r"(^|[\s'-])([a-z])", lambda m: m.group(1) + m.group(2).upper(), cleaned)


def _extract_person_name(*texts: str) -> str:
    patterns = (
        r"\b(?:student name|name)\s*[:=-]\s*([A-Za-z][A-Za-z'-]*(?:\s+[A-Za-z][A-Za-z'-]*){0,2})\b",
        r"\b(?:hi|hello|hey)\s*,?\s*([A-Za-z][A-Za-z'-]*)\b(?=[,.!?]|$)",
        r"let'?s get started,\s*([A-Za-z][A-Za-z'-]*)\b(?=[,.!?]|$)",
        r"\bcall(?:ing)?\s+(?:the student\s+)?([A-Za-z][A-Za-z'-]*(?:\s+[A-Za-z][A-Za-z'-]*){0,2})\b(?=[,.!?]|$)",
    )
    for text in texts:
        raw = (text or "").strip()
        if not raw:
            continue
        normalized = _normalize_person_name(raw)
        # Treat short alphabetic phrases as explicit names, including multi-word names like "Neo Alexs".
        if (
            normalized
            and normalized.lower() not in {"student", "user"}
            and re.fullmatch(r"[A-Za-z][A-Za-z'-]*(?:\s+[A-Za-z][A-Za-z'-]*){0,2}", raw)
        ):
            return normalized
        for pattern in patterns:
            match = re.search(pattern, raw, re.IGNORECASE)
            if not match:
                continue
            candidate = _normalize_person_name(match.group(1))
            if candidate and candidate.lower() not in {"student", "user"}:
                return candidate
    return ""


def friendly_llm_error(e: Exception) -> str:
    logger.error(f"LLM API error: {e}")
    s = str(e)
    if _is_rate_limit_text(s) or " 429" in s.lower():
        return RATE_LIMIT_UI_MESSAGE
    return GENERIC_ERROR_UI_MESSAGE


# ----------------------------
# Web search
# ----------------------------
_WEB_SEARCH_KEYWORDS = re.compile(
    r"\b(search|look\s*up|google|find\s+online|latest|recent|current|newest|"
    r"what\s+is\s+new|2024|2025|2026|trending|news|update|release|version|"
    r"announced|just\s+came\s+out|browse|web\s+search)\b",
    re.IGNORECASE,
)


def _needs_web_search(text: str) -> bool:
    return bool(_WEB_SEARCH_KEYWORDS.search(text))


def _web_search(query: str, max_results: int = 5) -> str:
    if DDGS is None:
        return ""
    try:
        with DDGS() as ddgs:
            results = list(ddgs.text(query, max_results=max_results))
        if not results:
            return ""
        lines = []
        for i, r in enumerate(results, 1):
            title = r.get("title", "")
            body = r.get("body", "")
            href = r.get("href", "")
            lines.append(f"{i}. {title}\n   {body}\n   Source: {href}")
        return "\n".join(lines)
    except Exception as e:
        print(f"[Web Search] error: {e}")
        return ""


class _LLMTextResponse:
    __slots__ = ("text",)

    def __init__(self, text: str = ""):
        self.text = text


def _openrouter_complete(
    model: str,
    messages: list[dict[str, Any]],
    max_tokens: int = 2048,
    temperature: float | None = None,
) -> _LLMTextResponse:
    if not OPENROUTER_API_KEY:
        return _LLMTextResponse("API not ready")
    url = "https://openrouter.ai/api/v1/chat/completions"
    payload: dict[str, Any] = {"model": model, "messages": messages, "max_tokens": max_tokens}
    if temperature is not None:
        payload["temperature"] = temperature
    try:
        with httpx.Client(timeout=httpx.Timeout(120.0, read=120.0)) as http:
            r = http.post(url, headers=_openrouter_headers(), json=payload)
            if r.status_code != 200:
                return _LLMTextResponse(_friendly_openrouter_http_error(r.status_code, r.content))
            data = r.json()
            msg = (data.get("choices") or [{}])[0].get("message") or {}
            content = msg.get("content") or ""
            return _LLMTextResponse(content or "")
    except Exception as e:
        return _LLMTextResponse(friendly_llm_error(e))


def _openrouter_generate_user_prompt(model: str, contents: str, max_tokens: int = 2048) -> Any:
    """Non-streaming completion with a single user message (replaces legacy Groq helper)."""
    return _openrouter_complete(model, [{"role": "user", "content": contents}], max_tokens=max_tokens)


def _openrouter_generate_with_fallback(
    primary_model: str, contents: str, max_tokens: int = 2048,
    fallback_model: str = OPENROUTER_AUX_FALLBACK_MODEL,
) -> Any:
    """Try primary model first. If rate-limited or returns rate-limit text, retry with fallback."""
    try:
        resp = _openrouter_generate_user_prompt(primary_model, contents, max_tokens)
        text = (getattr(resp, "text", "") or "").strip()
        if text and not _is_rate_limit_text(text):
            return resp
        logger.warning(
            "Primary model %s rate-limited or empty; falling back to %s",
            primary_model, fallback_model,
        )
    except Exception as e:
        logger.warning("Primary model %s failed (%s); trying fallback %s", primary_model, e, fallback_model)
    return _openrouter_generate_user_prompt(fallback_model, contents, max_tokens)


