def _teaching_message_suggests_concept_figure(user_msg: str, response_text: str) -> bool:
    """Heuristic: topic + answer text suggest a concept diagram would help (no extra user keywords)."""
    if not ALEX_TEACHING_AUTO_SVG:
        return False
    u = (user_msg or "").lower()
    r = (response_text or "").lower()
    if len(response_text or "") < 360:
        return False
    hints = (
        "circuit", "logic gate", "boolean", "transistor", "capacitor", "resistor", "amplifier",
        "free-body", "free body", "vector", "velocity", "acceleration", "momentum", "force ",
        "newton", "torque", "friction", "projectile",
        "cell membrane", "mitochondria", "dna ", "rna ", "protein", "enzyme", "photosynthesis",
        "neuron", "synapse", "heart ", "lung ", "kidney", "blood ",
        "osi ", "tcp/ip", "tcpip", "packet", "router", "subnet",
        "stack ", "heap ", "queue", "binary tree", "linked list", "hash table", "graph ",
        "recursion", "big-o", "sorting algorithm",
        "lifecycle", "waterfall", "feedback loop", "state machine",
        "derivative", "integral", "triangle", "geometry", "coordinate",
        "block cipher", "encryption", "hash function",
        "string theory", "brane", "extra dimensions", "compactification", "spacetime", "space-time",
        "general relativity", "curvature", "quantum gravity", "wormhole", "black hole",
    )
    return any(h in u or h in r for h in hints)


def _strip_think_tags(text: str) -> str:
    """Remove model reasoning wrappers from assistant-visible text (e.g. DeepSeek R1)."""
    if not text:
        return ""
    t = text
    t = re.sub(r"<think>.*?</think>", "", t, flags=re.DOTALL | re.IGNORECASE)
    t = re.sub(r"<redacted_thinking>.*?</redacted_thinking>", "", t, flags=re.DOTALL | re.IGNORECASE)
    return t.strip()


def _postprocess_svg(svg: str) -> str:
    """Clean up model-generated SVG: remove comments, fix common issues."""
    if not svg:
        return ""
    svg = re.sub(r"<!--.*?-->", "", svg, flags=re.DOTALL)
    svg = re.sub(r"<!\[CDATA\[.*?\]\]>", "", svg, flags=re.DOTALL)
    svg = re.sub(r"(?is)<style[^>]*>.*?</style>", "", svg)
    svg = re.sub(r"\s+", " ", svg).strip()
    return _sanitize_svg_markup(svg)


def _openrouter_generate_svg(subject: str, *, teaching_context: str = "") -> str:
    """Generate an educational SVG via OpenRouter (multi-attempt, picks best-scoring output)."""
    if not OPENROUTER_API_KEY:
        return ""
    subj = (subject or "").strip()[:240]
    if not subj:
        return ""
    lines = [
        f"Create a clear educational diagram or illustration for: {subj}",
        "Prioritize teaching clarity over decoration.",
    ]
    ctx = (teaching_context or "").strip()
    if ctx:
        lines.append(f"Align labels and layout with this lesson excerpt:\n{ctx[:900]}")
    prompt = "\n".join(lines)
    best_svg = ""
    best_score = 0

    for attempt in range(3):
        try:
            retry_hint = ""
            if attempt > 0 and best_svg:
                retry_hint = (
                    "\nRefine: add more distinct labeled parts, stronger visual hierarchy, "
                    "and ensure viewBox uses the full 480x280 canvas."
                )
            elif attempt > 0:
                retry_hint = "\nUse more shapes and at least one short text label for the main concept."
            resp = _openrouter_complete(
                OPENROUTER_DRAW_MODEL,
                [
                    {"role": "system", "content": _SVG_DRAWING_SYSTEM_PROMPT},
                    {"role": "user", "content": prompt + retry_hint},
                ],
                max_tokens=4500,
                temperature=0.32 + attempt * 0.14,
            )
            raw = _strip_think_tags(resp.text or "")
            svg_match = re.search(r"<svg[^>]*>.*?</svg>", raw, re.DOTALL | re.IGNORECASE)
            if not svg_match:
                continue
            svg = _postprocess_svg(svg_match.group(0))
            if not svg:
                continue
            s = svg.lower()
            score = 0
            for token in ("<circle", "<ellipse", "<rect", "<path", "<polygon", "<line"):
                score += min(3, s.count(token))
            if "stroke-width" in s:
                score += 2
            if s.count("fill=") >= 4:
                score += 3
            elif s.count("fill=") >= 3:
                score += 2
            if "viewbox" in s and ("480" in s or "320" in s):
                score += 2
            if "<text" in s:
                score += min(4, s.count("<text"))
            if len(svg) > 550:
                score += 3
            elif len(svg) > 400:
                score += 2
            if "xmlns" in s:
                score += 1
            logger.info(f"SVG gen attempt {attempt+1}: score={score}, len={len(svg)}")
            if score > best_score:
                best_score = score
                best_svg = svg
            if score >= 12:
                break
        except Exception as e:
            logger.error(f"SVG generation error (attempt {attempt+1}): {e}")
            if attempt == 0:
                continue
            break

    return best_svg


def _openrouter_generate_user_prompt_svg(subject: str) -> str:
    """Wrapper for illustration blocks: subject-only pictorial SVG."""
    return _openrouter_generate_svg(subject, teaching_context="")


def _openrouter_generate_teaching_svg(user_msg: str, response_excerpt: str) -> str:
    """SVG aligned to user question + assistant explanation excerpt."""
    subj = (user_msg or "").strip()[:220]
    excerpt = (response_excerpt or "").strip()[:1200]
    if not subj:
        return ""
    return _openrouter_generate_svg(subj, teaching_context=excerpt)


_SCHEMATIC_SPEC_SYSTEM_PROMPT = """You create compact JSON specs for educational schematic diagrams.
Return ONLY valid JSON (no markdown, no prose).

Schema:
{
  "title": "short title",
  "caption": "one sentence takeaway",
  "nodes": [
    {"id":"n1","label":"Object A","shape":"rect|circle|diamond","color":"#93c5fd"},
    {"id":"n2","label":"Object B","shape":"rect|circle|diamond","color":"#86efac"}
  ],
  "arrows": [
    {"from":"n1","to":"n2","label":"Action force","color":"#ef4444"},
    {"from":"n2","to":"n1","label":"Reaction force","color":"#3b82f6"}
  ]
}

Rules:
- 2 to 6 nodes, 1 to 8 arrows
- ids must be unique and referenced by arrows
- labels must be short (max 6 words)
- use hex colors
- keep output under 1400 characters
"""


def _openrouter_generate_teaching_spec(topic: str) -> dict[str, Any] | None:
    if not OPENROUTER_API_KEY:
        return None
    user_prompt = (
        f"Create a JSON schematic spec for teaching this topic: {topic}\n"
        "Use simple conceptual objects and directional relationships. /no_think"
    )
    try:
        resp = _openrouter_complete(
            OPENROUTER_SPEC_MODEL,
            [
                {"role": "system", "content": _SCHEMATIC_SPEC_SYSTEM_PROMPT},
                {"role": "user", "content": user_prompt},
            ],
            max_tokens=3000,
            temperature=0.2,
        )
        raw = _strip_think_tags(resp.text or "")
        json_slice, _ = _extract_json_object_slice(raw, 0)
        if not json_slice:
            return None
        parsed = json.loads(json_slice)
        if not isinstance(parsed, dict):
            return None
        nodes = parsed.get("nodes")
        arrows = parsed.get("arrows")
        if not isinstance(nodes, list) or not isinstance(arrows, list):
            return None
        return _sanitize_teaching_spec(topic, parsed)
    except Exception as e:
        logger.error(f"Teaching spec generation error: {e}")
        return None


_GENERIC_DIAGRAM_LABELS = {
    "input", "inputs", "output", "outputs", "calculate", "calculates",
    "calculation", "process", "step", "steps", "data", "result", "results",
    "value", "values", "info", "information",
}


def _is_generic_diagram_label(label: str) -> bool:
    low = (label or "").strip().lower()
    if not low:
        return True
    if low in _GENERIC_DIAGRAM_LABELS:
        return True
    return low in {"node", "object", "item", "thing", "concept"}


def _sanitize_teaching_spec(topic: str, spec: dict[str, Any]) -> dict[str, Any]:
    topic_low = (topic or "").lower()
    is_newton_second = ("newton" in topic_low) and ("second" in topic_low or "2nd" in topic_low)
    raw_nodes = spec.get("nodes", [])
    raw_arrows = spec.get("arrows", [])
    if not isinstance(raw_nodes, list):
        raw_nodes = []
    if not isinstance(raw_arrows, list):
        raw_arrows = []

    cleaned_nodes: list[dict[str, Any]] = []
    for item in raw_nodes[:8]:
        if not isinstance(item, dict):
            continue
        node_id = str(item.get("id", "")).strip() or f"n{len(cleaned_nodes)+1}"
        label = str(item.get("label", "")).strip()[:40]
        shape = str(item.get("shape", "rect")).strip().lower()
        color = str(item.get("color", "#93c5fd")).strip()
        if shape not in {"rect", "circle", "diamond"}:
            shape = "rect"
        if not re.fullmatch(r"#[0-9a-fA-F]{6}", color):
            color = "#93c5fd"
        if not label or _is_generic_diagram_label(label):
            continue
        cleaned_nodes.append({"id": node_id, "label": label, "shape": shape, "color": color})

    if len(cleaned_nodes) < 2:
        cleaned_nodes = []
        for i, item in enumerate(raw_nodes[:4]):
            if not isinstance(item, dict):
                continue
            node_id = str(item.get("id", "")).strip() or f"n{i+1}"
            label = str(item.get("label", "")).strip()[:40]
            shape = str(item.get("shape", "rect")).strip().lower()
            color = str(item.get("color", "#93c5fd")).strip()
            if not label or _is_generic_diagram_label(label):
                label = f"Concept {i+1}"
            if shape not in {"rect", "circle", "diamond"}:
                shape = "rect"
            if not re.fullmatch(r"#[0-9a-fA-F]{6}", color):
                color = "#93c5fd"
            cleaned_nodes.append({"id": node_id, "label": label, "shape": shape, "color": color})

    if "law" in topic_low:
        cleaned_nodes = cleaned_nodes[:4]

    if is_newton_second:
        has_equation = any("f = m" in n["label"].lower().replace("×", "x") or "f=ma" in n["label"].lower().replace(" ", "") for n in cleaned_nodes)
        if not has_equation:
            cleaned_nodes.append({"id": "eq", "label": "F = m × a", "shape": "diamond", "color": "#fde68a"})
        cleaned_nodes = cleaned_nodes[:4]

    valid_ids = {n["id"] for n in cleaned_nodes}
    cleaned_arrows: list[dict[str, Any]] = []
    for i, item in enumerate(raw_arrows[:10]):
        if not isinstance(item, dict):
            continue
        src = str(item.get("from", "")).strip()
        dst = str(item.get("to", "")).strip()
        if src not in valid_ids or dst not in valid_ids or src == dst:
            continue
        label = str(item.get("label", "")).strip()[:44]
        if not label or _is_generic_diagram_label(label):
            label = "affects"
        color = str(item.get("color", "")).strip()
        if not re.fullmatch(r"#[0-9a-fA-F]{6}", color):
            color = "#ef4444" if i % 2 == 0 else "#3b82f6"
        cleaned_arrows.append({"from": src, "to": dst, "label": label, "color": color})

    if is_newton_second:
        eq_exists = any(n["id"] == "eq" for n in cleaned_nodes)
        if eq_exists:
            base_ids = [n["id"] for n in cleaned_nodes if n["id"] != "eq"][:2]
            for bid in base_ids:
                if not any(a["from"] == bid and a["to"] == "eq" for a in cleaned_arrows):
                    cleaned_arrows.append({"from": bid, "to": "eq", "label": "contributes", "color": "#3b82f6"})

    # Canonicalize Newton's 2nd law to a clean deterministic concept map.
    if is_newton_second:
        cleaned_nodes = [
            {"id": "m", "label": "Mass (m)", "shape": "rect", "color": "#93c5fd"},
            {"id": "a", "label": "Acceleration (a)", "shape": "rect", "color": "#86efac"},
            {"id": "eq", "label": "F = m × a", "shape": "diamond", "color": "#fde68a"},
            {"id": "f", "label": "Force (F)", "shape": "rect", "color": "#fca5a5"},
        ]
        cleaned_arrows = [
            {"from": "m", "to": "eq", "label": "m term", "color": "#3b82f6"},
            {"from": "a", "to": "eq", "label": "a term", "color": "#10b981"},
            {"from": "eq", "to": "f", "label": "compute F", "color": "#ef4444"},
        ]
        cleaned_title = "Newton's 2nd Law"
        cleaned_caption = "Net force equals mass times acceleration."
    else:
        cleaned_title = str(spec.get("title", "")).strip()[:80] or (topic.strip().title()[:80] or "Concept Diagram")
        cleaned_caption = str(spec.get("caption", "")).strip()[:140]
        if not cleaned_caption:
            cleaned_caption = "Follow the arrows to understand how concepts connect."

    if not cleaned_arrows and len(cleaned_nodes) >= 2:
        cleaned_arrows.append({"from": cleaned_nodes[0]["id"], "to": cleaned_nodes[1]["id"], "label": "affects", "color": "#ef4444"})

    return {
        "title": cleaned_title,
        "caption": cleaned_caption,
        "nodes": cleaned_nodes,
        "arrows": cleaned_arrows[:8],
    }


def _render_schematic_spec_svg(spec: dict[str, Any]) -> str:
    title = str(spec.get("title", "Concept Diagram")).strip()[:80] or "Concept Diagram"
    caption = str(spec.get("caption", "")).strip()[:140]
    raw_nodes = spec.get("nodes", [])
    raw_arrows = spec.get("arrows", [])
    if not isinstance(raw_nodes, list) or not raw_nodes:
        return ""

    nodes: list[dict[str, Any]] = []
    for item in raw_nodes[:6]:
        if not isinstance(item, dict):
            continue
        node_id = str(item.get("id", "")).strip()
        label = str(item.get("label", node_id or "Node")).strip()[:40] or "Node"
        shape = str(item.get("shape", "rect")).strip().lower()
        if shape not in {"rect", "circle", "diamond"}:
            shape = "rect"
        color = str(item.get("color", "#93c5fd")).strip()
        if not re.fullmatch(r"#[0-9a-fA-F]{6}", color):
            color = "#93c5fd"
        if not node_id:
            node_id = f"n{len(nodes) + 1}"
        nodes.append({"id": node_id, "label": label, "shape": shape, "color": color})
    if not nodes:
        return ""

    n = len(nodes)
    if n == 1:
        layout = [(300, 210)]
    elif n == 2:
        layout = [(170, 210), (430, 210)]
    elif n == 3:
        layout = [(120, 210), (300, 210), (480, 210)]
    elif n == 4:
        layout = [(170, 155), (430, 155), (170, 265), (430, 265)]
    else:
        layout = [(120, 155), (300, 155), (480, 155), (120, 265), (300, 265), (480, 265)][:n]

    node_pos: dict[str, tuple[float, float]] = {}
    shape_parts: list[str] = []
    for i, node in enumerate(nodes):
        cx, cy = layout[i]
        node_pos[node["id"]] = (cx, cy)
        label = _esc_html(node["label"])
        color = node["color"]
        shape = node["shape"]
        if shape == "circle":
            shape_parts.append(
                f"<circle cx='{cx}' cy='{cy}' r='40' fill='{color}' stroke='#1e293b' stroke-width='3'/>"
            )
        elif shape == "diamond":
            points = f"{cx},{cy-44} {cx+54},{cy} {cx},{cy+44} {cx-54},{cy}"
            shape_parts.append(
                f"<polygon points='{points}' fill='{color}' stroke='#1e293b' stroke-width='3'/>"
            )
        else:
            shape_parts.append(
                f"<rect x='{cx-68}' y='{cy-26}' width='136' height='52' rx='12' fill='{color}' stroke='#1e293b' stroke-width='3'/>"
            )
        
        label_fs = '13' if len(label) < 18 else '11'
        shape_parts.append(
            f"<text x='{cx}' y='{cy+4}' text-anchor='middle' font-family='sans-serif' font-size='{label_fs}' fill='#0f172a' font-weight='700'>{label}</text>"
        )

    arrow_parts: list[str] = []
    legend_entries: list[tuple[str, str]] = []
    seen_pairs = 0
    arrow_colors = ["#ef4444", "#3b82f6", "#10b981", "#f59e0b", "#8b5cf6", "#ec4899", "#06b6d4", "#84cc16"]
    for item in raw_arrows[:8]:
        if not isinstance(item, dict):
            continue
        src = str(item.get("from", "")).strip()
        dst = str(item.get("to", "")).strip()
        if src not in node_pos or dst not in node_pos or src == dst:
            continue
        x1, y1 = node_pos[src]
        x2, y2 = node_pos[dst]
        color = str(item.get("color", "")).strip()
        if not re.fullmatch(r"#[0-9a-fA-F]{6}", color):
            color = arrow_colors[seen_pairs % len(arrow_colors)]
        label = _esc_html(str(item.get("label", "relation")).strip()[:44] or "relation")

        dx = x2 - x1
        dy_raw = y2 - y1
        length = (dx**2 + dy_raw**2) ** 0.5
        if length < 1:
            continue
        shrink = 45
        ratio_start = shrink / length
        ratio_end = 1 - shrink / length
        ax1 = x1 + dx * ratio_start
        ay1 = y1 + dy_raw * ratio_start
        ax2 = x1 + dx * ratio_end
        ay2 = y1 + dy_raw * ratio_end

        seg_l = ((ax2 - ax1) ** 2 + (ay2 - ay1) ** 2) ** 0.5
        if seg_l < 1e-6:
            continue
        ux, uy = (ax2 - ax1) / seg_l, (ay2 - ay1) / seg_l
        tip_back = 14.0
        stem_x2 = ax2 - ux * tip_back
        stem_y2 = ay2 - uy * tip_back
        bx, by = ax2 - ux * 5.5, ay2 - uy * 5.5
        px, py = -uy * 8.0, ux * 8.0
        arrow_parts.append(
            f"<line x1='{ax1:.1f}' y1='{ay1:.1f}' x2='{stem_x2:.1f}' y2='{stem_y2:.1f}' "
            f"stroke='{color}' stroke-width='4' stroke-linecap='round'/>"
        )
        arrow_parts.append(
            f"<polygon points='{ax2:.1f},{ay2:.1f} {bx+px:.1f},{by+py:.1f} {bx-px:.1f},{by-py:.1f}' "
            f"fill='{color}' stroke='#1e293b' stroke-width='1'/>"
        )
        legend_entries.append((color, label))
        seen_pairs += 1

    n_legends = len(legend_entries)
    legend_y_start = 340
    legend_parts: list[str] = []
    if n_legends > 0:
        cols = 2 if n_legends > 3 else 1
        col_w = 270
        start_x = [40, 310] if cols == 2 else [120]
        for idx, (lcolor, ltext) in enumerate(legend_entries):
            col = idx % cols
            row = idx // cols
            lx = start_x[col]
            ly = legend_y_start + row * 20
            legend_parts.append(
                f"<circle cx='{lx}' cy='{ly-4}' r='5' fill='{lcolor}'/>"
                f"<text x='{lx+12}' y='{ly}' font-family='sans-serif' font-size='12' fill='#334155'>{_esc_html(ltext)}</text>"
            )

    title_e = _esc_html(title)
    caption_e = _esc_html(caption or "Match arrow colors to the key below.")
    max_legend_y = legend_y_start + ((n_legends + 1) // 2) * 20 + 10 if n_legends > 0 else 340
    caption_y = max(416, max_legend_y + 16)
    svg_h = max(440, caption_y + 24)
    svg = (
        f"<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 600 {svg_h}'>"
        f"<rect width='600' height='{svg_h}' fill='#f0f4f8'/>"
        f"<text x='300' y='34' text-anchor='middle' font-family='sans-serif' font-size='18' fill='#0f172a' font-weight='700'>{title_e}</text>"
        + "".join(arrow_parts)
        + "".join(shape_parts)
        + "".join(legend_parts)
        + f"<text x='300' y='{caption_y}' text-anchor='middle' font-family='sans-serif' font-size='12' fill='#475569'>{caption_e}</text>"
        "</svg>"
    )
    return _sanitize_svg_markup(svg)


def _openrouter_read_image(image_bytes: bytes, mime_type: str, prompt: str) -> str:
    """Send an image + prompt to a vision-capable OpenRouter model."""
    if not OPENROUTER_API_KEY:
        return "API not ready"
    try:
        b64 = base64.b64encode(image_bytes).decode("utf-8")
        data_url = f"data:{mime_type};base64,{b64}"
        r = _openrouter_complete(
            OPENROUTER_VISION_MODEL,
            [
                {
                    "role": "user",
                    "content": [
                        {"type": "text", "text": prompt},
                        {"type": "image_url", "image_url": {"url": data_url}},
                    ],
                }
            ],
            max_tokens=2048,
        )
        return r.text or ""
    except Exception as e:
        return friendly_llm_error(e)

async def _fetch_page_text(url: str, max_chars: int = 4000) -> str:
    """Fetch a web page and extract readable text content."""
    try:
        if not await asyncio.to_thread(_is_safe_public_url, url):
            logger.warning(f"fetch_page blocked unsafe url: {url}")
            return ""
        async with httpx.AsyncClient(timeout=6.0, follow_redirects=True) as http:
            resp = await http.get(url, headers={
                "User-Agent": "Mozilla/5.0 (compatible; AlexStudies/1.0)",
                "Accept": "text/html,application/xhtml+xml",
            })
            resp.raise_for_status()
            content_type = (resp.headers.get("content-type", "") or "").lower()
            if not any(marker in content_type for marker in ("text/html", "application/xhtml+xml", "text/plain")):
                return ""
            html = resp.text
        # Strip HTML tags and extract text
        text = re.sub(r'<script[^>]*>[\s\S]*?</script>', ' ', html, flags=re.IGNORECASE)
        text = re.sub(r'<style[^>]*>[\s\S]*?</style>', ' ', text, flags=re.IGNORECASE)
        text = re.sub(r'<nav[^>]*>[\s\S]*?</nav>', ' ', text, flags=re.IGNORECASE)
        text = re.sub(r'<header[^>]*>[\s\S]*?</header>', ' ', text, flags=re.IGNORECASE)
        text = re.sub(r'<footer[^>]*>[\s\S]*?</footer>', ' ', text, flags=re.IGNORECASE)
        text = re.sub(r'<[^>]+>', ' ', text)
        text = re.sub(r'&[a-zA-Z]+;', ' ', text)
        text = re.sub(r'\s+', ' ', text).strip()
        return text[:max_chars]
    except Exception as e:
        logger.error(f"fetch_page error fetching {url}: {e}")
        return ""


async def _web_search(query: str) -> tuple:
    """Search the web via DuckDuckGo. Returns (snippets_text, results_list)."""
    if not DDG_SEARCH_ENABLED:
        return "", []
    try:
        def _do_search():
            with DDGS() as ddgs:
                return list(ddgs.text(query, max_results=6))

        results = await asyncio.to_thread(_do_search)
        if not results:
            return "", []
        parts = []
        for r in results:
            title = r.get("title", "")
            body = r.get("body", "")
            url = r.get("href", "")
            parts.append(f"- {title}: {body} (Source: {url})")
        return "\n".join(parts), results
    except Exception as e:
        logger.error(f"web_search error: {e}")
        return "", []


def _normalize_unicode_json_quotes(s: str) -> str:
    return (
        s.replace("\u201c", '"')
        .replace("\u201d", '"')
        .replace("\u2018", "'")
        .replace("\u2019", "'")
    )


def _strip_json_trailing_commas(s: str) -> str:
    prev = None
    while prev != s:
        prev = s
        s = re.sub(r",(\s*])", r"\1", s)
        s = re.sub(r",(\s*})", r"\1", s)
    return s


def _balanced_json_array_end(s: str, open_idx: int) -> int:
    """Index of the `]` that closes the array starting at open_idx, or -1 if unclosed."""
    if open_idx < 0 or open_idx >= len(s) or s[open_idx] != "[":
        return -1
    depth = 0
    i = open_idx
    in_string = False
    escape = False
    while i < len(s):
        ch = s[i]
        if in_string:
            if escape:
                escape = False
            elif ch == "\\":
                escape = True
            elif ch == '"':
                in_string = False
            i += 1
            continue
        if ch == '"':
            in_string = True
            i += 1
            continue
        if ch == "[":
            depth += 1
        elif ch == "]":
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return -1


def _coerce_parsed_json_to_plan_list(obj: Any) -> list | None:
    if isinstance(obj, list):
        return obj
    if isinstance(obj, dict):
        for k in ("plan", "days", "study_plan", "schedule", "items", "entries"):
            v = obj.get(k)
            if isinstance(v, list):
                return v
        for v in obj.values():
            if isinstance(v, list) and v and isinstance(v[0], dict):
                keys = {str(x).lower() for x in v[0].keys()}
                if "day" in keys:
                    return v
    return None


def _try_parse_llm_json_array_payload(s: str, _depth: int = 0) -> list | None:
    """Return a list if s is valid JSON (optionally after light LLM fixes)."""
    if _depth > 4:
        return None
    s = (s or "").strip()
    if not s:
        return None
    variants = (
        s,
        _strip_json_trailing_commas(s),
        _normalize_unicode_json_quotes(s),
        _strip_json_trailing_commas(_normalize_unicode_json_quotes(s)),
    )
    seen: set[str] = set()
    for cand in variants:
        if cand in seen:
            continue
        seen.add(cand)
        try:
            obj = json.loads(cand)
        except json.JSONDecodeError:
            continue
        if isinstance(obj, str):
            inner = obj.strip()
            if inner.startswith("[") or inner.startswith("{"):
                nested = _try_parse_llm_json_array_payload(inner, _depth + 1)
                if nested is not None:
                    return nested
            continue
        lst = _coerce_parsed_json_to_plan_list(obj)
        if isinstance(lst, list):
            return lst
    return None


def _parse_llm_json_plan_array(text: str) -> list:
    """Parse a top-level JSON array (or dict wrapper) from LLM study-plan output."""
    cleaned = (text or "").strip().lstrip("\ufeff")
    if not cleaned:
        return []
    if cleaned.startswith("```"):
        first_nl = cleaned.find("\n")
        if first_nl != -1:
            cleaned = cleaned[first_nl + 1 :]
        if cleaned.rstrip().endswith("```"):
            cleaned = cleaned.rstrip()[:-3].rstrip()

    direct = _try_parse_llm_json_array_payload(cleaned)
    if direct is not None:
        return direct

    a = cleaned.find("[")
    if a == -1:
        return []

    b = _balanced_json_array_end(cleaned, a)
    if b != -1:
        slice_str = cleaned[a : b + 1]
        got = _try_parse_llm_json_array_payload(slice_str)
        if got is not None:
            return got

    b2 = cleaned.rfind("]")
    if b2 != -1 and b2 > a:
        got2 = _try_parse_llm_json_array_payload(cleaned[a : b2 + 1])
        if got2 is not None:
            return got2

    fragment = cleaned[a:]
    last_brace = fragment.rfind("}")
    if last_brace > 0:
        truncated = fragment[: last_brace + 1] + "]"
        got3 = _try_parse_llm_json_array_payload(truncated)
        if got3 is not None:
            print(f"[PLAN-GEN] Recovered {len(got3)} items from truncated JSON", flush=True)
            return got3

    return []


async def _read_top_pages(results: list, max_pages: int = 3) -> str:
    """Fetch and read full content from the top search result pages."""
    urls = [r.get("href", "") for r in results if r.get("href")][:max_pages]
    if not urls:
        return ""
    tasks = [_fetch_page_text(url) for url in urls]
    pages = await asyncio.gather(*tasks, return_exceptions=True)
    parts = []
    for i, page in enumerate(pages):
        if isinstance(page, str) and page.strip():
            title = results[i].get("title", f"Page {i+1}")
            url = urls[i]
            parts.append(f"[Source: {title}]({url})\n{page}\n")
    return "\n---\n".join(parts)


