def subject_code_display_name(code: str) -> str:
    c = (code or "").strip()
    if not c:
        return ""
    if c in PS_SUBJECT_FULL_NAMES:
        return PS_SUBJECT_FULL_NAMES[c]
    if c in BS_SUBJECT_FULL_NAMES:
        return BS_SUBJECT_FULL_NAMES[c]
    return c


