# ── Route-based scope mapping ──
# Each scope gets its own URL so navigation = full page reload = no stale state.
SCOPE_ROUTE_MAP: dict[str, dict[str, str]] = {}
for _yr_label, _semesters in SEMESTER_NAVIGATION.items():
    _yr_num = _yr_label.replace("Year ", "").strip()
    for _sem_label in _semesters:
        _sem_num = _sem_label.replace("Semester ", "").strip()
        _scope_key = f"y{_yr_num}s{_sem_num}"
        SCOPE_ROUTE_MAP[_scope_key] = {
            "route": f"/s/{_scope_key}",
            "year": _yr_label,
            "semester": _sem_label,
            "view_mode": "semester",
        }
SCOPE_ROUTE_MAP["home"] = {
    "route": "/s/home",
    "year": "",
    "semester": "",
    "view_mode": "home",
}


def scope_to_route(scope_key: str) -> str:
    """Convert a scope key like 'y1s2' to its page route like '/s/y1s2'."""
    base_scope = str(scope_key or "home").split(":", 1)[0] or "home"
    entry = SCOPE_ROUTE_MAP.get(base_scope)
    return entry["route"] if entry else "/s/home"


def semester_scope_key(year: str, semester: str) -> str:
    y = year.lower().replace("year", "").strip()
    s = semester.lower().replace("semester", "").strip()
    if y.isdigit() and s.isdigit():
        return f"y{y}s{s}"
    return f"{year}|{semester}"


def _hard_navigate(route: str):
    """Force a full browser navigation — guarantees fresh WebSocket + state."""
    return rx.call_script(f"window.location.href = {json.dumps(route)}")


def _replace_route(route: str):
    """Replace stale browser history entries with the canonical workspace route."""
    return rx.call_script(f"window.location.replace({json.dumps(route)})")


_GA_ALLOWED_PARAM_KEYS = {
    "app_version",
    "auth_method",
    "button_location",
    "currency",
    "country",
    "degree_key",
    "page_location",
    "page_path",
    "page_title",
    "payment_status",
    "plan_name",
    "plan_scope",
    "price_usd",
    "pricing_variant",
    "route",
    "scope",
    "semester",
    "year",
}


def _safe_ga_params(params: dict[str, Any] | None = None) -> dict[str, Any]:
    """Keep GA4 funnel params non-personal and JSON-safe."""
    safe: dict[str, Any] = {}
    for key, value in (params or {}).items():
        if key not in _GA_ALLOWED_PARAM_KEYS or value is None:
            continue
        if isinstance(value, bool):
            safe[key] = value
        elif isinstance(value, (int, float)) and not isinstance(value, bool):
            safe[key] = value
        else:
            safe[key] = str(value)[:120]
    return safe


def track_ga_event(event_name: str, params: dict[str, Any] | None = None):
    """Fire a safe GA4 custom event through the global alexTrack helper."""
    safe_name = re.sub(r"[^A-Za-z0-9_]", "", str(event_name or ""))[:80]
    if not safe_name:
        return rx.call_script("")
    return rx.call_script(
        "try{if(window.alexTrack){window.alexTrack("
        + json.dumps(safe_name)
        + ","
        + json.dumps(_safe_ga_params(params))
        + ");}}catch(e){}"
    )


def _ga_degree_key(degree: str) -> str:
    """Non-personal degree identifier for analytics; never includes custom text."""
    value = (degree or "").strip()
    if not value:
        return ""
    if _degree_is_custom(value):
        return "custom"
    return re.sub(r"[^a-z0-9]+", "_", value.lower()).strip("_")[:80]


def _ga_study_params(
    *,
    country: str = "",
    degree: str = "",
    year: str = "",
    semester: str = "",
    plan_scope: str = "",
) -> dict[str, Any]:
    params: dict[str, Any] = {}
    if country:
        params["country"] = country
    degree_key = _ga_degree_key(degree)
    if degree_key:
        params["degree_key"] = degree_key
    if year:
        params["year"] = year
    if semester:
        params["semester"] = semester
    if plan_scope:
        params["plan_scope"] = plan_scope
    return params


