def require_app_login(page: rx.app.ComponentCallable) -> rx.app.ComponentCallable:
    def protected_page():
        return rx.fragment(
            _client_storage_cookie_bridge_script(),
            _ga_user_id_script(),
            rx.cond(
                AppState.is_hydrated,
                page(),
                _app_shell_loading_gate(),
            )
        )

    protected_page.__name__ = page.__name__
    return protected_page


CLIENT_STORAGE_COOKIE_BRIDGE_JS = f"""
(function() {{
  function readStorage(key) {{
    try {{
      var raw = localStorage.getItem(key) || "";
      if (!raw) return "";
      try {{
        var parsed = JSON.parse(raw);
        if (typeof parsed === "string") raw = parsed;
      }} catch (e) {{}}
      return String(raw || "").trim();
    }} catch (e) {{
      return "";
    }}
  }}
  function hasCookie(name) {{
    try {{
      return document.cookie.split(";").some(function(part) {{
        return part.trim().indexOf(name + "=") === 0;
      }});
    }} catch (e) {{
      return false;
    }}
  }}
  function remember(name, value, maxAge) {{
    if (!value) return;
    try {{
      document.cookie =
        name + "=" + encodeURIComponent(value) +
        "; Max-Age=" + maxAge +
        "; Path=/; SameSite=Lax" +
        (window.location && window.location.protocol === "https:" ? "; Secure" : "");
    }} catch (e) {{}}
  }}
  var authName = {json.dumps(AUTH_TOKEN_LOCAL_STORAGE_KEY)};
  var authValue = readStorage(authName);
  var hadAuthCookie = hasCookie(authName);
  remember(authName, authValue, {AUTH_SESSION_MAX_AGE_SECONDS});
  remember({json.dumps(GUEST_TOKEN_LOCAL_STORAGE_KEY)}, readStorage({json.dumps(GUEST_TOKEN_LOCAL_STORAGE_KEY)}), {60 * 60 * 24 * 30});
  try {{
    var params = new URLSearchParams(window.location.search || "");
    if (
      authValue &&
      !hadAuthCookie &&
      window.location &&
      window.location.pathname === {json.dumps(APP_DASHBOARD_ROUTE)} &&
      !params.has("auth_sync")
    ) {{
      params.set("auth_sync", "1");
      window.location.replace(window.location.pathname + "?" + params.toString());
    }}
  }} catch (e) {{}}
}})();
"""


def _client_storage_cookie_bridge_script() -> rx.Component:
    return rx.script(CLIENT_STORAGE_COOKIE_BRIDGE_JS)


def _ga_user_id_script() -> rx.Component:
    """Sets GA4 User-ID for authenticated users (safe/no-op if gtag missing)."""
    # NOTE: `_cached_uid` is a plain Python int field; expose it through a Reflex var
    # before embedding into JS to avoid compile-time evaluation issues.
    uid = AppState.cached_uid.to_string()
    return rx.cond(
        AppState.is_authenticated_now,
        rx.script(
            "(function(){"
            "try{"
            "var uid=Number(" + uid + ");"
            "if(!(uid>=0)) return;"
            "var uidStr=String(uid);"
            "if(window.__ga4_user_id_last===uidStr) return;"
            "window.__ga4_user_id_last=uidStr;"
            "var tries=0;"
            "function apply(){"
            "try{"
            "if(typeof window.gtag==='function'){"
            "window.gtag('set', {'user_id': uidStr});"
            "return;"
            "}"
            "}catch(e){}"
            "tries++;"
            "if(tries<25) setTimeout(apply,200);"
            "}"
            "apply();"
            "}catch(e){}"
            "})();"
        ),
        rx.fragment(),
    )


def _auth_error(text_var: rx.Var) -> rx.Component:
    return rx.cond(
        text_var != "",
        rx.callout(text_var, icon="triangle_alert", color_scheme="red", role="alert", width="100%"),
        rx.fragment(),
    )


