# ----------------------------
# Payment webhooks
# ----------------------------
async def gumroad_ping(request: Request) -> PlainTextResponse:
    try:
        if not (GUMROAD_PING_SECRET and GUMROAD_SELLER_ID and GUMROAD_PRODUCT_ID):
            print("[Gumroad] ping endpoint disabled: missing webhook configuration")
            return PlainTextResponse("webhook unavailable", status_code=503)

        raw_body = await request.body()
        signature = (
            request.headers.get("X-Gumroad-Signature")
            or request.headers.get("X-GUMROAD-SIGNATURE")
            or ""
        ).strip()
        expected_hex = hmac.new(
            GUMROAD_PING_SECRET.encode("utf-8"),
            raw_body,
            hashlib.sha256,
        ).hexdigest()
        expected_prefixed = f"sha256={expected_hex}"
        expected_b64 = base64.b64encode(
            hmac.new(
                GUMROAD_PING_SECRET.encode("utf-8"),
                raw_body,
                hashlib.sha256,
            ).digest()
        ).decode("ascii")
        if not signature or signature not in {expected_hex, expected_prefixed, expected_b64}:
            print("[Gumroad] invalid webhook signature")
            return PlainTextResponse("invalid signature", status_code=400)

        form = dict(parse_qsl(raw_body.decode("utf-8"), keep_blank_values=True))

        seller_id   = str(form.get("seller_id", ""))
        product_id  = str(form.get("product_id", ""))
        email       = str(form.get("email", ""))
        unique_id   = str(form.get("custom_fields[unique_id]", "") or form.get("url_params[unique_id]", "")).strip()

        if seller_id != GUMROAD_SELLER_ID or product_id != GUMROAD_PRODUCT_ID:
            print(f"[Gumroad] rejected webhook for unexpected seller/product seller_id={seller_id} product_id={product_id}")
            return PlainTextResponse("invalid webhook", status_code=400)

        if not unique_id:
            print(f"[Gumroad] ❌ No unique_id in ping (email={email})")
            return PlainTextResponse("missing unique_id", status_code=400)

        with rx.session() as session:
            profile = session.exec(
                select(UserProfile).where(UserProfile.unique_id == unique_id)
            ).one_or_none()

            if profile is None:
                print(f"[Gumroad] ❌ Unknown unique_id: {unique_id} (email={email})")
                return PlainTextResponse("user not found", status_code=404)

            _apply_profile_plan(profile, PLAN_PRO, True)
            session.add(profile)
            session.commit()
            print(f"[Gumroad] ✅ Activated Premium (30 days) for user_id={profile.user_id} unique_id={unique_id}")

        return PlainTextResponse("OK", status_code=200)

    except Exception as e:
        print(f"[Gumroad] 🔥 ping error: {e}")
        return PlainTextResponse("server error", status_code=500)


def _normalize_email(email: str) -> str:
    return (email or "").strip().lower()


def _profile_paid_plan_active(profile: UserProfile) -> bool:
    activated = getattr(profile, "premium_activated_at", None)
    if activated is None:
        return bool(getattr(profile, "is_pro", False) or getattr(profile, "is_premium_1", False) or getattr(profile, "is_premium_2", False))
    try:
        if activated.tzinfo is None:
            activated = activated.replace(tzinfo=timezone.utc)
        return (datetime.now(timezone.utc) - activated).days < 30
    except Exception:
        return False


def _profile_effective_plan_tier(profile: UserProfile) -> str:
    explicit_plan = _normalize_plan_tier(str(getattr(profile, "plan_tier", "") or ""))
    if explicit_plan != PLAN_FREE and _profile_paid_plan_active(profile):
        return explicit_plan
    if getattr(profile, "is_premium_2", False) and _profile_paid_plan_active(profile):
        return PLAN_MAX
    if (getattr(profile, "is_premium_1", False) or getattr(profile, "is_pro", False)) and _profile_paid_plan_active(profile):
        return PLAN_PRO
    return PLAN_FREE


def _apply_profile_plan(profile: UserProfile, plan_tier: str, is_active: bool) -> None:
    plan = _normalize_plan_tier(plan_tier)
    if is_active and plan in PAID_PLAN_KEYS:
        profile.plan_tier = plan
        profile.is_pro = True
        profile.is_premium_1 = True
        profile.is_premium_2 = _plan_at_least(plan, PLAN_MAX)
        profile.premium_activated_at = datetime.now(timezone.utc)
        return
    profile.plan_tier = PLAN_FREE
    profile.is_pro = False
    profile.is_premium_1 = False
    profile.is_premium_2 = False
    profile.premium_activated_at = None


def _store_user_profile_email(uid: int, email: str) -> None:
    normalized_email = _normalize_email(email)
    if uid < 0 or not normalized_email:
        return

    with rx.session() as session:
        profile = session.exec(
            select(UserProfile).where(UserProfile.user_id == uid)
        ).one_or_none()
        if profile is None:
            profile = UserProfile(user_id=uid)  # type: ignore
        if profile.email != normalized_email:
            profile.email = normalized_email
            session.add(profile)
            session.commit()


def _set_plan_status_by_email(email: str, plan_tier: str, is_active: bool) -> bool:
    normalized_email = _normalize_email(email)
    if not normalized_email:
        return False

    with rx.session() as session:
        profile = session.exec(
            select(UserProfile).where(func.lower(UserProfile.email) == normalized_email)
        ).one_or_none()

        if profile is None:
            user = session.exec(
                select(LocalUser).where(func.lower(LocalUser.username) == normalized_email)
            ).one_or_none()
            if user is not None and user.id is not None:
                profile = session.exec(
                    select(UserProfile).where(UserProfile.user_id == int(user.id))
                ).one_or_none()

        if profile is None:
            return False

        profile.email = normalized_email
        _apply_profile_plan(profile, plan_tier, is_active)
        session.add(profile)
        session.commit()
        return True


def _set_plan_status_by_unique_id(unique_id: str, plan_tier: str, is_active: bool) -> bool:
    normalized_unique_id = (unique_id or "").strip()
    if not normalized_unique_id:
        return False

    with rx.session() as session:
        profile = session.exec(
            select(UserProfile).where(UserProfile.unique_id == normalized_unique_id)
        ).one_or_none()
        if profile is None:
            return False

        _apply_profile_plan(profile, plan_tier, is_active)
        session.add(profile)
        session.commit()
        return True


def _set_pro_status_by_email(email: str, is_pro: bool) -> bool:
    return _set_plan_status_by_email(email, PLAN_PRO, is_pro)


def _set_pro_status_by_unique_id(unique_id: str, is_pro: bool) -> bool:
    return _set_plan_status_by_unique_id(unique_id, PLAN_PRO, is_pro)


async def dodo_webhook(request: Request) -> PlainTextResponse:
    if not (DODO_PAYMENTS_API_KEY and DODO_PAYMENTS_WEBHOOK_SECRET):
        print("[Dodo Payments] webhook disabled: missing API key or webhook secret")
        return PlainTextResponse("webhook unavailable", status_code=503)

    raw_payload = await request.body()
    payload = raw_payload.decode("utf-8")

    try:
        APIWebhookValidationError, DodoPayments, DodoPaymentsError = _load_dodo_payments()
    except Exception as e:
        print(f"[Dodo Payments] webhook SDK unavailable: {e}")
        return PlainTextResponse("webhook unavailable", status_code=500)

    try:
        client = DodoPayments(
            bearer_token=DODO_PAYMENTS_API_KEY,
            webhook_key=DODO_PAYMENTS_WEBHOOK_SECRET,
        )
        event = client.webhooks.unwrap(payload, headers=dict(request.headers))
    except APIWebhookValidationError as e:
        print(f"[Dodo Payments] invalid webhook signature: {e}")
        return PlainTextResponse("invalid signature", status_code=400)
    except DodoPaymentsError as e:
        print(f"[Dodo Payments] webhook validation unavailable: {e}")
        return PlainTextResponse("webhook unavailable", status_code=500)
    except Exception as e:
        print(f"[Dodo Payments] unexpected webhook error: {e}")
        return PlainTextResponse("server error", status_code=500)

    event_type = str(getattr(event, "type", "") or "").strip()
    event_data = getattr(event, "data", None)
    customer = getattr(event_data, "customer", None)
    email = _normalize_email(str(getattr(customer, "email", "") or ""))
    metadata = getattr(event_data, "metadata", {}) or {}
    if not isinstance(metadata, dict):
        metadata = {}
    unique_id = str(metadata.get("unique_id", "") or "").strip()
    product_id = str(
        getattr(event_data, "product_id", "")
        or getattr(event_data, "product", "")
        or metadata.get("product_id", "")
        or ""
    ).strip()
    plan_tier = _normalize_plan_tier(str(metadata.get("plan_tier", "") or ""))
    if plan_tier == PLAN_FREE:
        plan_tier = next(
            (
                candidate
                for candidate, configured_product_id in PLAN_PRODUCT_IDS.items()
                if configured_product_id and configured_product_id == product_id
            ),
            PLAN_PRO,
        )

    try:
        if event_type in {"payment.succeeded", "subscription.renewed"}:
            if not (
                _set_plan_status_by_email(email, plan_tier, True)
                or _set_plan_status_by_unique_id(unique_id, plan_tier, True)
            ):
                print(f"[Dodo Payments] no matching user for success event unique_id={unique_id} email={email} plan={plan_tier}")
        elif event_type in {"subscription.cancelled", "subscription.failed"}:
            if not (
                _set_plan_status_by_email(email, plan_tier, False)
                or _set_plan_status_by_unique_id(unique_id, plan_tier, False)
            ):
                print(f"[Dodo Payments] no matching user for downgrade event type={event_type} unique_id={unique_id} email={email} plan={plan_tier}")
        else:
            print(f"[Dodo Payments] ignored event type={event_type}")
    except Exception as e:
        print(f"[Dodo Payments] processing error for type={event_type} unique_id={unique_id} email={email}: {e}")
        return PlainTextResponse("OK", status_code=200)

    return PlainTextResponse("OK", status_code=200)


async def health_check(request):
    try:
        with rx.session() as session:
            session.exec(select(UserProfile).limit(1))
        return PlainTextResponse("OK")
    except Exception:
        return PlainTextResponse("unhealthy", status_code=500)


