    @rx.event
    def set_name(self, value: str):
        self.name = _normalize_person_name(value)
        self.onboarding_message = ""
        uid = self._active_data_uid()
        self._save_memory(uid)

    @rx.var
    def available_semesters(self) -> list[str]:
        if not self.selected_year:
            return []
        return SEMESTER_NAVIGATION.get(self.selected_year, [])

    def _uid(self) -> int:
        # rx.LocalStorage reads localStorage values without JSON.parse, but
        # the Next.js login route and Google OAuth bootstrap both write the
        # session token via JSON.stringify(...). The result is auth_token /
        # app_auth_token hold a quoted string like '"abc123"' instead of the
        # raw 'abc123' stored in localauthsession — so the SQL lookup below
        # silently fails on a fresh tab and the user gets bounced back into
        # onboarding. Decode the same way _cookie_value already does.
        tokens: list[str] = []
        for raw in (self.auth_token, self.app_auth_token, self._auth_token_from_cookie()):
            token = (raw or "").strip()
            if not token:
                continue
            try:
                parsed = json.loads(token)
                if isinstance(parsed, str):
                    token = parsed.strip()
            except Exception:
                pass
            if token and token not in tokens:
                tokens.append(token)
        if not tokens:
            return -1
        try:
            with rx.session() as session:
                for token in tokens:
                    auth_sess = session.exec(
                        select(LocalAuthSession).where(
                            LocalAuthSession.session_id == token,
                            LocalAuthSession.expiration >= datetime.now(timezone.utc),
                        )
                    ).one_or_none()
                    if auth_sess and auth_sess.user_id is not None:
                        return int(auth_sess.user_id)
        except Exception as e:
            print(f"ERROR uid lookup: {e}")
        return -1

    def _guest_uid_from_token(self, token: str) -> int:
        cleaned = (token or "").strip()
        if not cleaned:
            return -1
        digest = hashlib.sha256(f"alex-guest:{cleaned}".encode("utf-8")).hexdigest()
        return GUEST_USER_ID_BASE + (int(digest[:12], 16) % GUEST_USER_ID_SPAN)

    def _ensure_guest_token(self) -> str:
        token = (self.guest_token or "").strip()
        if not token:
            token = f"g_{secrets.token_urlsafe(24)}"
            self.guest_token = token
        return token

    def _guest_uid(self, *, create: bool = False) -> int:
        token = self._ensure_guest_token() if create else (self.guest_token or "").strip()
        return self._guest_uid_from_token(token)

    def _active_data_uid(self) -> int:
        uid = self._uid()
        if uid >= 0:
            return uid
        return self._guest_uid(create=True)

    def _load_guest_memory(self, uid: int) -> None:
        if uid < 0:
            return
        with rx.session() as session:
            memory = session.exec(
                select(UserMemory).where(UserMemory.user_id == uid)
            ).one_or_none()
        if memory is None:
            self.step = 0
            self.degree = ""
            self.pathway = ""
            self.active_subject = ""
            self.is_started = False
            self.selected_year = ""
            self.selected_semester = ""
            self.memory_summary = ""
            self.other_degree_text = ""
            self._sync_pathway_options()
            return
        self.step = int(memory.step or 0)
        self.name = _normalize_person_name(memory.name)
        self.degree = memory.degree or ""
        self.pathway = memory.pathway or ""
        self.active_subject = memory.active_subject or ""
        self.is_started = bool(memory.is_started)
        self.selected_year = memory.selected_year or ""
        self.selected_semester = memory.selected_semester or ""
        self.memory_summary = memory.summary or ""
        self.other_degree_text = getattr(memory, "other_degree_text", "") or ""
        if self.pathway:
            self.pathway = canonical_pathway_label(self.degree, self.pathway)
        self._sync_pathway_options()

    def _cookie_value(self, name: str) -> str:
        try:
            raw_cookie = str(getattr(self.router.headers, "cookie", "") or "")
        except Exception:
            raw_cookie = ""
        if not raw_cookie:
            return ""
        try:
            cookie = SimpleCookie()
            cookie.load(raw_cookie)
            morsel = cookie.get(name)
            token = str(morsel.value if morsel else "").strip()
        except Exception:
            token = ""
        if not token:
            return ""
        try:
            token = unquote(token).strip()
        except Exception:
            pass
        try:
            parsed = json.loads(token)
            if isinstance(parsed, str):
                token = parsed.strip()
        except Exception:
            pass
        return token

    def _auth_token_from_cookie(self) -> str:
        return self._cookie_value(AUTH_TOKEN_LOCAL_STORAGE_KEY)

    def _guest_token_from_cookie(self) -> str:
        return self._cookie_value(GUEST_TOKEN_LOCAL_STORAGE_KEY)

    def _migrate_guest_data_to_user(self, uid: int, guest_token: str = "") -> None:
        guest_uid = self._guest_uid_from_token(guest_token) if guest_token else self._guest_uid(create=False)
        if uid < 0 or guest_uid < 0 or guest_uid == uid:
            return

        def newer(a: Any, b: Any) -> bool:
            av = getattr(a, "updated_at", None) or getattr(a, "created_at", None)
            bv = getattr(b, "updated_at", None) or getattr(b, "created_at", None)
            if av is None or bv is None:
                return True
            return av >= bv

        try:
            with rx.session() as session:
                guest_mem = session.exec(select(UserMemory).where(UserMemory.user_id == guest_uid)).one_or_none()
                if guest_mem is not None:
                    real_mem = session.exec(select(UserMemory).where(UserMemory.user_id == uid)).one_or_none()
                    if real_mem is None:
                        guest_mem.user_id = uid
                        session.add(guest_mem)
                    else:
                        if guest_mem.is_started or not real_mem.is_started:
                            real_mem.step = guest_mem.step
                            real_mem.name = guest_mem.name
                            real_mem.degree = guest_mem.degree
                            real_mem.pathway = guest_mem.pathway
                            real_mem.active_subject = guest_mem.active_subject
                            real_mem.is_started = guest_mem.is_started
                            real_mem.selected_year = guest_mem.selected_year
                            real_mem.selected_semester = guest_mem.selected_semester
                            real_mem.other_degree_text = guest_mem.other_degree_text
                        if (guest_mem.summary or "").strip():
                            real_mem.summary = guest_mem.summary
                        session.add(real_mem)
                        session.delete(guest_mem)

                for model in (ChatMessage, ChatSession, ChatMessage2, MessageFeedback, StudentNote, TodoTracker):
                    for row in session.exec(select(model).where(model.user_id == guest_uid)).all():
                        row.user_id = uid
                        session.add(row)

                for row in session.exec(select(ScopeMemory).where(ScopeMemory.user_id == guest_uid)).all():
                    real = session.exec(
                        select(ScopeMemory)
                        .where(ScopeMemory.user_id == uid)
                        .where(ScopeMemory.scope == row.scope)
                    ).first()
                    if real is None:
                        row.user_id = uid
                        session.add(row)
                    else:
                        guest_summary = (row.summary or "").strip()
                        real_summary = (real.summary or "").strip()
                        if guest_summary and guest_summary not in real_summary:
                            real.summary = ((real_summary + "\n\n" + guest_summary).strip())[:4000]
                        session.add(real)
                        session.delete(row)

                for row in session.exec(select(SemesterStudyPlan).where(SemesterStudyPlan.user_id == guest_uid)).all():
                    real = session.exec(
                        select(SemesterStudyPlan)
                        .where(SemesterStudyPlan.user_id == uid)
                        .where(SemesterStudyPlan.scope == row.scope)
                    ).first()
                    if real is None:
                        row.user_id = uid
                        session.add(row)
                    else:
                        if (not real.plan_json) or newer(row, real):
                            real.plan_json = row.plan_json
                            session.add(real)
                        session.delete(row)

                for row in session.exec(select(SemesterPlanGenerationState).where(SemesterPlanGenerationState.user_id == guest_uid)).all():
                    real = session.exec(
                        select(SemesterPlanGenerationState)
                        .where(SemesterPlanGenerationState.user_id == uid)
                        .where(SemesterPlanGenerationState.scope == row.scope)
                    ).first()
                    if real is None:
                        row.user_id = uid
                        session.add(row)
                    else:
                        if newer(row, real):
                            real.status = row.status
                            real.error_message = row.error_message
                            session.add(real)
                        session.delete(row)

                for row in session.exec(select(DayProgress).where(DayProgress.user_id == guest_uid)).all():
                    real = session.exec(
                        select(DayProgress)
                        .where(DayProgress.user_id == uid)
                        .where(DayProgress.scope == row.scope)
                    ).first()
                    if real is None:
                        row.user_id = uid
                        session.add(row)
                    else:
                        if newer(row, real):
                            real.current_day = row.current_day
                            real.current_topic_index = row.current_topic_index
                            session.add(real)
                        session.delete(row)

                for row in session.exec(select(StudyProgress).where(StudyProgress.user_id == guest_uid)).all():
                    real = session.exec(
                        select(StudyProgress)
                        .where(StudyProgress.user_id == uid)
                        .where(StudyProgress.year == row.year)
                        .where(StudyProgress.semester == row.semester)
                        .where(StudyProgress.course == row.course)
                    ).first()
                    if real is None:
                        row.user_id = uid
                        session.add(row)
                    else:
                        if row.status == "done" and real.status != "done":
                            real.status = "done"
                            real.last_done_at = row.last_done_at
                        if (row.notes or "").strip() and not (real.notes or "").strip():
                            real.notes = row.notes
                        session.add(real)
                        session.delete(row)

                for row in session.exec(select(LearnVideoSession).where(LearnVideoSession.user_id == guest_uid)).all():
                    real = session.exec(
                        select(LearnVideoSession)
                        .where(LearnVideoSession.user_id == uid)
                        .where(LearnVideoSession.video_id == row.video_id)
                    ).first()
                    if real is None:
                        row.user_id = uid
                        session.add(row)
                    else:
                        if not real.title:
                            real.title = row.title
                        if not real.transcript_cached:
                            real.transcript_cached = row.transcript_cached
                        if not real.summary_cached:
                            real.summary_cached = row.summary_cached
                        if not real.quiz_json:
                            real.quiz_json = row.quiz_json
                        if (row.chat_history_json or "[]") != "[]":
                            try:
                                real_chat = json.loads(real.chat_history_json or "[]")
                                guest_chat = json.loads(row.chat_history_json or "[]")
                                if isinstance(real_chat, list) and isinstance(guest_chat, list):
                                    real.chat_history_json = json.dumps(real_chat + guest_chat)
                            except Exception:
                                pass
                        session.add(real)
                        session.delete(row)

                session.commit()
            self.guest_token = ""
        except Exception as e:
            print(f"[GUEST MIGRATE] error: {e}")

    def _safe_role(self, role: str) -> str:
        return "assistant" if role == "bot" else role

    def _scope_key(self, year: str, semester: str) -> str:
        base = semester_scope_key(year, semester)
        # For multi-subject degrees, append subject to scope so each subject has independent chat/plan
        if self._is_multi_subject_degree():
            subject = self._active_subject_for_semester(year, semester)
            if subject:
                return f"{base}:{subject}"
        return base

    def _normalize_course_label(self, value: str) -> str:
        text = (value or "").strip().lower()
        if ":" in text:
            text = text.split(":", 1)[1]
        text = re.sub(r"[^a-z0-9]+", " ", text)
        return " ".join(text.split())

    def _is_multi_subject_degree(self) -> bool:
        """True if current degree uses the multi-subject model (e.g. Physical Science)."""
        return self.degree in MULTI_SUBJECT_DEGREES

    def _sync_pathway_options(self) -> None:
        if self.degree in MULTI_SUBJECT_DEGREES:
            self.pathway_options = list(DEGREE_PATHWAY_LABELS.get(self.degree, []))
        else:
            self.pathway_options = []

    def _multi_subject_course_table(self) -> dict[str, dict[str, dict[str, list[str]]]]:
        if not self._is_multi_subject_degree():
            return {}
        return DEGREE_SUBJECT_CURRICULUM.get(self.degree, {})

    def _multi_subject_unit_table(self) -> dict[str, dict[str, dict[str, list[dict[str, Any]]]]]:
        if not self._is_multi_subject_degree():
            return {}
        return DEGREE_CURRICULUM_UNITS.get(self.degree, {})

    def _multi_subject_full_names(self) -> dict[str, str]:
        if not self._is_multi_subject_degree():
            return {}
        return DEGREE_SUBJECT_FULL_NAMES.get(self.degree, {})

    def _multi_subject_teaching_styles(self) -> dict[str, dict[str, str]]:
        if not self._is_multi_subject_degree():
            return {}
        return DEGREE_SUBJECT_TEACHING_STYLE.get(self.degree, {})

    def _valid_pathway_labels(self) -> list[str]:
        if not self._is_multi_subject_degree():
            return []
        return list(DEGREE_PATHWAY_LABELS.get(self.degree, []))

    def _pathway_subjects(self) -> list[str]:
        """Return the 3 subject codes for the student's pathway, or [] for non-pathway degrees."""
        return pathway_subject_codes(self.pathway)

    def _subject_scope_preferences(self) -> dict[str, str]:
        raw = (self.subject_scope_preferences_json or "").strip()
        if not raw:
            return {}
        try:
            data = json.loads(raw)
        except Exception:
            return {}
        if not isinstance(data, dict):
            return {}
        cleaned: dict[str, str] = {}
        valid_subjects = set(self._pathway_subjects())
        for key, value in data.items():
            k = str(key or "").strip()
            v = str(value or "").strip()
            if not k or not v:
                continue
            if valid_subjects and v not in valid_subjects:
                continue
            cleaned[k] = v
        return cleaned

    def _base_semester_scope(self, year: str, semester: str) -> str:
        return semester_scope_key(year, semester)

    def _active_subject_for_semester(self, year: str, semester: str) -> str:
        subjects = self._pathway_subjects()
        if not subjects:
            return ""
        base_scope = self._base_semester_scope(year, semester)
        remembered = self._subject_scope_preferences().get(base_scope, "")
        if remembered in subjects:
            return remembered
        if self.active_subject in subjects:
            return self.active_subject
        return subjects[0]

    def _remember_active_subject_for_semester(self, year: str, semester: str, subject: str) -> None:
        if not year or not semester or not subject:
            return
        subjects = self._pathway_subjects()
        if subjects and subject not in subjects:
            return
        prefs = self._subject_scope_preferences()
        prefs[self._base_semester_scope(year, semester)] = subject
        self.subject_scope_preferences_json = json.dumps(prefs, separators=(",", ":"))

    def _other_subjects(self) -> list[str]:
        """Return the OTHER subject codes (excluding active_subject) for subject switcher."""
        subjects = self._pathway_subjects()
        return [s for s in subjects if s != self.active_subject]

    def _semester_courses(self, year: str, semester: str) -> list[str]:
        """Return modules for current semester.
        - Multi-subject degrees: modules for the active_subject only
        - All other flat degrees: look up FLAT_DEGREE_CURRICULUM
        """
        if self._is_multi_subject_degree() and self.active_subject:
            return (
                self._multi_subject_course_table()
                .get(self.active_subject, {})
                .get(year, {})
                .get(semester, [])
            )
        curriculum = FLAT_DEGREE_CURRICULUM.get(self.degree)
        if curriculum is None:
            return []
        return curriculum.get(year, {}).get(semester, [])

    def _semester_courses_for_subject(self, subject: str, year: str, semester: str) -> list[str]:
        """Return modules for a specific subject in a semester (multi-subject degrees)."""
        return (
            self._multi_subject_course_table()
            .get(subject, {})
            .get(year, {})
            .get(semester, [])
        )

    def _semester_course_units_for_subject(self, subject: str, year: str, semester: str) -> list[dict[str, Any]]:
        return (
            self._multi_subject_unit_table()
            .get(subject, {})
            .get(year, {})
            .get(semester, [])
        )

    def _semester_course_units(self, year: str, semester: str) -> list[dict[str, Any]]:
        if self._is_multi_subject_degree() and self.active_subject:
            return self._semester_course_units_for_subject(self.active_subject, year, semester)
        if self.degree == "Software Engineering":
            return KELANIYA_SENG_CURRICULUM.get(year, {}).get(semester, [])
        if self.degree == "Electronics and Computer Science (BECS)":
            return KELANIYA_BECS_CURRICULUM.get(year, {}).get(semester, [])
        return []

    def _all_semester_course_units_ps(self, year: str, semester: str) -> list[dict[str, Any]]:
        names = self._multi_subject_full_names()
        styles = self._multi_subject_teaching_styles()
        units: list[dict[str, Any]] = []
        for subj in self._pathway_subjects():
            for unit in self._semester_course_units_for_subject(subj, year, semester):
                enriched = dict(unit)
                enriched["subject_code"] = subj
                enriched["subject_name"] = names.get(subj, subj)
                enriched["teaching_style"] = styles.get(subj, {})
                units.append(enriched)
        return units

    def _all_semester_courses_ps(self, year: str, semester: str) -> list[str]:
        """Return ALL modules across all 3 pathway subjects for a semester (for study plan)."""
        if not self._is_multi_subject_degree():
            return self._semester_courses(year, semester)
        table = self._multi_subject_course_table()
        all_courses: list[str] = []
        for subj in self._pathway_subjects():
            all_courses.extend(table.get(subj, {}).get(year, {}).get(semester, []))
        return all_courses

    def _has_curriculum_for_semester(self, year: str, semester: str) -> bool:
        return bool(self._semester_courses(year, semester))

    def _course_unit_list_text(self, course_units: list[dict[str, Any]]) -> str:
        if not course_units:
            return ""
        lines: list[str] = []
        for unit in course_units:
            subject_label = ""
            if unit.get("subject_code"):
                subject_label = f" | subject={unit.get('subject_code')} ({unit.get('subject_name')})"
            prereq = ", ".join(unit.get("prerequisites", [])) or "None listed"
            coreq = ", ".join(unit.get("corequisites", [])) or "None listed"
            lines.append(
                f"- {unit.get('code', '').strip()} {unit.get('title', '').strip()}{subject_label}"
                f" | delivery={unit.get('delivery', 'theory')}"
                f" | depth={unit.get('depth', 'standard')}"
                f" | prerequisites={prereq}"
                f" | corequisites={coreq}"
            )
        return "\n".join(lines)

    def _semester_curriculum_context(self, year: str, semester: str, *, include_all_pathway: bool = False) -> str:
        if self._is_multi_subject_degree():
            course_units = (
                self._all_semester_course_units_ps(year, semester)
                if include_all_pathway
                else self._semester_course_units(year, semester)
            )
            subject_guidance: list[str] = []
            subjects = self._pathway_subjects() if include_all_pathway else ([self.active_subject] if self.active_subject else [])
            names = self._multi_subject_full_names()
            styles = self._multi_subject_teaching_styles()
            for subject in subjects:
                if not subject:
                    continue
                style = styles.get(subject, {})
                if style:
                    subject_guidance.append(
                        f"- {subject} ({names.get(subject, subject)}): {style.get('discipline', '')}; {style.get('emphasis', '')}"
                    )
            block = self._course_unit_list_text(course_units)
            guidance = "\n".join(subject_guidance)
            return (
                f"Official curriculum source: {UNIVERSITY_NAME} Faculty of Science Student Handbook 2024/2025 ({KELANIYA_SCIENCE_HANDBOOK_URL})\n"
                f"Official course units for {year} {semester}:\n{block or '- No official course units loaded'}\n"
                f"Subject teaching guidance:\n{guidance or '- No subject guidance loaded'}"
            )
        course_units = self._semester_course_units(year, semester)
        discipline = FLAT_DEGREE_DISCIPLINE.get(self.degree, self.degree or "Unknown degree")
        if self.degree == "Software Engineering":
            guidance = f"- Software Engineering: {SE_TEACHING_STYLE['discipline']}; {SE_TEACHING_STYLE['emphasis']}"
            source_line = f"Official curriculum source: {UNIVERSITY_NAME} Faculty of Science Student Handbook 2024/2025 ({KELANIYA_SCIENCE_HANDBOOK_URL})"
        elif self.degree == "Electronics and Computer Science (BECS)":
            guidance = f"- Electronics and Computer Science (BECS): {BECS_TEACHING_STYLE['discipline']}; {BECS_TEACHING_STYLE['emphasis']}"
            source_line = f"Official curriculum source: {UNIVERSITY_NAME} Faculty of Science Student Handbook 2024/2025 ({KELANIYA_SCIENCE_HANDBOOK_URL})"
        else:
            guidance = f"- {discipline}: teach core concepts clearly with practical examples; balance theory and applied problem-solving."
            source_line = f"Degree: {self.degree} | Discipline: {discipline} | Generic international curriculum"
        block = self._course_unit_list_text(course_units)
        flat_curriculum = FLAT_DEGREE_CURRICULUM.get(self.degree)
        courses = flat_curriculum.get(year, {}).get(semester, []) if flat_curriculum is not None else []
        courses_text = "\n".join(f"  - {c.split(':', 1)[-1]}" for c in courses) if courses else ""
        if not block and courses_text:
            block = courses_text
        return (
            f"{source_line}\n"
            f"Official course units for {year} {semester}:\n{block or '- No official course units loaded'}\n"
            f"Subject teaching guidance:\n{guidance}"
        )

    def _compressed_curriculum_for_entry(self, year: str, semester: str, entry: dict[str, Any]) -> str:
        """Current unit row + prerequisite rows only (token-efficient)."""
        units = self._semester_course_units(year, semester)
        if not units:
            return "- No course unit rows loaded for this semester."
        hint = str(entry.get("unit", "") or "").strip()
        matched: dict[str, Any] | None = None
        for u in units:
            code = str(u.get("code", "") or "").strip()
            title = str(u.get("title", "") or "").strip()
            if code and code in hint:
                matched = u
                break
            if title and title.lower() in hint.lower():
                matched = u
                break
        if matched is None:
            matched = units[0]
        chunks: list[str] = [self._course_unit_list_text([matched])]
        prereq_codes = list(matched.get("prerequisites") or [])
        if prereq_codes:
            for u in units:
                c = str(u.get("code", "") or "").strip()
                if c and c in prereq_codes:
                    chunks.append(self._course_unit_list_text([u]))
        body = "\n".join(chunks)
        return (f"Focused curriculum (current unit + prerequisites):\n{body}")[:3600]

    def _plan_matches_semester(self, plan: list, year: str, semester: str) -> bool:
        if not plan:
            return True

        expected_courses = self._semester_courses(year, semester)
        expected = {
            self._normalize_course_label(course)
            for course in expected_courses
            if self._normalize_course_label(course)
        }
        if not expected:
            return True

        subjects: list[str] = []
        for entry in plan[:20]:
            subject = self._normalize_course_label(str(entry.get("subject", "")))
            if subject and subject not in subjects:
                subjects.append(subject)

        if not subjects:
            return False

        # Lenient matching: check word overlap between plan subjects and expected courses
        expected_words = set()
        for course in expected:
            for w in course.split():
                if len(w) >= 4:
                    expected_words.add(w)

        for subject in subjects:
            # Direct or substring match
            for course in expected:
                if subject == course or subject in course or course in subject:
                    return True
            # Word overlap: if 2+ significant words match, accept it
            subj_words = {w for w in subject.split() if len(w) >= 4}
            if len(subj_words & expected_words) >= 2:
                return True

        return False

    def _current_courses_for_scope(self) -> list[str]:
        if self.view_mode != "semester" or not self.selected_year or not self.selected_semester:
            return []
        return self._semester_courses(self.selected_year, self.selected_semester)

    def _set_default_semester_workspace(self, uid: int, year: str, semester: str, *, load_scope: bool = True) -> str:
        if uid < 0 or not year or not semester:
            return ""
        scope = self._scope_key(year, semester)
        self.selected_year = year
        self.selected_semester = semester
        if self._is_multi_subject_degree():
            self.active_subject = self._active_subject_for_semester(year, semester)
        self.view_mode = "semester"
        self.active_scope = scope
        self.show_semester_sidebar = False
        self.show_subject_switcher = False
        self._save_memory(uid)
        if load_scope:
            self._switch_scope(uid, scope)
        return scope

    def _ensure_scope_memory(self, uid: int, scope: str) -> None:
        if uid < 0:
            return
        with rx.session() as session:
            row = session.exec(
                select(ScopeMemory).where(ScopeMemory.user_id == uid).where(ScopeMemory.scope == scope)
            ).one_or_none()
            if row is None:
                session.add(ScopeMemory(user_id=uid, scope=scope, summary=""))  # type: ignore
                session.commit()

    def _get_scope_summary(self, uid: int, scope: str) -> str:
        if uid < 0:
            return ""
        with rx.session() as session:
            row = session.exec(
                select(ScopeMemory).where(ScopeMemory.user_id == uid).where(ScopeMemory.scope == scope)
            ).one_or_none()
        return (row.summary if row else "") or ""

    def _set_scope_summary(self, uid: int, scope: str, text: str) -> None:
        if uid < 0:
            return
        with rx.session() as session:
            row = session.exec(
                select(ScopeMemory).where(ScopeMemory.user_id == uid).where(ScopeMemory.scope == scope)
            ).one_or_none()
            if row is None:
                row = ScopeMemory(user_id=uid, scope=scope, summary="")  # type: ignore
            row.summary = (text or "")[:4000]
            session.add(row)
            session.commit()

    def _get_all_scope_summaries_text(self, uid: int) -> str:
        if uid < 0:
            return ""
        with rx.session() as session:
            rows = session.exec(
                select(ScopeMemory).where(ScopeMemory.user_id == uid).order_by(ScopeMemory.scope)
            ).all()
        return "\n\n".join(
            f"{r.scope}\n{r.summary}".strip()
            for r in rows
            if r.scope not in ("home", ADAPTIVE_PROFILE_SCOPE) and (r.summary or "").strip()
        )

    @rx.event
    def delete_session(self, session_id: str):
        uid = self._active_data_uid()
        if uid < 0 or not session_id:
            return
        try:
            sid = int(session_id)
            if not self._session_in_scope(uid, sid, self.active_scope):
                return
            with rx.session() as session:
                for m in session.exec(select(ChatMessage2).where(ChatMessage2.session_id == sid)).all():
                    session.delete(m)
                sess = session.exec(select(ChatSession).where(ChatSession.id == sid)).one_or_none()
                if sess:
                    session.delete(sess)
                session.commit()
            _delete_chat_media_for_session(uid, sid)
            if self.current_session_id == session_id:
                self.current_session_id = ""
                self.current_session_choice = ""
                self._ensure_session(uid, self.active_scope)
                self._load_messages(uid)
            self._load_sessions(uid, self.active_scope)
        except Exception as e:
            print(f"ERROR delete_session: {e}")

    @rx.event
    def delete_home_session(self, session_id: str):
        """Delete an Alex AI home chat session (works from any scope)."""
        uid = self._active_data_uid()
        if uid < 0 or not session_id:
            return
        try:
            sid = int(session_id)
            if not self._session_in_scope(uid, sid, "home"):
                return
            with rx.session() as session:
                for m in session.exec(select(ChatMessage2).where(ChatMessage2.session_id == sid)).all():
                    session.delete(m)
                sess = session.exec(select(ChatSession).where(ChatSession.id == sid)).one_or_none()
                if sess:
                    session.delete(sess)
                session.commit()
            _delete_chat_media_for_session(uid, sid)
            # If we're on home and deleted the active session, reset
            if self.active_scope == "home" and self.current_session_id == session_id:
                self.current_session_id = ""
                self.current_session_choice = ""
                self._ensure_session(uid, "home")
                self._load_messages(uid)
                self._load_sessions(uid, "home")
            # Always refresh home_sessions for the sidebar
            self._load_home_sessions(uid)
        except Exception as e:
            print(f"ERROR delete_home_session: {e}")

    @rx.event
    def start_rename_session(self, session_id: str, is_home: bool):
        """Open inline rename for a chat session."""
        self.renaming_session_id = session_id
        self.renaming_is_home = is_home
        # Pre-fill with current title
        session_list = self.home_sessions if is_home else self.sessions
        for s in session_list:
            if s.get("id") == session_id:
                self.renaming_title_input = s.get("title", "")
                break

    @rx.event
    def set_rename_title_input(self, value: str):
        self.renaming_title_input = value

    @rx.event
    def cancel_rename_session(self):
        self.renaming_session_id = ""
        self.renaming_is_home = False
        self.renaming_title_input = ""

    @rx.event
    def confirm_rename_session(self):
        """Save the new title to DB."""
        uid = self._active_data_uid()
        sid_str = self.renaming_session_id
        new_title = (self.renaming_title_input or "").strip()
        if uid < 0 or not sid_str or not new_title:
            self.renaming_session_id = ""
            self.renaming_is_home = False
            self.renaming_title_input = ""
            return
        try:
            sid = int(sid_str)
            with rx.session() as session:
                sess = session.exec(
                    select(ChatSession).where(ChatSession.id == sid).where(ChatSession.user_id == uid)
                ).one_or_none()
                if sess:
                    sess.title = new_title[:80]
                    session.add(sess)
                    session.commit()
            if self.renaming_is_home:
                self._load_home_sessions(uid)
            else:
                self._load_sessions(uid, self.active_scope)
        except Exception as e:
            print(f"ERROR confirm_rename_session: {e}")
        finally:
            self.renaming_session_id = ""
            self.renaming_is_home = False
            self.renaming_title_input = ""

    @rx.event
    def open_global_search(self):
        """Open global search once (avoids double-toggle if the same tap hits a new backdrop)."""
        if self.show_global_search:
            return
        self._notes_persist_editor(manual=False)
        self.show_notes_panel = False
        self.show_global_search = True

    @rx.event
    def close_global_search(self):
        if not self.show_global_search:
            return
        self.show_global_search = False
        self.global_search_query = ""
        self.global_search_results = []

    @rx.event
    def toggle_global_search(self):
        """Toggle global search (backdrop / nav rail); sidebar icon uses open_global_search."""
        if self.show_global_search:
            self.show_global_search = False
            self.global_search_query = ""
            self.global_search_results = []
        else:
            self._notes_persist_editor(manual=False)
            self.show_notes_panel = False
            self.show_global_search = True

    @rx.event
    def set_global_search_query(self, value: str):
        self.global_search_query = value
        if not value.strip():
            self.global_search_results = []
            return
        uid = self._active_data_uid()
        if uid < 0:
            return
        q = value.strip().lower()
        try:
            with rx.session() as session:
                # Search all sessions this user has
                all_sessions = session.exec(
                    select(ChatSession).where(ChatSession.user_id == uid)
                ).all()
                sess_map = {int(s.id): s for s in all_sessions}
                # Search messages that match the query
                rows = session.exec(
                    select(ChatMessage2)
                    .where(ChatMessage2.user_id == uid)
                    .where(func.lower(ChatMessage2.content).contains(q))
                    .order_by(ChatMessage2.id.desc())
                    .limit(40)
                ).all()
            seen_sessions: set[int] = set()
            results: list[dict] = []
            for msg in rows:
                sid = msg.session_id
                if sid in seen_sessions:
                    continue
                seen_sessions.add(sid)
                sess = sess_map.get(sid)
                if sess is None:
                    continue
                snippet = (msg.content or "").replace("\n", " ").strip()[:120]
                session_scope = (sess.scope or "home")
                base_scope = session_scope.split(":", 1)[0]
                scope_info = SCOPE_ROUTE_MAP.get(base_scope, {})
                subject_suffix = ""
                if ":" in session_scope:
                    subject_code = session_scope.split(":", 1)[1]
                    subject_suffix = f" · {subject_code_display_name(subject_code)}"
                scope_label = (
                    (f"{scope_info.get('year','')} {scope_info.get('semester','')}".strip() + subject_suffix).strip()
                    or ("Alex AI" if session_scope == "home" else session_scope)
                )
                results.append({
                    "session_id": str(sid),
                    "scope": session_scope,
                    "session_title": sess.title or "Chat",
                    "scope_label": scope_label,
                    "snippet": snippet,
                })
                if len(results) >= 12:
                    break
            self.global_search_results = results
        except Exception as e:
            print(f"ERROR global_search: {e}")
            self.global_search_results = []

    @rx.event
    async def open_search_result(self, session_id: str, scope: str):
        """Navigate to the session containing the search result."""
        uid = self._active_data_uid()
        if uid < 0:
            return
        target_scope = (scope or "home").strip()
        base_scope, _, subject_code = target_scope.partition(":")
        self.show_global_search = False
        self.global_search_query = ""
        self.global_search_results = []
        if target_scope == "home":
            target_route = self._workspace_home_route()
            current_path = str(getattr(self.router.url, "path", "") or "")
            if self.active_scope == "home" and self.view_mode == "home":
                if self._session_in_scope(uid, int(session_id), "home"):
                    self.current_session_id = session_id
                    self._load_messages(uid)
                    if target_route == "/free":
                        yield rx.call_script(self._workspace_home_chat_history_script(session_id))
                        yield rx.call_script(SCROLL_TO_BOTTOM_JS)
                    elif current_path != target_route:
                        yield _hard_navigate(target_route)
                    else:
                        yield rx.call_script(SCROLL_TO_BOTTOM_JS)
                return
            self.active_scope = "home"
            self.view_mode = "home"
            self.current_session_id = session_id
            yield _hard_navigate(
                self._workspace_home_chat_route(session_id) if target_route == "/free" else target_route
            )
            return
        else:
            scope_info = SCOPE_ROUTE_MAP.get(base_scope, {})
            if scope_info:
                if subject_code:
                    self.active_subject = subject_code
                    self._save_memory(uid)
                self.current_session_id = session_id
                yield _hard_navigate(scope_to_route(target_scope))
        with rx.session() as session:
            sess = session.exec(
                select(ChatSession)
                .where(ChatSession.user_id == uid)
                .where(ChatSession.scope == target_scope)
                .order_by(ChatSession.updated_at.desc())
            ).first()
            if sess is None:
                sess = ChatSession(user_id=uid, scope=target_scope)  # type: ignore
                session.add(sess)
                session.commit()
                session.refresh(sess)
            self.current_session_id = str(sess.id)
            self.current_session_choice = f"{sess.id}::{sess.title}"

    def _notes_scope_key(self) -> str:
        return (self.active_scope or "home").strip() or "home"

    def _migrate_legacy_learn_notes_to_home(self, uid: int, scope: str) -> None:
        if uid < 0 or scope != "home":
            return
        try:
            with rx.session() as session:
                existing_bodies = {
                    str(body or "")
                    for body in session.exec(
                        select(StudentNote.body)
                        .where(StudentNote.user_id == uid)
                        .where(StudentNote.scope == "home")
                    ).all()
                }
                rows = session.exec(
                    select(StudentNote)
                    .where(StudentNote.user_id == uid)
                    .where(StudentNote.scope.startswith("learn:"))
                ).all()
                changed = False
                for row in rows:
                    body = str(row.body or "")
                    if body in existing_bodies:
                        session.delete(row)
                    else:
                        row.scope = "home"
                        session.add(row)
                        existing_bodies.add(body)
                    changed = True
                if changed:
                    session.commit()
        except Exception as e:
            print(f"ERROR _migrate_legacy_learn_notes_to_home: {e}")

    def _reload_notes_items(self) -> None:
        uid = self._active_data_uid()
        self.notes_items = []
        if uid < 0:
            self.notes_header_subtitle = ""
            return
        scope = self._notes_scope_key()
        self._migrate_legacy_learn_notes_to_home(uid, scope)
        try:
            with rx.session() as session:
                rows = session.exec(
                    select(StudentNote)
                    .where(StudentNote.user_id == uid)
                    .where(StudentNote.scope == scope)
                    .order_by(StudentNote.updated_at.desc())
                ).all()
            items: list[dict] = []
            for r in rows:
                prev = _note_preview_from_body(r.body or "")
                if not prev:
                    prev = _note_empty_preview_from_attachments(getattr(r, "attachments_json", "") or "[]")
                items.append({
                    "id": str(r.id),
                    "title": (r.title or "").strip() or "Untitled",
                    "preview": prev,
                    "updated": r.updated_at.isoformat() if getattr(r, "updated_at", None) else "",
                })
            self.notes_items = items
        except Exception as e:
            print(f"ERROR _reload_notes_items: {e}")
            self.notes_items = []
        self.notes_header_subtitle = self._format_notes_scope_label(scope)

    def _format_notes_scope_label(self, scope: str) -> str:
        sc = (scope or "").strip() or "home"
        if sc == "home":
            return "Alex AI"
        base, _, subj = sc.partition(":")
        info = SCOPE_ROUTE_MAP.get(base, {})
        label = f"{info.get('year', '')} {info.get('semester', '')}".strip()
        if subj:
            label = f"{label} · {subject_code_display_name(subj)}".strip()
        return label or sc

    def _notes_editor_has_saveable_content(self) -> bool:
        if (self.notes_editor_title or "").strip():
            return True
        if (self.notes_editor_body or "").strip():
            return True
        if self.notes_attachments:
            return True
        return False

    def _notes_resolve_title(self, *, for_manual: bool) -> str | None:
        raw = (self.notes_editor_title or "").strip()
        body = (self.notes_editor_body or "").strip()
        if for_manual:
            return raw if raw else None
        if raw:
            return raw
        if body:
            return _note_title_from_body(body)
        if self.notes_attachments:
            return "Untitled"
        return None

    def _notes_persist_editor(self, *, manual: bool, scope_key: str | None = None) -> bool:
        """Manual save requires a non-empty title. Auto-save may infer title from body or use \"Untitled\"."""
        uid = self._active_data_uid()
        if uid < 0:
            return True
        if not self._notes_editor_has_saveable_content():
            self.notes_editor_error = ""
            return True
        scope = (scope_key if scope_key is not None else self._notes_scope_key()).strip() or "home"
        title = self._notes_resolve_title(for_manual=manual)
        if title is None:
            if manual:
                self.notes_editor_error = "Add a title before saving."
            return False
        self.notes_editor_error = ""
        body = self.notes_editor_body or ""
        att_json = _slim_note_attachments_for_db(self.notes_attachments)
        try:
            with rx.session() as session:
                if self.notes_editor_id:
                    nid = int(self.notes_editor_id)
                    row = session.get(StudentNote, nid)
                    if row is None or row.user_id != uid or row.scope != scope:
                        if manual:
                            self.notes_editor_error = "Could not save this note."
                        return False
                    row.title = title
                    row.body = body
                    row.attachments_json = att_json
                    session.add(row)
                else:
                    row = StudentNote(
                        user_id=uid,
                        scope=scope,
                        title=title,
                        body=body,
                        attachments_json=att_json,
                        source_message_db_id=0,
                    )
                    session.add(row)
                session.commit()
                session.refresh(row)
                self.notes_editor_id = str(row.id)
                self.notes_upload_bucket = f"n{row.id}"
                self.notes_attachments = _sign_note_attachment_records(
                    _parse_note_attachments_json(row.attachments_json)
                )
            self._reload_notes_items()
            return True
        except Exception as e:
            print(f"ERROR _notes_persist_editor: {e}")
            if manual:
                self.notes_editor_error = "Could not save. Try again."
            return False

    def _notes_reset_blank_editor_keep_panel(self) -> None:
        """Clear the in-memory editor (e.g. after autosave when switching workspace)."""
        self.notes_editor_id = ""
        self.notes_editor_title = ""
        self.notes_editor_body = ""
        self.notes_attachments = []
        self.notes_upload_bucket = f"d{secrets.token_hex(6)}"
        self.notes_attachment_error = ""
        self.notes_editor_error = ""

    @rx.event
    def toggle_notes_panel(self):
        if self.show_notes_panel:
            self._notes_persist_editor(manual=False)
            self.show_notes_library_drawer = False
        self.show_notes_panel = not self.show_notes_panel
        if self.show_notes_panel:
            self.show_global_search = False
            self.show_notes_library_drawer = False
            self._reload_notes_items()
            if not self.notes_editor_id and not self.notes_upload_bucket:
                self.notes_upload_bucket = f"d{secrets.token_hex(6)}"

    @rx.event
    def close_notes_panel(self):
        self._notes_persist_editor(manual=False)
        self.show_notes_panel = False
        self.show_notes_library_drawer = False

    @rx.event
    def toggle_notes_library_drawer(self):
        self.show_notes_library_drawer = not self.show_notes_library_drawer

    @rx.event
    def close_notes_library_drawer(self):
        self.show_notes_library_drawer = False

    @rx.event
    def set_notes_editor_title(self, v: str):
        self.notes_editor_title = v
        self.notes_editor_error = ""

    @rx.event
    def set_notes_editor_body(self, v: str):
        self.notes_editor_body = v
        self.notes_editor_error = ""

    @rx.event
    def notes_new_blank(self):
        self._notes_persist_editor(manual=False)
        self.notes_editor_id = ""
        self.notes_editor_title = ""
        self.notes_editor_body = ""
        self.notes_attachments = []
        self.notes_upload_bucket = f"d{secrets.token_hex(6)}"
        self.notes_attachment_error = ""
        self.notes_editor_error = ""
        self.show_notes_library_drawer = False

    def _ensure_notes_upload_bucket(self) -> None:
        if not (self.notes_upload_bucket or "").strip():
            self.notes_upload_bucket = f"d{secrets.token_hex(6)}"

    def _append_note_attachment_bytes(
        self, uid: int, filename: str, file_bytes: bytes, content_type: str, expect: str
    ) -> bool:
        if uid < 0 or not self.show_notes_panel:
            return False
        if len(self.notes_attachments) >= MAX_NOTE_ATTACHMENTS:
            self.notes_attachment_error = f"Maximum {MAX_NOTE_ATTACHMENTS} attachments per note."
            return False
        self._ensure_notes_upload_bucket()
        kind, mime, err = _classify_note_attachment(filename, content_type, file_bytes, expect)
        if not kind:
            self.notes_attachment_error = err or "Could not attach file."
            return False
        try:
            rel = _store_note_attachment(uid, self.notes_upload_bucket, filename, file_bytes)
        except Exception as e:
            self.notes_attachment_error = f"Could not save file: {e}"
            return False
        aid = secrets.token_hex(6)
        item = {"id": aid, "kind": kind, "name": filename or "file", "rel": rel, "mime": mime}
        signed = _sign_note_attachment_records([item])[0]
        self.notes_attachments = [*self.notes_attachments, signed]
        self.notes_attachment_error = ""
        return True

    @rx.event
    async def handle_note_media_upload(self, files: list[rx.UploadFile]):
        uid = self._active_data_uid()
        if not files or uid < 0:
            return
        uf = files[0]
        data = await uf.read()
        expect = _note_media_upload_expect(uf.filename or "file", uf.content_type or "")
        self._append_note_attachment_bytes(uid, uf.filename or "file", data, uf.content_type or "", expect)

    @rx.event
    def notes_remove_attachment(self, att_id: str):
        uid = self._active_data_uid()
        if not att_id:
            return
        rel_drop = ""
        kept: list[dict] = []
        for a in self.notes_attachments:
            if str(a.get("id")) == str(att_id):
                rel_drop = (a.get("rel") or "").strip()
                continue
            kept.append(a)
        self.notes_attachments = kept
        if rel_drop and uid >= 0:
            _delete_note_attachment_paths(uid, [rel_drop])

    def _load_note_for_editor(self, note_id: str) -> None:
        uid = self._active_data_uid()
        if uid < 0 or not note_id:
            return
        scope = self._notes_scope_key()
        try:
            nid = int(note_id)
        except (ValueError, TypeError):
            return
        try:
            with rx.session() as session:
                row = session.get(StudentNote, nid)
                if row is None or row.user_id != uid or row.scope != scope:
                    return
                self.notes_editor_id = str(row.id)
                self.notes_editor_title = row.title or ""
                self.notes_editor_body = row.body or ""
                self.notes_upload_bucket = f"n{row.id}"
                self.notes_attachment_error = ""
                self.notes_attachments = _sign_note_attachment_records(
                    _parse_note_attachments_json(getattr(row, "attachments_json", None) or "[]")
                )
                self.notes_editor_error = ""
        except Exception as e:
            print(f"ERROR _load_note_for_editor: {e}")

    @rx.event
    def notes_select(self, note_id: str):
        nid = (note_id or "").strip()
        if not nid:
            return
        if nid == (self.notes_editor_id or "").strip():
            return
        self._notes_persist_editor(manual=False)
        self._load_note_for_editor(nid)
        self.show_notes_library_drawer = False

    @rx.event
    def open_note_in_panel(self, note_id: str):
        """Open Notes and load a saved note by id."""
        if not (note_id or "").strip():
            return
        nid = note_id.strip()
        if nid != (self.notes_editor_id or "").strip():
            self._notes_persist_editor(manual=False)
        self.show_notes_panel = True
        self.show_global_search = False
        self.show_notes_library_drawer = False
        self._reload_notes_items()
        self._load_note_for_editor(nid)

    @rx.event
    def notes_save_editor(self):
        self._notes_persist_editor(manual=True)

    @rx.event
    def notes_delete_current(self):
        uid = self._active_data_uid()
        if uid < 0 or not self.notes_editor_id:
            return
        scope = self._notes_scope_key()
        try:
            nid = int(self.notes_editor_id)
        except (ValueError, TypeError):
            return
        try:
            with rx.session() as session:
                row = session.get(StudentNote, nid)
                if row is None or row.user_id != uid or row.scope != scope:
                    return
                rels = [
                    str(a.get("rel") or "").strip()
                    for a in _parse_note_attachments_json(getattr(row, "attachments_json", None) or "[]")
                    if a.get("rel")
                ]
                session.delete(row)
                session.commit()
            _delete_note_attachment_paths(uid, rels)
            self.notes_editor_id = ""
            self.notes_editor_title = ""
            self.notes_editor_body = ""
            self.notes_attachments = []
            self.notes_upload_bucket = ""
            self.notes_attachment_error = ""
            self.notes_editor_error = ""
            self._reload_notes_items()
        except Exception as e:
            print(f"ERROR notes_delete_current: {e}")

    @rx.event
    async def save_reply_as_note(self, msg_index: int):
        uid = self._active_data_uid()
        if uid < 0 or msg_index < 0 or msg_index >= len(self.chat_history):
            return
        m = self.chat_history[msg_index]
        if not isinstance(m, dict) or m.get("role") != "assistant":
            return
        body = (m.get("content") or "").strip()
        if not body:
            return
        scope = self._notes_scope_key()
        title = _note_title_from_body(body)
        try:
            src_id = int(m.get("db_id") or 0)
        except (ValueError, TypeError):
            src_id = 0
        try:
            with rx.session() as session:
                row = StudentNote(
                    user_id=uid,
                    scope=scope,
                    title=title,
                    body=body,
                    attachments_json="[]",
                    source_message_db_id=src_id,
                )
                session.add(row)
                session.commit()
                session.refresh(row)
                note_id_str = str(row.id)
            self._reload_notes_items()
            # Stable id: Sonner replaces an existing toast with the same id instead of stacking;
            # also avoids duplicate toasts if the handler runs more than once.
            yield rx.toast(
                "",
                id="alex-note-saved",
                title="Saved to Notes",
                description="Reply saved to workspace notes.",
                unstyled=True,
                class_name="note-saved-toast",
                style=_NOTE_SAVED_TOAST_STYLE,
                action=ToastAction(
                    label="View",
                    on_click=AppState.open_note_in_panel(note_id_str),
                ),
                duration=9000,
                close_button=True,
                position="bottom-right",
            )
        except Exception as e:
            print(f"ERROR save_reply_as_note: {e}")
            yield rx.toast.error(
                "Could not save to Notes. Try again.",
                id="alex-note-save-error",
                duration=6000,
                position="bottom-right",
            )

    def _session_in_scope(self, uid: int, sid: int, scope: str) -> bool:
        if uid < 0 or sid <= 0:
            return False
        with rx.session() as session:
            sess = session.exec(
                select(ChatSession)
                .where(ChatSession.id == sid)
                .where(ChatSession.user_id == uid)
            ).one_or_none()
        return bool(sess and sess.scope == scope)

    def _reset_scope_workspace(self, uid: int, scope: str) -> None:
        if uid < 0 or not scope:
            return
        with rx.session() as session:
            sessions = session.exec(
                select(ChatSession)
                .where(ChatSession.user_id == uid)
                .where(ChatSession.scope == scope)
            ).all()
            for sess in sessions:
                messages = session.exec(
                    select(ChatMessage2).where(ChatMessage2.session_id == int(sess.id))
                ).all()
                for msg in messages:
                    session.delete(msg)
                session.delete(sess)

            plan = session.exec(
                select(SemesterStudyPlan)
                .where(SemesterStudyPlan.user_id == uid)
                .where(SemesterStudyPlan.scope == scope)
            ).one_or_none()
            if plan is not None:
                session.delete(plan)

            progress = session.exec(
                select(DayProgress)
                .where(DayProgress.user_id == uid)
                .where(DayProgress.scope == scope)
            ).one_or_none()
            if progress is not None:
                session.delete(progress)

            scope_memory = session.exec(
                select(ScopeMemory)
                .where(ScopeMemory.user_id == uid)
                .where(ScopeMemory.scope == scope)
            ).one_or_none()
            if scope_memory is not None:
                scope_memory.summary = ""
                session.add(scope_memory)

            session.commit()

    def _ensure_session(self, uid: int, scope: str) -> None:
        """Ensure a current session exists for the given scope; create one if needed.
        Prefer the most recently updated session that already has messages so reopening
        the workspace does not land on an empty 'new' session while older chats exist.
        """
        if uid < 0:
            return
        with rx.session() as session:
            rows = session.exec(
                select(ChatSession)
                .where(ChatSession.user_id == uid)
                .where(ChatSession.scope == scope)
                .order_by(ChatSession.updated_at.desc())
            ).all()
            if not rows:
                sess = ChatSession(user_id=uid, scope=scope)  # type: ignore
                session.add(sess)
                session.commit()
                session.refresh(sess)
                self.current_session_id = str(sess.id)
                self.current_session_choice = f"{sess.id}::{sess.title}"
                return
            chosen: ChatSession | None = None
            for s in rows:
                has_any = session.exec(
                    select(ChatMessage2.id)
                    .where(ChatMessage2.user_id == uid)
                    .where(ChatMessage2.session_id == int(s.id))
                    .limit(1)
                ).first()
                if has_any is not None:
                    chosen = s
                    break
            if chosen is None:
                chosen = rows[0]
            self.current_session_id = str(chosen.id)
            self.current_session_choice = f"{chosen.id}::{chosen.title}"

    def _load_sessions(self, uid: int, scope: str) -> None:
        with rx.session() as session:
            rows = session.exec(
                select(ChatSession)
                .where(ChatSession.user_id == uid)
                .where(ChatSession.scope == scope)
                .order_by(ChatSession.updated_at.desc())
            ).all()
        self.sessions = [{"id": str(r.id), "title": r.title} for r in rows]
        if not self.current_session_id and rows:
            first = rows[0]
            self.current_session_id = str(first.id)
            self.current_session_choice = f"{first.id}::{first.title}"

    def _load_home_sessions(self, uid: int) -> None:
        with rx.session() as session:
            rows = session.exec(
                select(ChatSession)
                .where(ChatSession.user_id == uid)
                .where(ChatSession.scope == "home")
                .order_by(ChatSession.updated_at.desc())
            ).all()
        self.home_sessions = [
            {"id": str(r.id), "title": r.title, "updated_at": r.updated_at.isoformat() if r.updated_at else ""}
            for r in rows
        ]

    def _migrate_legacy_messages_once(self, uid: int) -> None:
        with rx.session() as session:
            if session.exec(select(ChatMessage2).where(ChatMessage2.user_id == uid).limit(1)).first():
                return
            legacy = session.exec(select(ChatMessage).where(ChatMessage.user_id == uid).order_by(ChatMessage.id)).all()
            if not legacy:
                return
            sess = ChatSession(user_id=uid, scope="home", title="Imported chat")  # type: ignore
            session.add(sess)
            session.commit()
            session.refresh(sess)
            for m in legacy:
                session.add(
                    ChatMessage2(
                        user_id=uid,
                        session_id=int(sess.id),
                        role=self._safe_role(m.role),
                        content=m.content,
                    )
                )
            session.commit()

    def _assistant_content_meta(self, raw: str) -> dict[str, str]:
        safe = sanitize_for_ui(raw or "")
        cleaned, blocks = _extract_all_visual_blocks(safe)
        if blocks:
            all_html = "".join(_render_visual_html(vt, vj) for vt, vj in blocks)
            meta: dict[str, str] = {"content": cleaned}
            meta["visual_html"] = all_html
            meta["visual_type"] = blocks[0][0]
            meta["visual_title"] = _visual_title_from_json(blocks[0][0], blocks[0][1])
            return meta
        return {"content": cleaned if cleaned else safe}

    def _set_assistant_content(self, index: int, content: str) -> None:
        if index < 0 or index >= len(self.chat_history):
            return
        msg = self.chat_history[index]
        if not isinstance(msg, dict):
            return
        for k in ("visual_html", "visual_type", "visual_title"):
            if k in msg:
                del msg[k]
        msg.update(self._assistant_content_meta(content))
        if msg.get("visual_html"):
            self._sync_canvas_from_message(index, open_panel=False)

    def _assistant_system_message_dedupe_key(self, content: str) -> str:
        body = (content or "").strip()
        if not body or not self._assistant_body_wants_proceed_only(body):
            return ""
        return "\n".join(line.rstrip() for line in body.splitlines()).strip()

    def _collapse_repeated_system_assistant_messages(self) -> None:
        collapsed: list[dict] = []
        previous_key = ""
        for msg in self.chat_history or []:
            if not isinstance(msg, dict):
                continue
            if msg.get("role") == "assistant":
                key = self._assistant_system_message_dedupe_key(msg.get("content") or "")
                if key and key == previous_key:
                    continue
                previous_key = key
            else:
                previous_key = ""
            collapsed.append(msg)
        self.chat_history = collapsed

    def _load_messages(self, uid: int, scope: str = "", *, _trusted: bool = False) -> None:
        effective_scope = scope or self.active_scope
        self._clear_canvas_state()
        if not self.current_session_id:
            self.chat_history = []
            return
        sid = int(self.current_session_id)
        if not _trusted and not self._session_in_scope(uid, sid, effective_scope):
            self.current_session_id = ""
            self.current_session_choice = ""
            self.chat_history = []
            return
        with rx.session() as session:
            msgs = session.exec(
                select(ChatMessage2).where(ChatMessage2.user_id == uid).where(ChatMessage2.session_id == sid).order_by(ChatMessage2.id)
            ).all()

        self.chat_history = [
            (
                {
                    "role": m.role,
                    **(self._assistant_content_meta(m.content) if m.role == "assistant" else {"content": m.content}),
                    "db_id": str(m.id or 0),
                    "has_image": True,
                    "image_url": _signed_media_url(m.image_url),
                    **(
                        {
                            "has_document": True,
                            "document_name": m.document_name or "document",
                            "document_url": _signed_media_url(m.document_url or ""),
                        }
                        if m.has_document
                        else {}
                    ),
                }
                if m.has_image
                else (
                    {
                        "role": m.role,
                        **(self._assistant_content_meta(m.content) if m.role == "assistant" else {"content": m.content}),
                        "db_id": str(m.id or 0),
                        "has_document": True,
                        "document_name": m.document_name or "document",
                        "document_url": _signed_media_url(m.document_url or ""),
                    }
                    if m.has_document
                    else (
                        # Voice session summary — parse label + transcript for special rendering
                        {
                            "role": "voice_session",
                            "content": m.content,
                            "db_id": str(m.id or 0),
                            "voice_label": (m.content.split("\n", 1)[0]
                                            .replace("🎙️ [", "").rstrip("]")),
                            "voice_transcript": (m.content.split("\n", 1)[1].strip()
                                                 if "\n" in m.content else ""),
                        }
                        if m.role == "voice_session"
                        else {
                            "role": m.role,
                            **(self._assistant_content_meta(m.content) if m.role == "assistant" else {"content": m.content}),
                            "db_id": str(m.id or 0),
                        }
                    )
                )
            )
            for m in msgs
        ]

        for msg_dict, m in zip(self.chat_history, msgs):
            if m.role == "user":
                cd = (getattr(m, "content_display", None) or "").strip()
                if not cd:
                    cd = _followup_prompt_display_label(m.content)
                if cd:
                    msg_dict["content_display"] = cd
            if m.role == "assistant":
                body = (msg_dict.get("content") or "").strip()
                flags = (getattr(m, "assistant_flags", None) or "").strip()
                fup = ""
                if body.startswith("Moving to the next topic"):
                    fup = "proceed_only"
                elif self._assistant_body_wants_proceed_only(body):
                    fup = "proceed_only"
                elif "proceed_only" in flags:
                    fup = "proceed_only"
                if "no_deepen" in flags:
                    fup = "no_deepen"
                if fup:
                    msg_dict["followup_actions"] = fup

        self._collapse_repeated_system_assistant_messages()

        # Annotate messages with existing feedback
        if self.chat_history:
            try:
                with rx.session() as session:
                    feedbacks = session.exec(
                        select(MessageFeedback)
                        .where(MessageFeedback.user_id == uid)
                        .where(MessageFeedback.session_id == sid)
                    ).all()
                fb_map = {f.message_db_id: f.feedback_type for f in feedbacks}
                for msg_dict in self.chat_history:
                    db_id_str = msg_dict.get("db_id", "0")
                    try:
                        db_id = int(db_id_str)
                    except (ValueError, TypeError):
                        db_id = 0
                    if db_id in fb_map:
                        msg_dict["feedback"] = fb_map[db_id]
            except Exception:
                pass

    def _save_message(
        self,
        uid: int,
        role: str,
        content: str,
        scope: str = "",
        trusted: bool = False,
        *,
        has_image: bool = False,
        image_url: str = "",
        has_document: bool = False,
        document_name: str = "",
        document_url: str = "",
        content_display: str = "",
        assistant_flags: str = "",
    ) -> None:
        effective_scope = scope or self.active_scope
        if uid < 0 or not self.current_session_id:
            return
        if not trusted and not self._session_in_scope(uid, int(self.current_session_id), effective_scope):
            return
        safe_content = sanitize_for_ui(content) if role == "assistant" else content
        disp = (content_display or "").strip() if role == "user" else ""
        aflags = (assistant_flags or "").strip() if role == "assistant" else ""
        sid = int(self.current_session_id)
        dedupe_key = self._assistant_system_message_dedupe_key(safe_content) if role == "assistant" else ""
        with rx.session() as session:
            if dedupe_key:
                last_msg = session.exec(
                    select(ChatMessage2)
                    .where(ChatMessage2.user_id == uid)
                    .where(ChatMessage2.session_id == sid)
                    .order_by(ChatMessage2.id.desc())
                ).first()
                if (
                    last_msg is not None
                    and last_msg.role == "assistant"
                    and self._assistant_system_message_dedupe_key(last_msg.content) == dedupe_key
                ):
                    return
            session.add(
                ChatMessage2(
                    user_id=uid,
                    session_id=sid,
                    role=role,
                    content=safe_content,
                    content_display=disp,
                    assistant_flags=aflags,
                    has_image=has_image,
                    image_url=image_url or "",
                    has_document=has_document,
                    document_name=document_name or "",
                    document_url=document_url or "",
                )
            )
            session.commit()

    def _save_memory(self, uid: int) -> None:
        if uid < 0:
            return
        normalized_name = _normalize_person_name(self.name)
        if self.name != normalized_name:
            self.name = normalized_name
        with rx.session() as session:
            mem = session.exec(select(UserMemory).where(UserMemory.user_id == uid)).one_or_none()
            if mem is None:
                mem = UserMemory(user_id=uid)  # type: ignore
            mem.step = self.step; mem.name = normalized_name; mem.degree = self.degree
            mem.pathway = self.pathway; mem.active_subject = self.active_subject
            mem.is_started = self.is_started; mem.selected_year = self.selected_year; mem.selected_semester = self.selected_semester
            mem.summary = self.memory_summary
            mem.other_degree_text = self.other_degree_text or ""
            session.add(mem)
            session.commit()

    def _ensure_progress_for_year(self, uid: int, year: str) -> None:
        if uid < 0:
            return
        curriculum = FLAT_DEGREE_CURRICULUM.get(self.degree)
        if curriculum is None:
            return
        if year not in curriculum:
            return
        items, idx = [], 0
        for semester, courses in curriculum[year].items():
            for course in courses:
                items.append((semester, course, idx)); idx += 1
        with rx.session() as session:
            existing_set = set(session.exec(
                select(StudyProgress.course).where(StudyProgress.user_id == uid).where(StudyProgress.year == year)
            ).all())
            for semester, course, order_index in items:
                if course not in existing_set:
                    session.add(StudyProgress(user_id=uid, year=year, semester=semester, course=course, order_index=order_index))
            session.commit()

    def _get_next_courses(self, uid: int, year: str, n: int = 3) -> list[str]:
        if uid < 0 or not year:
            return []
        with rx.session() as session:
            rows = session.exec(
                select(StudyProgress).where(StudyProgress.user_id == uid).where(StudyProgress.year == year).where(StudyProgress.status != "done").order_by(StudyProgress.order_index)
            ).all()
        return [r.course for r in rows[:n]]

    def _refresh_today_plan(self, uid: int) -> None:
        if uid < 0 or not self.selected_year:
            self.today_plan = ""; return
        nxt = self._get_next_courses(uid, self.selected_year, 2)
        self.today_plan = "all done for this year" if not nxt else "\n".join([f"today focus {c}" for c in nxt])

    def _extract_json(self, text: str) -> dict:
        try: return json.loads(text)
        except Exception: pass
        try:
            a, b = text.find("{"), text.rfind("}")
            if a != -1 and b != -1 and b > a: return json.loads(text[a:b+1])
        except Exception: return {}
        return {}

    def _extract_json_list(self, text: str) -> list:
        return _parse_llm_json_plan_array(text)
        # ----------------------------
    # memory tuning
    # ----------------------------
    SCOPE_SUMMARY_TRIGGER_NEW_MSGS = 12
    GLOBAL_MEMORY_TRIGGER_NEW_MSGS = 24
    ADAPTIVE_PROFILE_TRIGGER_NEW_MSGS = 4
    PAST_HITS_LIMIT = 8
    PAST_HITS_MAX_CHARS = 220

    def _kw(self, text: str) -> list[str]:
        stop = {
            "this","that","with","have","what","when","your","from","they","them","then",
            "just","like","about","into","need","tell","give","does","done","only","more",
            "less","been","were","will","would","could","should","because","also","there",
            "here","want","make","please","help"
        }
        words = []
        for raw in (text or "").split():
            w = raw.strip(".,!?;:()[]{}'\"").lower()
            if len(w) < 4:
                continue
            if w.isdigit():
                continue
            if w in stop:
                continue
            if w not in words:
                words.append(w)
            if len(words) >= 6:
                break
        return words

    def _scope_session_ids(self, uid: int, scope: str) -> list[int]:
        if uid < 0:
            return []
        with rx.session() as session:
            rows = session.exec(
                select(ChatSession.id)
                .where(ChatSession.user_id == uid)
                .where(ChatSession.scope == scope)
            ).all()
        out: list[int] = []
        for r in rows:
            try:
                out.append(int(r))
            except Exception:
                try:
                    out.append(int(r[0]))
                except Exception:
                    pass
        return out

    def _memory_search_session_ids(self, uid: int, scope: str) -> list[int]:
        if scope != "home":
            return self._scope_session_ids(uid, scope)
        if uid < 0:
            return []
        with rx.session() as session:
            rows = session.exec(
                select(ChatSession.id)
                .where(ChatSession.user_id == uid)
            ).all()
        out: list[int] = []
        for r in rows:
            try:
                out.append(int(r))
            except Exception:
                try:
                    out.append(int(r[0]))
                except Exception:
                    pass
        return out

    def _recent_msgs_for_session(self, uid: int, sid: int, n: int = 18) -> list[dict]:
        with rx.session() as session:
            rows = session.exec(
                select(ChatMessage2)
                .where(ChatMessage2.user_id == uid)
                .where(ChatMessage2.session_id == sid)
                .order_by(ChatMessage2.id.desc())
                .limit(n)
            ).all()
        rows = list(reversed(rows))
        return [{"role": m.role, "content": m.content} for m in rows]

    def _recent_msgs_for_user(self, uid: int, n: int = 26) -> list[dict]:
        with rx.session() as session:
            rows = session.exec(
                select(ChatMessage2)
                .where(ChatMessage2.user_id == uid)
                .order_by(ChatMessage2.id.desc())
                .limit(n)
            ).all()
        rows = list(reversed(rows))
        return [{"role": m.role, "content": m.content} for m in rows]

    def _past_hits_text(self, uid: int, scope: str, user_msg: str) -> str:
        kws = self._kw(user_msg)
        if not kws:
            return ""

        sids = self._memory_search_session_ids(uid, scope)
        if not sids:
            return ""

        # Escape SQL LIKE wildcards to prevent injection
        def _escape_like(s: str) -> str:
            return s.replace("%", r"\%").replace("_", r"\_")

        conds = [func.lower(ChatMessage2.content).like(f"%{_escape_like(k)}%") for k in kws]

        with rx.session() as session:
            rows = session.exec(
                select(ChatMessage2)
                .where(ChatMessage2.user_id == uid)
                .where(ChatMessage2.session_id.in_(sids))
                .where(or_(*conds))
                .order_by(ChatMessage2.id.desc())
                .limit(self.PAST_HITS_LIMIT)
            ).all()

        if not rows:
            return ""

        lines = []
        for m in rows:
            c = (m.content or "").replace("\n", " ").strip()
            if len(c) > self.PAST_HITS_MAX_CHARS:
                c = c[: self.PAST_HITS_MAX_CHARS] + "..."
            lines.append(f"- {m.role}: {c}")
        return "\n".join(lines)

