        with rx.session() as session:
            cnt = session.exec(
                select(func.count())
                .select_from(ChatMessage2)
                .where(ChatMessage2.user_id == uid)
                .where(ChatMessage2.session_id.in_(sids))
                .where(ChatMessage2.created_at > since_dt)
            ).one()
        try:
            return int(cnt)
        except Exception:
            try:
                return int(cnt[0])
            except Exception:
                return 0

