    def _alex_guardrail_reply(self, text: str, student_name: str) -> str:
        if self._is_identity_question(text):
            return self._alex_identity_reply()
        if self._is_off_topic_request(text):
            return self._alex_focus_redirect(student_name)
        return ""

    def _is_visual_only_request(self, text: str) -> bool:
        lower = (text or "").lower()
        if not lower:
            return False
        visual_markers = (
            "visual",
            "diagram",
            "graph",
            "chart",
            "draw",
            "plot",
            "show me",
            "3d",
            "3-d",
            "three dimensional",
            "model",
            "image",
            "picture",
            "illustration",
        )
        no_text_markers = (
            "no text",
            "without text",
            "textless",
            "only visual",
            "visual only",
            "no explanation",
            "don't explain",
            "no more text",
            "only image",
            "image only",
            "only picture",
            "via an image",
            "via image",
            "just image",
            "just the image",
        )
        return any(v in lower for v in visual_markers) and any(n in lower for n in no_text_markers)

    def _is_visual_drawing_request(self, text: str) -> bool:
        lower = (text or "").lower().strip()
        if not lower:
            return False
        if "draw conclusion" in lower:
            return False

        # Catch any message containing an image/picture/drawing keyword alongside
        # a generation verb. This is resilient to typos and missing articles.
        image_nouns = ("image", "picture", "drawing", "illustration", "sketch", "visual", "photo")
        generation_verbs = (
            "draw", "sketch", "illustrate", "illustrat",
            "create", "generate", "make", "render", "produce",
            "show", "give", "build",
        )
        has_image_noun = any(
            re.search(rf"\b{re.escape(noun)}\b", lower) for noun in image_nouns
        )
        has_gen_verb = any(
            re.search(rf"\b{re.escape(v)}\w*\b", lower) for v in generation_verbs
        )
        if has_image_noun and has_gen_verb:
            return True

        # "explain X via an image", "X only image", "X via image" — image is the output format.
        via_image_markers = ("via an image", "via image", "via a picture", "via picture", "only image", "image only")
        if has_image_noun and any(m in lower for m in via_image_markers):
            return True

        # Safety net: classic draw/sketch/illustrate prompts with an object.
        draw_markers = (
            "draw ",
            "sketch",
            "illustrate",
            "illustration",
            "icon of",
            "picture of",
            "diagram of",
        )
        if any(m in lower for m in draw_markers):
            return True
        return False

    def _is_3d_model_request(self, text: str) -> bool:
        lower = (text or "").lower().strip()
        if not lower:
            return False
        return (
            ("3d" in lower or "3-d" in lower or "three dimensional" in lower)
            and any(k in lower for k in ("model", "viewer", "visual", "show", "teach", "explain", "diagram", "atom", "vector", "cube", "axis"))
        )

    def _is_teaching_request(self, text: str) -> bool:
        lower = (text or "").lower().strip()
        if not lower:
            return False
        teaching_markers = (
            "teach",
            "explain",
            "how to", "how do", "how does", "how can", "how is",
            "what is", "what are",
            "why is", "why are", "why do", "why does",
            "describe",
            "difference between",
            "compare",
            "details",
        )
        return any(m in lower for m in teaching_markers)

    def _is_deep_analysis_request(self, text: str) -> bool:
        raw = (text or "").strip()
        lower = raw.lower()
        if not lower:
            return False
        if raw == FOLLOWUP_DEEPEN_PROMPT:
            return True
        markers = (
            "in-depth",
            "indepth",
            "deep analysis",
            "deep dive",
            "analyze deeply",
            "go deeper",
            "explain in detail",
            "detailed analysis",
            "thorough explanation",
            "full analysis",
        )
        return any(marker in lower for marker in markers)

    def _is_rich_teaching_request(self, text: str, response_text: str = "") -> bool:
        raw = (text or "").strip()
        lower = raw.lower()
        if not lower:
            return False
        if self._is_deep_analysis_request(raw):
            return True
        teaching_like = self._is_teaching_request(raw)
        advanced_topic_markers = (
            "string theory",
            "relativity",
            "general relativity",
            "special relativity",
            "spacetime",
            "space-time",
            "quantum",
            "black hole",
            "wormhole",
            "brane",
            "extra dimension",
            "extra dimensions",
            "dimension",
            "dimensions",
            "field theory",
            "architecture",
            "algorithm",
            "network",
            "topology",
            "molecule",
            "atom",
            "dna",
            "protein",
        )
        concept_explainer_markers = (
            "explain",
            "teach",
            "what is",
            "what are",
            "how does",
            "how do",
            "why does",
            "why do",
            "describe",
            "compare",
            "difference between",
        )
        rich_topic = self._topic_needs_high_detail_visual(raw, response_text) or any(
            marker in lower for marker in advanced_topic_markers
        )
        concept_like = any(marker in lower for marker in concept_explainer_markers)
        return bool((teaching_like or concept_like) and rich_topic)

    def _topic_needs_high_detail_visual(self, user_msg: str, response_text: str = "") -> bool:
        combined = f"{user_msg}\n{response_text}".lower()
        if not combined.strip():
            return False
        keywords = (
            "animal", "frog", "toad", "lizard", "chameleon", "snake", "bird", "fish", "insect",
            "heart", "brain", "eye", "ear", "lung", "kidney", "liver", "skeleton", "muscle", "anatomy",
            "cell", "organelle", "mitochondria", "chloroplast", "dna", "molecule", "atom", "protein",
            "flower", "leaf", "root", "plant", "photosynthesis",
            "engine", "turbine", "gear", "machine", "robot", "circuit", "motherboard", "chip",
            "architecture", "building", "bridge", "network", "topology", "server rack", "system design",
            "solar system", "planet", "volcano", "rock layer", "map", "ecosystem", "orbit",
            "physics", "relativity", "general relativity", "spacetime", "space-time", "gravity", "gravitational",
            "curvature", "geodesic", "tensor", "field equation", "einstein", "quantum", "wave", "electric field",
            "magnetic field", "free body", "free-body", "force diagram",
            "string theory", "string vibration", "vibrating string", "brane", "branes", "extra dimension",
            "extra dimensions", "compactification", "calabi-yau", "quantum gravity",
            "blueprint", "schematic", "cross section", "cross-section", "internal structure", "callout", "annotated",
        )
        return any(keyword in combined for keyword in keywords)

    def _should_use_high_detail_image(
        self,
        user_msg: str,
        response_text: str = "",
        *,
        visual_only: bool = False,
    ) -> bool:
        if not OPENAI_API_KEY or not self.current_session_id:
            return False
        if self._is_3d_model_request(user_msg):
            return False
        lower = (user_msg or "").lower()
        explicit_high_detail = any(
            term in lower
            for term in (
                "high detail",
                "high-detail",
                "high quality",
                "detailed visual",
                "blueprint",
                "schematic",
                "technical illustration",
                "annotated drawing",
                "concept art",
                "realistic render",
            )
        )
        explicit_draw = self._is_visual_drawing_request(user_msg)
        deep_analysis = self._is_deep_analysis_request(user_msg)
        rich_topic = self._topic_needs_high_detail_visual(user_msg, response_text)
        auto_teaching_visual = _teaching_message_suggests_concept_figure(user_msg, response_text)
        is_followup_indepth = (user_msg or "").strip() == FOLLOWUP_DEEPEN_PROMPT

        # Any explicit request for an image/picture/drawing always uses the OpenAI image API.
        # We do not require the topic to be in the "rich topics" list.
        if explicit_draw:
            return True
        if visual_only and explicit_high_detail:
            return True
        if (deep_analysis or is_followup_indepth) and rich_topic:
            return True
        if rich_topic and auto_teaching_visual:
            return True
        return False

    def _visual_style_from_request(self, text: str) -> str:
        lower = (text or "").lower()
        if any(k in lower for k in ("blueprint", "technical", "schematic", "annotated")):
            return "blueprint"
        if any(k in lower for k in ("cartoon", "cute", "playful", "mascot")):
            return "cartoon"
        if any(k in lower for k in ("neon", "glow", "cyber", "futuristic")):
            return "neon"
        if any(k in lower for k in ("outline", "line art", "lineart", "stroke only", "wireframe")):
            return "outline"
        if any(k in lower for k in ("minimal", "flat", "clean", "simple")):
            return "minimal"
        return "minimal"

    def _visual_style_instruction(self, style: str) -> str:
        if style == "blueprint":
            return (
                "Use a blueprint SVG style: deep navy background, precise white/cyan linework, "
                "measurement marks, annotated callouts, and dense technical detail."
            )
        if style == "cartoon":
            return (
                "Use a cartoon SVG style: rounded shapes, friendly proportions, "
                "soft color palette, medium stroke width, and clear separation between objects."
            )
        if style == "neon":
            return (
                "Use a neon SVG style: dark background, high-contrast cyan/magenta/lime accents, "
                "glow-like highlights (without filters/scripts), and bold geometric composition."
            )
        if style == "outline":
            return (
                "Use an outline SVG style: mostly transparent/light background, no heavy fills, "
                "clean consistent strokes, and precise line structure."
            )
        return (
            "Use a minimal SVG style: flat shapes, restrained palette (2-4 colors), "
            "clean spacing, and low visual clutter. "
            "Always start with <rect width='100%' height='100%' fill='#ffffff'/> as the first element "
            "so the SVG has a white background and is readable on any surface."
        )

    def _high_detail_visual_style(self, text: str, response_text: str = "") -> str:
        lower = f"{text}\n{response_text}".lower()
        if any(k in lower for k in ("blueprint", "technical drawing", "schematic", "annotated", "callout")):
            return "blueprint"
        if any(k in lower for k in ("realistic", "photorealistic", "photo-realistic", "photo real")):
            return "realistic"
        if any(k in lower for k in ("anime", "manga", "illustration poster", "concept art")):
            return "concept"
        return "teaching"

    def _high_detail_image_size(self, text: str, response_text: str = "") -> str:
        lower = f"{text}\n{response_text}".lower()
        portrait_terms = (
            "portrait",
            "poster",
            "standing",
            "full body",
            "full-body",
            "character sheet",
            "person",
            "girl",
            "boy",
            "woman",
            "man",
        )
        if any(term in lower for term in portrait_terms):
            return "1024x1536"
        return "1536x1024"

    def _high_detail_focus_points(self, user_msg: str, response_text: str = "") -> list[str]:
        raw = (response_text or "").strip()
        if not raw:
            phrases = self._extract_subject_phrases(user_msg)
            return [p.strip().rstrip(".") for p in phrases[:3] if p.strip()]

        cleaned = re.sub(r"\[[^\]]+\]\([^)]+\)", "", raw)
        cleaned = re.sub(r"[*_`#>-]", " ", cleaned)
        cleaned = re.sub(r"\s+", " ", cleaned).strip()
        parts = re.split(r"(?<=[.!?])\s+|\n+", cleaned)

        points: list[str] = []
        for part in parts:
            sentence = re.sub(r"^\d+\.\s*", "", (part or "").strip())
            if not sentence:
                continue
            if len(sentence) < 28:
                continue
            if len(sentence) > 140:
                sentence = re.split(r"[;:]", sentence, maxsplit=1)[0].strip()
            sentence = sentence.rstrip(".")
            if 20 <= len(sentence) <= 110 and sentence not in points:
                points.append(sentence)
            if len(points) >= 4:
                break
        return points[:4]

    def _high_detail_image_prompt(self, user_msg: str, response_text: str = "") -> tuple[str, str]:
        combined = f"{user_msg}\n{response_text}".strip()
        subject = self._extract_subject_keyword(combined).strip() or "Detailed visual"
        subject_phrases = self._extract_subject_phrases(combined)
        subject_hint = ", ".join(subject_phrases[:4]) if subject_phrases else subject
        style = self._high_detail_visual_style(user_msg, response_text)
        title_base = subject.title()
        context_excerpt = re.sub(r"\s+", " ", (response_text or "").strip())[:900]
        common = (
            f"Create one educational visual for an interactive learning canvas based on this request: {user_msg.strip() or subject}. "
            f"Keep the subject unmistakably recognizable as {subject}. Relevant subject hints: {subject_hint}. "
            f"Use this teaching context when deciding the composition: {context_excerpt or 'No extra context available.'} "
            "The purpose is to help a student understand the topic quickly and clearly at first glance. "
            "Prioritize conceptual clarity over cinematic style. Use large shapes, one main idea, and 3 to 5 clearly separated components. "
            "Avoid dense poster layouts, decorative blueprint backgrounds, tiny labels, paragraphs, handwriting, and small unreadable text. "
            "If labels are used, keep them extremely short, large, and high-contrast. "
            "Use crisp edges, clean spacing, clear hierarchy, and a textbook-quality educational composition. "
            "No watermark, no UI chrome, no browser frame, no fake app screenshot, no logos unless explicitly requested."
        )
        if style == "blueprint":
            prompt = (
                common
                + " Render it as a clean technical teaching diagram with a restrained blueprint feel, but keep the layout simple and readable. "
                "Use a dark navy background only if contrast stays excellent. Show one main system with a few large arrows and no dense grid clutter. "
                "Use at most 4 short labels."
            )
            return prompt, f"{title_base} Blueprint"
        if style == "realistic":
            prompt = (
                common
                + " Render it as a polished high-end realistic concept image with rich materials, cinematic lighting, "
                "sharp details, subtle depth, and only a few large educational callouts."
            )
            return prompt, f"{title_base} Detailed Render"
        if style == "teaching":
            prompt = (
                common
                + " Render it as a simple teaching infographic: one central concept, big readable objects, strong arrows or grouping, "
                "minimal clutter, and a friendly modern educational look. "
                "Do not make it look like a poster, vintage blueprint, or busy collage. "
                "If the topic is a process, show the flow clearly from left to right or top to bottom. "
                "If the topic is a structure, show the main parts with visual separation."
            )
            return prompt, f"{title_base} Concept Visual"
        prompt = (
            common
            + " Render it as a polished editorial infographic illustration with exceptional detail, fine texture work, "
            "clear silhouette, premium lighting, layered composition, and only a few short labels or callouts that help explain the topic."
        )
        return prompt, f"{title_base} Concept Illustration"

    def _high_detail_image_block(self, user_msg: str, response_text: str = "") -> tuple[str, str]:
        """Returns (visual_block, error_message). visual_block is empty on failure."""
        uid = self._active_data_uid()
        if uid < 0 or not self.current_session_id:
            return "", "no active session"
        if not OPENAI_API_KEY:
            return "", "OPENAI_API_KEY not configured"
        prompt, title = self._high_detail_image_prompt(user_msg, response_text)
        size = self._high_detail_image_size(user_msg, response_text)
        image_bytes, mime, err = _openai_generate_image_bytes(prompt, size=size, quality="high")
        if not image_bytes:
            return "", err or "image generation returned empty"
        ext = {
            "image/png": ".png",
            "image/jpeg": ".jpg",
            "image/webp": ".webp",
        }.get((mime or "").lower(), ".png")
        media_path = _store_chat_media(
            uid,
            self.current_session_id,
            f"canvas-{_safe_filename_fragment(title.lower())}{ext}",
            image_bytes,
        )
        focus_points = self._high_detail_focus_points(user_msg, response_text)
        block = (
            "[VISUAL:type=illustration]\n"
            + json.dumps(
                {
                    "title": title,
                    "image_url": media_path,
                    "focus_points": focus_points,
                },
                ensure_ascii=False,
            )
        )
        return block, ""

    def _illustration_subject_instruction(self, text: str) -> str:
        lower = (text or "").lower()
        if "flower" in lower:
            return (
                "The subject is a flower. Include recognizable petals around a center, "
                "a stem, and at least one leaf."
            )
        if "atom" in lower:
            return (
                "The subject is an atom. Include a nucleus and multiple orbital paths "
                "with electrons."
            )
        if any(k in lower for k in ("object", "laptop", "phone", "car", "rocket", "house")):
            return (
                "The subject is a real object. Keep proportions recognizable and avoid abstract-only geometry."
            )
        return "Keep the subject visually recognizable at first glance."

    def _model3d_visual_block(self, user_msg: str) -> str:
        lower = (user_msg or "").lower()
        kind = _infer_model3d_kind(lower)
        topic = self._extract_subject_keyword(user_msg).title()
        if kind == "atom":
            data = {
                "title": f"3D {topic or 'Atom'} model",
                "model": "atom",
                "caption": "A simple 3D teaching model: the center is the nucleus, and the surrounding rings show electron shells in space.",
                "labels": ["Nucleus", "Shell", "Electron"],
            }
            return f"[VISUAL:type=model3d]\n{json.dumps(data, ensure_ascii=False)}"
        if kind == "axes":
            data = {
                "title": f"3D {topic or 'Vector'} model",
                "model": "axes",
                "caption": "Use the three axes to reason about direction, sign, and the final vector in space.",
                "labels": ["X-axis", "Y-axis", "Z-axis", "Vector"],
            }
            return f"[VISUAL:type=model3d]\n{json.dumps(data, ensure_ascii=False)}"
        data = {
            "title": f"3D {topic or 'Solid'} model",
            "model": "cube",
            "caption": "Rotate the solid to compare the front, top, and side faces while Alex explains the structure.",
            "labels": ["Front", "Top", "Side"],
        }
        return f"[VISUAL:type=model3d]\n{json.dumps(data, ensure_ascii=False)}"

    def _visual_only_fallback_block(self, user_msg: str) -> str:
        style = self._visual_style_from_request(user_msg)
        lower = (user_msg or "").lower()
        if "flower" in lower:
            bg = "#0b1020" if style == "neon" else "#f8fafc"
            petal = "#fb7185" if style != "outline" else "none"
            stroke = "#f43f5e" if style == "neon" else "#be123c"
            center = "#fde047"
            leaf = "#22c55e"
            stem = "#16a34a"
            svg = (
                "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 320 220'>"
                f"<rect width='320' height='220' fill='{bg}'/>"
                "<g transform='translate(160 90)'>"
                f"<ellipse cx='0' cy='-34' rx='18' ry='26' fill='{petal}' stroke='{stroke}' stroke-width='3'/>"
                f"<ellipse cx='30' cy='-18' rx='18' ry='26' fill='{petal}' stroke='{stroke}' stroke-width='3' transform='rotate(55)'/>"
                f"<ellipse cx='30' cy='18' rx='18' ry='26' fill='{petal}' stroke='{stroke}' stroke-width='3' transform='rotate(125)'/>"
                f"<ellipse cx='0' cy='34' rx='18' ry='26' fill='{petal}' stroke='{stroke}' stroke-width='3'/>"
                f"<ellipse cx='-30' cy='18' rx='18' ry='26' fill='{petal}' stroke='{stroke}' stroke-width='3' transform='rotate(-125)'/>"
                f"<ellipse cx='-30' cy='-18' rx='18' ry='26' fill='{petal}' stroke='{stroke}' stroke-width='3' transform='rotate(-55)'/>"
                f"<circle cx='0' cy='0' r='16' fill='{center}' stroke='#ca8a04' stroke-width='2'/>"
                "</g>"
                f"<rect x='154' y='106' width='12' height='82' rx='6' fill='{stem}'/>"
                f"<ellipse cx='132' cy='145' rx='22' ry='12' fill='{leaf}' transform='rotate(-25 132 145)'/>"
                f"<ellipse cx='188' cy='160' rx='22' ry='12' fill='{leaf}' transform='rotate(25 188 160)'/>"
                "</svg>"
            )
            data = {"title": f"2D flower ({style})", "svg": svg}
            return f"[VISUAL:type=illustration]\n{json.dumps(data, ensure_ascii=False)}"

        if any(k in lower for k in ("atom", "object", "draw", "illustration", "sketch")):
            bg = "#0b1020" if style == "neon" else "#f8fafc"
            orbit = "#60a5fa" if style != "neon" else "#22d3ee"
            nucleus = "#fde68a" if style != "neon" else "#f43f5e"
            svg = (
                "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 320 220'>"
                f"<rect width='320' height='220' fill='{bg}'/>"
                f"<circle cx='160' cy='110' r='20' fill='{nucleus}'/>"
                f"<g fill='none' stroke='{orbit}' stroke-width='2'>"
                "<ellipse cx='160' cy='110' rx='96' ry='34'/>"
                "<ellipse cx='160' cy='110' rx='96' ry='34' transform='rotate(60 160 110)'/>"
                "<ellipse cx='160' cy='110' rx='96' ry='34' transform='rotate(-60 160 110)'/>"
                "</g>"
                "<circle cx='247' cy='110' r='4.5' fill='#34d399'/>"
                "<circle cx='117' cy='53' r='4.5' fill='#f472b6'/>"
                "<circle cx='117' cy='167' r='4.5' fill='#93c5fd'/>"
                "</svg>"
            )
            data = {"title": f"2D illustration ({style})", "svg": svg}
            return f"[VISUAL:type=illustration]\n{json.dumps(data, ensure_ascii=False)}"

        tokens = [t for t in re.split(r"[^a-zA-Z0-9]+", (user_msg or "").strip()) if t]
        topic = " ".join(tokens[:5]) if tokens else "Requested concept"
        data = {
            "description": f"Visual-only explanation: {topic}",
            "steps": [
                "Core concept",
                "How components interact",
                "Result or observation",
            ],
        }
