                f"<circle cx='0' cy='-34' r='30' fill='{petal}' stroke='{stroke}' stroke-width='3.8'/>"
                f"<circle cx='-42' cy='-2' r='30' fill='{petal}' stroke='{stroke}' stroke-width='3.8'/>"
                f"<circle cx='42' cy='-2' r='30' fill='{petal}' stroke='{stroke}' stroke-width='3.8'/>"
