    def _build_alex_voice_boot_script(self, *, auto_start_voice: bool) -> str:
        """Build JS that configures voice APIs and loads alex_voice.js (optionally starts the call)."""
        import secrets as _secrets

        # Voice sync uses chat session; reset hydration keys so chat_history is not stale.
        self._last_hydrated_scope = ""
        self._last_hydrated_session_id = ""

        student_name = self.inferred_name or "Student"
        voice_language = self._effective_voice_language()

        try:
            base_system = self._alex_system_prompt(student_name, response_language=voice_language)
        except Exception:
            base_system = _ALEX_VOICE_SYSTEM

        scope_summary = self._get_scope_summary(self._uid(), self.active_scope or "home")
        memory_block = f"\n\n─── Student Semester Memory ───\n{scope_summary}" if scope_summary else ""

        voice_system = (
            base_system
            + memory_block
            + "\n\n─── VOICE CALL + READING PANE (OVERRIDES LOOSE TEXT RULES ABOVE) ───\n"
            "The student is on a live voice call AND sees a formatted reading pane (same spirit as the main chat).\n"
            "Reply using **clear markdown for the reading pane**: a short ### heading when it helps, **bold** key terms, "
            "and bullet or numbered lists with full sentences so they can scan while they listen.\n"
            "The platform will also derive a plain spoken version automatically — still avoid the abbreviations "
            "e.g. and i.e.; write the words 'for example' or 'that is' so both screen and speech sound natural.\n"
            "Do not use [VISUAL] blocks in voice mode. Keep code fences short only when essential.\n"
            "Teach one clear layer per turn (aim under ~220 words in the reading pane unless they want a crisp definition). "
            "If the topic is huge, cover the core clearly, then invite them to go deeper next.\n"
            "Sound like a human professor: warm, direct, and structured for reading — not a wall of unbroken prose.\n"
            f"{_language_response_instruction(voice_language, voice=True)}"
        )

        raw = list(self.chat_history[-20:]) if len(self.chat_history) > 20 else list(self.chat_history)
        api_history = [
            {"role": m["role"], "content": str(m.get("content", ""))}
            for m in raw
            if m.get("role") in ("user", "assistant") and m.get("content")
        ]

        voice_key = _secrets.token_urlsafe(16)
        _alex_voice_sessions[voice_key] = {
            "system": voice_system,
            "voice_system_base": voice_system,
            "history": api_history,
            "student_name": student_name,
            "uid": self._uid(),
            "session_id": int(self.current_session_id) if self.current_session_id else -1,
            "scope": self.active_scope or "",
            "voice_language": voice_language,
            "pre_loaded_count": len(api_history),
            "_created": time.time(),
        }

        if ALEX_VOICE_COMMERCIAL_GATES:
            is_premium = self.has_premium_access
            is_home = (self.active_scope or "home") == "home"
            voice_plan_tier = self.effective_plan_tier if is_premium else PLAN_FREE
            voice_limit_sec = _plan_voice_limit_seconds(voice_plan_tier)

            if is_home and not is_premium:
                voice_allowed = False
                remaining_sec = 0
                block_reason = "home_blocked"
            else:
                used_sec = _get_voice_seconds_today(self._uid())
                remaining_sec = max(0, voice_limit_sec - used_sec)
                if remaining_sec <= 0:
                    voice_allowed = False
                    block_reason = "limit_reached"
                else:
                    voice_allowed = True
                    block_reason = ""
        else:
            voice_allowed = True
            remaining_sec = -1
            block_reason = ""

        api_base = os.getenv("REFLEX_API_URL", os.getenv("API_URL", "http://localhost:8000")).rstrip("/")
        overlay_flag = "window.__alex_overlay_mode=true;" if auto_start_voice else "window.__alex_overlay_mode=false;"
        onload_extra = "if(window.toggleAlexVoice)window.toggleAlexVoice();" if auto_start_voice else ""
        return (
            overlay_flag
            + f"window.ALEX_API_BASE = {json.dumps(api_base)};"
            f"window.ALEX_VOICE_KEY = {json.dumps(voice_key)};"
            f"window.ALEX_VOICE_SCOPE = {json.dumps(self.active_scope or 'home')};"
            f"window.ALEX_VOICE_ALLOWED = {str(bool(voice_allowed)).lower()};"
            f"window.ALEX_VOICE_REMAINING_SEC = {int(remaining_sec)};"
            f"window.ALEX_VOICE_BLOCK_REASON = {json.dumps(block_reason)};"
            f"window.ALEX_VOICE_SHOW_UPSELL = {str(bool(ALEX_VOICE_COMMERCIAL_GATES)).lower()};"
            f"window.ALEX_AUTH_STORAGE_KEY = {json.dumps(AUTH_TOKEN_LOCAL_STORAGE_KEY)};"
            "(function(){"
            "var old=document.getElementById('_alex_voice_script');"
            "if(old)old.remove();"
            "var s=document.createElement('script');"
            "s.id='_alex_voice_script';"
            "s.src='/alex_voice.js?v='+Date.now();"
            "s.onload=function(){console.log('[AlexVoice] loaded OK');"
            + onload_extra
            + "};"
            "s.onerror=function(){console.error('[AlexVoice] FAILED to load /alex_voice.js');};"
            "document.head.appendChild(s);"
            # 3D avatar overlay — loads once, no-op if already booted. Separate from voice logic
            # so a failure here never breaks the call.
            "window.ALEX_AVATAR_TARGET_ID='alex-orb';"
            "if(window.AlexAvatarMount){window.AlexAvatarMount('alex-orb');}"
            "else if(!document.getElementById('_alex_avatar_script')){"
            "var av=document.createElement('script');"
            "av.id='_alex_avatar_script';"
            "av.src='/alex_avatar.js?v='+Date.now();"
            "av.onload=function(){try{if(window.AlexAvatarMount)window.AlexAvatarMount('alex-orb');}catch(e){}};"
            "av.onerror=function(){console.warn('[AlexAvatar] failed to load /alex_avatar.js');};"
            "document.head.appendChild(av);"
            "}"
            "})();"
        )

