def _marketing_button(label: str, href: str, variant: str = "solid") -> rx.Component:
    base_props = {
        "size": "3",
        "height": "48px",
        "padding": "0 22px",
        "border_radius": "9999px",
        "font_weight": "700",
        "letter_spacing": "0.01em",
        "cursor": "pointer",
        "transition": "all 0.2s ease",
    }
    if variant == "solid":
        button = rx.button(
            label,
            background="linear-gradient(135deg,var(--landing-accent) 0%, var(--landing-accent-2) 100%)",
            color="white",
            border="none",
            box_shadow="0 18px 44px rgba(16,185,129,0.24)",
            _hover={
                "transform": "translateY(-1px)",
                "box_shadow": "0 22px 52px rgba(134,239,172,0.16)",
            },
            _active={"transform": "translateY(0px)"},
            **base_props,
        )
    else:
        button = rx.button(
            label,
            background="rgba(3,8,20,0.36)",
            color="white",
            border="1px solid var(--landing-border-strong)",
            backdrop_filter="blur(14px)",
            box_shadow="0 10px 36px rgba(2,6,23,0.24)",
            _hover={
                "background": "rgba(15,23,42,0.56)",
                "border_color": "rgba(148,163,184,0.38)",
                "transform": "translateY(-1px)",
            },
            _active={"transform": "translateY(0px)"},
            **base_props,
        )
    return rx.link(
        button,
        href=href,
        text_decoration="none",
        display="inline-flex",
    )


def _json_ld_script(data: dict[str, Any] | list[dict[str, Any]]) -> rx.Component:
    return rx.el.script(
        json.dumps(data, ensure_ascii=False, separators=(",", ":")),
        type="application/ld+json",
    )


def _canonical_public_url(path: str = "/") -> str:
    if path == "/":
        return "https://alexstudies.com/"
    return f"https://alexstudies.com/{path.lstrip('/')}"


def _landing_json_ld() -> rx.Component:
    return _json_ld_script(
        {
            "@context": "https://schema.org",
            "@graph": [
                {
                    "@type": "WebSite",
                    "name": "Alex Studies",
                    "alternateName": "Alex AI",
                    "url": "https://alexstudies.com/",
                    "description": "AI-powered study platform for university students with degree study plans and academic guidance.",
                },
                {
                    "@type": "Organization",
                    "name": "Alex Studies",
                    "alternateName": "Alex AI",
                    "url": "https://alexstudies.com/",
                    "description": "AI-powered study platform for university students with degree study plans and academic guidance.",
                    "email": "support.alexstudies@gmail.com",
                },
            ],
        }
    )


