def _legal_section_body(body: str) -> rx.Component:
    rows: list[rx.Component] = []
    for raw_line in (body or "").splitlines():
        line = raw_line.strip()
        if not line:
            continue

        if line.startswith("- "):
            rows.append(
                rx.hstack(
                    rx.text("•", color="rgba(255,255,255,0.4)", margin_top="2px"),
                    rx.text(
                        line[2:].strip(),
                        color="rgba(255,255,255,0.55)",
                        line_height="1.7",
                        font_size="0.95rem",
                        font_family="'Plus Jakarta Sans', sans-serif",
                        flex="1",
                    ),
                    align="start",
                    spacing="3",
                    width="100%",
                )
            )
            continue

        if ":" in line:
            label, value = line.split(":", 1)
            if label.strip() and value.strip():
                rows.append(
                    rx.hstack(
                        rx.text(
                            label.strip() + ":",
                            color="rgba(255,255,255,0.85)",
                            font_weight="600",
                            font_size="0.95rem",
                            font_family="'Plus Jakarta Sans', sans-serif",
                            width="96px",
                            flex_shrink="0",
                        ),
                        rx.text(
                            value.strip(),
                            color="rgba(255,255,255,0.55)",
                            line_height="1.7",
                            font_size="0.95rem",
                            font_family="'Plus Jakarta Sans', sans-serif",
                            flex="1",
                        ),
                        align="start",
                        spacing="3",
                        width="100%",
                    )
                )
                continue

        rows.append(
            rx.text(
                line,
                color="rgba(255,255,255,0.55)",
                line_height="1.7",
                font_size="0.95rem",
                font_family="'Plus Jakarta Sans', sans-serif",
                width="100%",
            )
        )

    return rx.vstack(
        *rows,
        spacing="3",
        align_items="flex-start",
        width="100%",
    )


