def legal_page_shell(title: str, subtitle: str, sections: list[tuple[str, str]]) -> rx.Component:
    return _public_page_frame(
        rx.vstack(
            rx.box(
                rx.vstack(
                    rx.text(
                        "Public Information",
                        color="rgba(255,255,255,0.55)",
                        font_size="0.64rem",
                        font_weight="700",
                        letter_spacing="0.22em",
                        text_transform="uppercase",
                        font_family="'Plus Jakarta Sans', sans-serif",
                    ),
                    rx.heading(
                        title,
                        color="white",
                        font_size="clamp(2.4rem, 6vw, 4.2rem)",
                        line_height="1.05",
                        letter_spacing="-0.04em",
                        font_family="'Plus Jakarta Sans', sans-serif",
                        font_weight="800",
                    ),
                    rx.text(
                        subtitle,
                        color="rgba(255,255,255,0.55)",
                        font_size="1.06rem",
                        line_height="1.65",
                        max_width="760px",
                        font_family="'Plus Jakarta Sans', sans-serif",
                    ),
                    spacing="4",
                    align_items="flex-start",
                    width="100%",
                ),
                padding="clamp(32px, 6vw, 72px) 0",
                width="100%",
            ),
            *[
                rx.box(
                    rx.vstack(
                        rx.text(
                            "Alex AI",
                            color="rgba(255,255,255,0.45)",
                            font_size="0.75rem",
                            font_weight="700",
                            letter_spacing="0.15em",
                            text_transform="uppercase",
                            font_family="'Plus Jakarta Sans', sans-serif",
                        ),
                        rx.heading(
                            section_title,
                            size="6",
                            color="white",
                            font_family="'Plus Jakarta Sans', sans-serif",
                            font_weight="700",
                            letter_spacing="-0.02em",
                        ),
                        _legal_section_body(section_text),
                        spacing="4",
                        align_items="flex-start",
                        width="100%",
                    ),
                    padding="40px 0",
                    width="100%",
                )
                for section_title, section_text in sections
            ],
            spacing="9",
            width="100%",
            align_items="stretch",
            padding_top="24px",
            padding_bottom="120px",
        )
    )


