def landing_page():
    def nav_link(label: str, href: str) -> rx.Component:
        return         rx.link(
            rx.text(
                label,
                color="rgba(255,255,255,0.52)",
                font_size="0.95rem",
                font_weight="500",
                letter_spacing="0",
            ),
            href=href,
            text_decoration="none",
            style={
                "_hover": {
                    "color": "rgba(255,255,255,0.92)",
                },
            },
        )

    def hero_button(
        label: str,
        href: str,
        variant: str = "solid",
        tracking_event: str = "",
        tracking_params: dict[str, Any] | None = None,
    ) -> rx.Component:
        # Single interactive element — the rx.button below. Navigation uses
        # direct browser navigation via window.location.assign(...) rather
        # than rx.redirect, because rx.redirect (a Reflex state event) was
        # observed to silently no-op for these buttons in production.
        # `window.location.assign` is the canonical hard-navigate path and
        # is impossible for Reflex/Radix to swallow.
        is_solid = variant == "solid"
        on_click_chain: list[Any] = []
        if tracking_event:
            # Track first, then navigate — track_ga_event is fire-and-forget
            # JS via rx.call_script, so the GA beacon is queued before the
            # page unloads (modern GA delivers via Beacon API even if the
            # page is mid-navigation).
            on_click_chain.append(track_ga_event(tracking_event, tracking_params))
        on_click_chain.append(
            rx.call_script(f"window.location.assign({json.dumps(href)})")
        )
        on_click_value = (
            on_click_chain if len(on_click_chain) > 1 else on_click_chain[0]
        )
        return rx.button(
            label,
            type="button",
            variant="ghost",
            class_name=f"landing-main-cta landing-main-cta--{variant}",
            on_click=on_click_value,
            custom_attrs={"data-landing-link": "primary" if is_solid else "secondary"},
            style={
                "height": "52px",
                "padding": "0 24px",
                "border_radius": "999px",
                "border": (
                    "1px solid rgba(255,255,255,0.14)"
                    if not is_solid
                    else "1px solid rgba(255,255,255,0.08)"
                ),
                "background": (
                    "linear-gradient(180deg, #f5f5f5 0%, #e8e8ea 100%)"
                    if is_solid
                    else "rgba(255,255,255,0.04)"
                ),
                "color": "#0a0a0b" if is_solid else "rgba(255,255,255,0.88)",
                "font_size": "0.98rem",
                "font_weight": "600",
                "letter_spacing": "0",
                "line_height": "1",
                "white_space": "nowrap",
                "text_align": "center",
                "display": "inline-flex",
                "align_items": "center",
                "justify_content": "center",
                "min_width": "216px",
                "max_width": "100%",
                "width": "fit-content",
                "box_sizing": "border-box",
                "cursor": "pointer",
                "transition": "transform 0.18s ease, background 0.18s ease, border-color 0.18s ease",
                "box_shadow": (
                    "0 12px 40px rgba(0,0,0,0.45), 0 0 0 1px rgba(255,255,255,0.06) inset"
                    if is_solid
                    else "none"
                ),
                "_hover": {
                    "transform": "translateY(-1px)",
                    "background": "#ffffff" if is_solid else "rgba(255,255,255,0.09)",
                },
            },
        )

    def proof_chip(label: str, animate: str = "") -> rx.Component:
        return rx.box(
            rx.text(
                label,
                color="rgba(255,255,255,0.82)",
                font_size="0.84rem",
                font_weight="600",
                letter_spacing="0",
                line_height="1.2",
                text_align="center",
            ),
            padding="10px 14px",
            border="1px solid rgba(255,255,255,0.08)",
            border_radius="999px",
            background="rgba(255,255,255,0.04)",
            backdrop_filter="blur(16px)",
            display="inline-flex",
            align_items="center",
            justify_content="center",
            max_width="100%",
            text_align="center",
            custom_attrs={"data-landing-animate": animate} if animate else {},
        )

    def feature_card(title: str, description: str, image_src: str, eyebrow: str) -> rx.Component:
        return rx.box(
            rx.vstack(
                rx.box(
                    rx.image(
                        src=image_src,
                        alt=f"{title} — Alex AI {eyebrow.lower()} preview",
                        width="100%",
                        height="100%",
                        object_fit="cover",
                        filter="brightness(1.25) contrast(1.06) saturate(1.04)",
                    ),
                    width="100%",
                    height=rx.breakpoints(initial="200px", md="220px"),
                    overflow="hidden",
                    border_radius="18px",
                    border="1px solid rgba(255,255,255,0.08)",
                    background="rgba(255,255,255,0.02)",
                ),
                rx.vstack(
                    rx.text(
                        eyebrow,
                        color="rgba(255,255,255,0.44)",
                        font_size="0.74rem",
                        font_weight="700",
                        letter_spacing="0",
                        text_transform="uppercase",
                    ),
                    rx.text(
                        title,
                        color="rgba(255,255,255,0.94)",
                        font_size="1.15rem",
                        font_weight="650",
                        letter_spacing="0",
                    ),
                    rx.text(
                        description,
                        color="rgba(255,255,255,0.56)",
                        font_size="0.95rem",
                        line_height="1.7",
                    ),
                    spacing="2",
                    align_items="flex-start",
                    width="100%",
                ),
                spacing="4",
                align_items="flex-start",
                width="100%",
            ),
            width=rx.breakpoints(initial="100%", md="calc(50% - 10px)", lg="calc(25% - 15px)"),
            min_width=rx.breakpoints(initial="100%", md="260px"),
            max_width=rx.breakpoints(initial="100%", md="380px", lg="none"),
            padding="18px",
            border="1px solid rgba(255,255,255,0.08)",
            border_radius="24px",
            background="linear-gradient(180deg, rgba(255,255,255,0.05) 0%, rgba(255,255,255,0.02) 100%)",
            box_shadow="0 24px 60px rgba(0,0,0,0.34)",
        )

    def landing_pricing_card(
        title: str,
        price: str,
        period: str,
        description: str,
        features: list[str],
        action_label: str,
        href: str,
        accent: str = "neutral",
        primary: bool = False,
        badge_label: str = "",
        local_price: str = "",
        local_price_id: str = "",
        footer_note: str = "",
        tracking_event: str = "",
        tracking_params: dict[str, Any] | None = None,
    ) -> rx.Component:
        accent_styles = {
            "free": {
                "border": "rgba(255,255,255,0.08)",
                "glow": "rgba(255,255,255,0.04)",
            },
            "pro": {
                "border": "rgba(94,211,132,0.36)",
                "glow": "rgba(74,222,128,0.10)",
            },
            "max": {
                "border": "rgba(255,255,255,0.24)",
                "glow": "rgba(255,255,255,0.07)",
            },
            "ultra": {
                "border": "rgba(231,182,157,0.38)",
                "glow": "rgba(231,182,157,0.11)",
            },
        }
        theme = accent_styles.get(accent, accent_styles["free"])
        button_background = (
            "linear-gradient(180deg, #f7f4ed 0%, #ebe4d7 100%)"
            if primary
            else "rgba(255,255,255,0.045)"
        )
        button_color = "#1c1915" if primary else "rgba(255,255,255,0.88)"
        button_border = "1px solid rgba(255,255,255,0.10)" if primary else f"1px solid {theme['border']}"
        badge = (
            rx.box(
                rx.text(
                    badge_label,
                    color="rgba(10,14,11,0.9)",
                    font_size="0.74rem",
                    font_weight="800",
                    letter_spacing="0",
                ),
                padding="7px 10px",
                border_radius="999px",
                background="linear-gradient(180deg, #bbf7d0 0%, #86efac 100%)",
                border="1px solid rgba(255,255,255,0.22)",
            )
            if badge_label
            else rx.fragment()
        )
        local_price_line = (
            rx.text(
                local_price,
                id=local_price_id,
                color="rgba(255,255,255,0.42)",
                font_size="0.82rem",
                font_weight="600",
                letter_spacing="0",
                custom_attrs={"data-usd-amount": "3"} if local_price_id else {},
            )
            if local_price
            else rx.fragment()
        )
        link_props: dict[str, Any] = {
            "href": href,
            "width": "100%",
            "text_decoration": "none",
            "display": "flex",
            "align_items": "center",
        }
        if tracking_event:
            # GA funnel event: pricing card click, then normal link navigation continues.
            link_props["on_click"] = track_ga_event(tracking_event, tracking_params)

        return rx.box(
            rx.vstack(
                rx.vstack(
                    badge,
                    rx.text(
                        title,
                        color="rgba(255,255,255,0.96)",
                        font_size="1.05rem",
                        font_weight="700",
                        letter_spacing="0",
                    ),
                    rx.hstack(
                        rx.text(
                            price,
                            color="rgba(255,255,255,0.98)",
                            font_size=rx.breakpoints(initial="2.3rem", md="1.92rem", lg="2.16rem"),
                            font_weight="800",
                            letter_spacing="0",
                            line_height="1",
                        ),
                        rx.text(
                            period,
                            color="rgba(255,255,255,0.48)",
                            font_size="0.78rem",
                            font_weight="500",
                            white_space="nowrap",
                        ),
                        spacing="2",
                        align="end",
                    ),
                    local_price_line,
                    rx.text(
                        description,
                        color="rgba(255,255,255,0.58)",
                        font_size=rx.breakpoints(initial="0.95rem", md="0.84rem", lg="0.9rem"),
                        line_height="1.62",
                    ),
                    spacing="3",
                    align_items="flex-start",
                    width="100%",
                ),
                rx.vstack(
                    *[
                        rx.hstack(
                            rx.text("•", color="rgba(231,182,157,0.8)", font_size="0.9rem", line_height="1.45"),
                            rx.text(
                                feature,
                                color="rgba(255,255,255,0.78)",
                                font_size=rx.breakpoints(initial="0.92rem", md="0.78rem", lg="0.84rem"),
                                line_height="1.48",
                            ),
                            spacing="2",
                            align="start",
                            width="100%",
                        )
                        for feature in features
                    ],
                    spacing="2",
                    align_items="flex-start",
                    width="100%",
                ),
                rx.box(flex="1"),
                (
                    rx.hstack(
                        rx.text("✓", color="rgba(134,239,172,0.92)", font_size="0.78rem", font_weight="800"),
                        rx.text(
                            "7-day money-back guarantee",
                            color="rgba(255,255,255,0.72)",
                            font_size="0.78rem",
                            font_weight="650",
                            letter_spacing="-0.01em",
                        ),
                        spacing="1",
                        align="center",
                        justify="center",
                        width="100%",
                        margin_bottom="2px",
                    )
                    if primary
                    else rx.fragment()
                ),
                rx.link(
                    rx.button(
                        action_label,
                        type="button",
                        variant="ghost",
                        class_name=(
                            "landing-plan-cta landing-plan-cta--primary"
                            if primary
                            else "landing-plan-cta landing-plan-cta--secondary"
                        ),
                        width="100%",
                        height=rx.breakpoints(initial="52px", md="48px"),
                        border_radius="999px",
                        background=button_background,
                        color=button_color,
                        border=button_border,
                        font_weight="750",
                        font_size="0.92rem",
                        line_height="1.15",
                        padding="0 18px",
                        white_space="normal",
                        box_shadow=(
                            "0 18px 46px rgba(0,0,0,0.44), 0 1px 0 rgba(255,255,255,0.45) inset"
                            if primary
                            else "none"
                        ),
                        cursor="pointer",
                        display="flex",
                        align_items="center",
                        justify_content="center",
                        text_align="center",
                        box_sizing="border-box",
                        style={
                            "transition": "transform 0.18s ease, background 0.18s ease, border-color 0.18s ease",
                            "_hover": {
                                "transform": "translateY(-1px)",
                                "background": "#fffaf0" if primary else "rgba(255,255,255,0.075)",
                            }
                        },
                    ),
                    **link_props,
                ),
                (
                    rx.text(
                        footer_note,
                        color="rgba(255,255,255,0.54)",
                        font_size="0.84rem",
                        font_weight="650",
                        letter_spacing="0",
                        width="100%",
                        text_align="center",
                        margin_top="4px",
                    )
                    if footer_note
                    else rx.fragment()
                ),
                spacing="4",
                align_items="flex-start",
                width="100%",
                height="100%",
            ),
            width=rx.breakpoints(initial="100%", md="calc(50% - 10px)"),
            min_width=rx.breakpoints(initial="100%", md="0"),
            min_height=rx.breakpoints(initial="auto", md="500px"),
            padding=rx.breakpoints(initial="24px", md="18px", lg="22px"),
            border=f"1px solid {theme['border']}",
            border_radius="24px",
            background=(
                f"radial-gradient(circle at 50% 0%, {theme['glow']} 0%, transparent 42%), "
                "linear-gradient(180deg, rgba(255,255,255,0.065) 0%, rgba(255,255,255,0.025) 100%)"
            ),
            box_shadow="0 24px 70px rgba(0,0,0,0.36)",
        )

