# ──────────────────────────────────────────────────────────────
# Todo Tracker — state + page
# ──────────────────────────────────────────────────────────────

class _CheckCell(rx.Base):
    day: int
    checked: bool


class _TrackerRow(rx.Base):
    name: str
    cells: list[_CheckCell]
    done_count: int


class _TrackerListMeta(rx.Base):
    id: int
    title: str
    days: int
    todo_count: int


class _ProgressItem(rx.Base):
    name: str
    done: int
    missed: int
    remaining: int
    total: int
    pct_label: str        # consistency % within active window
    done_label: str       # "5 days"
    missed_label: str     # "2 days"
    remaining_label: str  # "23 days"
    conic_style: str


class TrackerState(AppState):
    # ── Multi-list management ──
    tracker_lists: list[_TrackerListMeta] = []
    current_tracker_id: int = -1
    show_lists_panel: bool = False

    # ── Create new list modal ──
    show_create_modal: bool = False
    create_title: str = ""
    create_days_preset: str = "100"
    create_custom_days: str = ""

    # ── Current tracker content ──
    tracker_title: str = ""
    tracker_days: int = 100
    tracker_todos: list[str] = []
    tracker_checks: dict[str, list[bool]] = {}
    tracker_editing_title: bool = False
    tracker_title_draft: str = ""
    tracker_adding: bool = False
    tracker_adding_draft: str = ""

    # ── Row context menu / rename / drag ──
    ctx_row: str = ""
    renaming_row: str = ""
    rename_draft: str = ""
    drag_src: str = ""

    # ── Progress circle tooltip ──
    tooltip_circle: str = ""

    def toggle_circle_tooltip(self, name: str):
        self.tooltip_circle = "" if self.tooltip_circle == name else name

    # ── Lists panel – increase days ──
    increase_days_id: int = -1
    increase_days_draft: str = ""

    @rx.var
    def tracker_rows(self) -> list[_TrackerRow]:
        rows = []
        for name in self.tracker_todos:
            checks = list(self.tracker_checks.get(name, [False] * self.tracker_days))
            if len(checks) < self.tracker_days:
                checks.extend([False] * (self.tracker_days - len(checks)))
            elif len(checks) > self.tracker_days:
                checks = checks[:self.tracker_days]
            rows.append(_TrackerRow(
                name=name,
                cells=[_CheckCell(day=i, checked=c) for i, c in enumerate(checks)],
                done_count=sum(1 for c in checks if c),
            ))
        return rows

    @rx.var
    def day_columns(self) -> list[int]:
        return list(range(1, self.tracker_days + 1))

    @rx.var
    def tracker_progress(self) -> list[_ProgressItem]:
        result = []
        for name in self.tracker_todos:
            raw = self.tracker_checks.get(name, [])
            checks = list(raw) + [False] * max(0, self.tracker_days - len(raw))
            checks = checks[:self.tracker_days]
            total = self.tracker_days

            # Find the last checked day index
            last_idx = -1
            for i in range(len(checks) - 1, -1, -1):
                if checks[i]:
                    last_idx = i
                    break

            if last_idx == -1:
                # No activity yet — all white
                done = 0
                missed = 0
                active = 0
            else:
                active = last_idx + 1          # days up to and including last check
                done = sum(1 for c in checks[:active] if c)
                missed = active - done

            remaining = total - active         # days after the last check

            # Arc sizes as % of full circle
            g = round(done     / total * 100, 3) if total > 0 else 0.0
            r = round(missed   / total * 100, 3) if total > 0 else 0.0
            gr = round(g + r, 3)

            # Build conic-gradient: green → red → white/gray
            if active == 0:
                conic = "conic-gradient(rgba(255,255,255,0.13) 100%)"
            elif remaining == 0:
                conic = f"conic-gradient(#22c55e {g}%, #ef4444 {g}% 100%)"
            elif missed == 0:
                conic = f"conic-gradient(#22c55e {g}%, rgba(255,255,255,0.13) {g}% 100%)"
            else:
                conic = (
                    f"conic-gradient(#22c55e {g}%, "
                    f"#ef4444 {g}% {gr}%, "
                    f"rgba(255,255,255,0.13) {gr}% 100%)"
                )

            # Centre label: consistency within active period
            consistency = int(round(done / active * 100)) if active > 0 else 0
            day = lambda n: f"{n} day" + ("s" if n != 1 else "")
            result.append(_ProgressItem(
                name=name,
                done=done,
                missed=missed,
                remaining=remaining,
                total=total,
                pct_label=f"{consistency}%",
                done_label=day(done),
                missed_label=day(missed),
                remaining_label=day(remaining),
                conic_style=conic,
            ))
        return result

    @rx.var
    def create_days_value(self) -> int:
        m = {"1": 1, "7": 7, "30": 30, "100": 100}
        if self.create_days_preset in m:
            return m[self.create_days_preset]
        try:
            return max(0, min(100, int(self.create_custom_days or "0")))
        except (ValueError, TypeError):
            return 0

    @rx.var
    def can_create_tracker(self) -> bool:
        return self.create_days_value > 0

    # ── Internal helpers ──
    def _load_lists(self, session):
        uid = self._cached_uid
        trackers = session.exec(
            select(TodoTracker).where(TodoTracker.user_id == uid)
        ).all()
        self.tracker_lists = [
            _TrackerListMeta(
                id=t.id,
                title=t.title,
                days=t.days,
                todo_count=len(json.loads(t.todos_json)),
            )
            for t in trackers
        ]

    def _load_tracker_data(self, tracker):
        self.current_tracker_id = tracker.id
        self.tracker_title = tracker.title
        self.tracker_days = tracker.days
        todos = json.loads(tracker.todos_json)
        raw = json.loads(tracker.checks_json)
        self.tracker_todos = todos
        checks = {}
        for name in todos:
            row = list(raw.get(name, []))
            if len(row) < self.tracker_days:
                row.extend([False] * (self.tracker_days - len(row)))
            checks[name] = row[:self.tracker_days]
        self.tracker_checks = checks

    # ── Page load ──
    def on_load_tracker(self):
        real_uid = self._uid()
        uid = real_uid if real_uid >= 0 else self._active_data_uid()
        self._cached_uid = uid
        if real_uid < 0:
            self._load_guest_memory(uid)
        with rx.session() as session:
            self._load_lists(session)
            tracker = None
            if self.current_tracker_id >= 0:
                tracker = session.get(TodoTracker, self.current_tracker_id)
                if tracker and tracker.user_id != uid:
                    tracker = None
            if not tracker and self.tracker_lists:
                tracker = session.get(TodoTracker, self.tracker_lists[0].id)
            if tracker:
                self._load_tracker_data(tracker)

    def _save(self):
        uid = self._cached_uid
        if uid < 0 or self.current_tracker_id < 0:
            return
        with rx.session() as session:
            tracker = session.get(TodoTracker, self.current_tracker_id)
            if not tracker:
                return
            tracker.title = self.tracker_title
            tracker.days = self.tracker_days
            tracker.todos_json = json.dumps(self.tracker_todos)
            tracker.checks_json = json.dumps({k: list(v) for k, v in self.tracker_checks.items()})
            session.commit()
            self._load_lists(session)

    # ── Multi-list management ──
    def toggle_lists_panel(self):
        self.show_lists_panel = not self.show_lists_panel
        self.increase_days_id = -1
        self.increase_days_draft = ""

    def switch_tracker(self, tracker_id: int):
        with rx.session() as session:
            tracker = session.get(TodoTracker, tracker_id)
            if tracker and tracker.user_id == self._cached_uid:
                self._load_tracker_data(tracker)
        self.show_lists_panel = False

    def delete_tracker(self, tracker_id: int):
        uid = self._cached_uid
        with rx.session() as session:
            tracker = session.get(TodoTracker, tracker_id)
            if tracker and tracker.user_id == uid:
                session.delete(tracker)
                session.commit()
            self._load_lists(session)
        if tracker_id == self.current_tracker_id:
            if self.tracker_lists:
                with rx.session() as session:
                    t = session.get(TodoTracker, self.tracker_lists[0].id)
                    if t:
                        self._load_tracker_data(t)
            else:
                self.current_tracker_id = -1
                self.tracker_title = ""
                self.tracker_todos = []
                self.tracker_checks = {}

    def set_increase_days_id(self, tid: int):
        self.increase_days_id = tid
        self.increase_days_draft = ""

    def set_increase_days_draft(self, val: str):
        # Keep only digits so "add days" stays strictly numeric.
        self.increase_days_draft = "".join(ch for ch in str(val or "") if ch.isdigit())

    def confirm_increase_days(self, tracker_id: int):
        try:
            extra = max(1, int(self.increase_days_draft or "0"))
        except (ValueError, TypeError):
            self.increase_days_id = -1
            return
        uid = self._cached_uid
        with rx.session() as session:
            tracker = session.get(TodoTracker, tracker_id)
            if tracker and tracker.user_id == uid:
                new_days = tracker.days + extra
                checks = json.loads(tracker.checks_json)
                for name in json.loads(tracker.todos_json):
                    row = list(checks.get(name, []))
                    row.extend([False] * (new_days - len(row)))
                    checks[name] = row
                tracker.days = new_days
                tracker.checks_json = json.dumps(checks)
                session.commit()
                if tracker_id == self.current_tracker_id:
                    self.tracker_days = new_days
                    new_tc = {}
                    for name in self.tracker_todos:
                        row = list(self.tracker_checks.get(name, []))
                        row.extend([False] * (new_days - len(row)))
                        new_tc[name] = row
                    self.tracker_checks = new_tc
            self._load_lists(session)
        self.increase_days_id = -1
        self.increase_days_draft = ""

    # ── Create new tracker ──
    def open_create_modal(self):
        self.show_create_modal = True
        self.create_title = ""
        self.create_days_preset = "100"
        self.create_custom_days = ""

    def close_create_modal(self):
        self.show_create_modal = False

    def set_create_title(self, val: str):
        self.create_title = val

    def set_create_days_preset(self, val: str):
        self.create_days_preset = val

    def set_create_custom_days(self, val: str):
        # Keep only digits and hard-cap visible value at 100.
        digits = "".join(ch for ch in str(val or "") if ch.isdigit())[:3]
        if not digits:
            next_value = ""
        else:
            next_value = str(min(100, int(digits)))
        if next_value != self.create_custom_days:
            self.create_custom_days = next_value

    def confirm_create_tracker(self):
        title = self.create_title.strip() or "My Tracker"
        days = self.create_days_value
        if days <= 0:
            return
        uid = self._cached_uid
        if uid < 0:
            return
        with rx.session() as session:
            new_t = TodoTracker(
                user_id=uid,
                title=title,
                days=days,
                todos_json="[]",
                checks_json="{}",
            )
            session.add(new_t)
            session.commit()
            session.refresh(new_t)
            self._load_lists(session)
            self._load_tracker_data(new_t)
        self.show_create_modal = False

    def handle_create_title_key(self, key: str):
        if key == "Enter":
            return TrackerState.confirm_create_tracker

    # ── Inline add-row flow (Notion-style "+ New") ──
    def start_add_row(self):
        self.tracker_adding = True
        self.tracker_adding_draft = ""

    def set_adding_draft(self, val: str):
        self.tracker_adding_draft = val

    def commit_add_row(self):
        name = self.tracker_adding_draft.strip()
        if name and name not in self.tracker_todos:
            self.tracker_todos = self.tracker_todos + [name]
            checks = dict(self.tracker_checks)
            checks[name] = [False] * self.tracker_days
            self.tracker_checks = checks
            self._save()
        self.tracker_adding_draft = ""
        self.tracker_adding = False

    def cancel_add_row(self):
        self.tracker_adding_draft = ""
        self.tracker_adding = False

    def handle_add_row_key(self, key: str):
        if key == "Enter":
            return TrackerState.commit_add_row
        if key == "Escape":
            return TrackerState.cancel_add_row

    # ── Row context menu ──
    def show_ctx(self, name: str):
        self.ctx_row = name
        self.renaming_row = ""

    def hide_ctx(self):
        self.ctx_row = ""

    def toggle_ctx(self, name: str):
        self.ctx_row = "" if self.ctx_row == name else name
        self.renaming_row = ""

    def start_rename(self, name: str):
        self.renaming_row = name
        self.rename_draft = name
        self.ctx_row = ""

    def set_rename_draft(self, val: str):
        self.rename_draft = val

    def commit_rename(self, old_name: str):
        new_name = self.rename_draft.strip()
        self.renaming_row = ""
        if not new_name or new_name == old_name or new_name in self.tracker_todos:
            return
        todos = list(self.tracker_todos)
        idx = todos.index(old_name) if old_name in todos else -1
        if idx < 0:
            return
        todos[idx] = new_name
        self.tracker_todos = todos
        self.tracker_checks = {
            (new_name if k == old_name else k): v
            for k, v in self.tracker_checks.items()
        }
        self._save()

    def handle_rename_key(self, old_name: str, key: str):
        if key == "Enter":
            return TrackerState.commit_rename(old_name)
        if key == "Escape":
            self.renaming_row = ""

    def remove_todo(self, name: str):
        self.ctx_row = ""
        self.tracker_todos = [t for t in self.tracker_todos if t != name]
        self.tracker_checks = {k: v for k, v in self.tracker_checks.items() if k != name}
        self._save()

    # ── Reorder (up / down buttons) ──
    def move_up(self, name: str):
        todos = list(self.tracker_todos)
        idx = todos.index(name) if name in todos else -1
        if idx > 0:
            todos[idx], todos[idx - 1] = todos[idx - 1], todos[idx]
            self.tracker_todos = todos
            self._save()

    def move_down(self, name: str):
        todos = list(self.tracker_todos)
        idx = todos.index(name) if name in todos else -1
        if idx >= 0 and idx < len(todos) - 1:
            todos[idx], todos[idx + 1] = todos[idx + 1], todos[idx]
            self.tracker_todos = todos
            self._save()

    # ── Drag-to-reorder (via SortableJS signal) ──
    def apply_drag_order(self, csv: str):
        names = [n for n in csv.split(",") if n]
        existing = set(self.tracker_todos)
        ordered = [n for n in names if n in existing]
        rest = [n for n in self.tracker_todos if n not in set(ordered)]
        self.tracker_todos = ordered + rest
        self._save()

    def toggle_check(self, todo: str, day: int):
        checks = dict(self.tracker_checks)
        if todo in checks:
            row = list(checks[todo])
            if day < len(row):
                row[day] = not row[day]
                checks[todo] = row
                self.tracker_checks = checks
        self._save()

    # ── Title editing ──
    def start_edit_title(self):
        self.tracker_title_draft = self.tracker_title
        self.tracker_editing_title = True

    def set_title_draft(self, val: str):
        self.tracker_title_draft = val

    def commit_title(self):
        title = self.tracker_title_draft.strip()
        if title:
            self.tracker_title = title
        self.tracker_editing_title = False
        self._save()

    def handle_title_key(self, key: str):
        if key == "Enter":
            return TrackerState.commit_title


