# ============================================================
# Rate limiter — in-memory, per-user fixed window
# Works fine for a single Railway instance. Upgrade to Redis
# if you ever run multiple instances.
# ============================================================

import threading as _threading
from collections import defaultdict as _defaultdict

class _RateLimiter:
    """Fixed-window in-memory rate limiter keyed by arbitrary strings."""

    def __init__(self):
        self._counts: dict[str, list[float]] = _defaultdict(list)
        self._lock = _threading.Lock()

    def is_allowed(self, key: str, max_calls: int, window_seconds: int) -> bool:
        """Return True and record the call if under the limit, else False."""
        now = time.time()
        with self._lock:
            bucket = self._counts[key]
            # Drop timestamps outside the current window
            self._counts[key] = bucket = [t for t in bucket if now - t < window_seconds]
            if len(bucket) < max_calls:
                bucket.append(now)
                return True
            return False

    def seconds_until_reset(self, key: str, window_seconds: int) -> int:
        """How many seconds until the oldest entry expires."""
        now = time.time()
        with self._lock:
            bucket = self._counts.get(key, [])
            if not bucket:
                return 0
            oldest = min(bucket)
            return max(0, int(window_seconds - (now - oldest)) + 1)


_rl = _RateLimiter()


# ============================================================
# /learn — YouTube-powered learning hub (embed + AI chat + quiz + notes)
# ============================================================


# Reflex needs typed structures for `foreach` to know how to iterate.
# Plain `list[dict]` is rejected as "untyped" — use TypedDict instead.

class LearnChatMessage(TypedDict):
    role: str        # "user" | "assistant"
    content: str
    ts: int


class LearnQuizQuestion(TypedDict):
    q: str
    choices: list[str]
    answer: int      # 0..3 — index of correct choice
    explain: str
    picked: int      # -1 if not picked yet, else 0..3


class LearnState(AppState):
    """State for the /learn page — paste a YouTube URL, get an AI-powered study session."""

    # ── Form ──────────────────────────────────────────────────
    url_input: str = ""
    url_error: str = ""

    # ── Loaded video ──────────────────────────────────────────
    video_id: str = ""
    video_url: str = ""        # canonical embed URL
    video_title: str = ""

    # ── Active session row id (for the LearnVideoSession table) ──
    session_id: int = 0

    # ── Transcript ────────────────────────────────────────────
    transcript: str = ""
    transcript_loading: bool = False
    transcript_error: str = ""
    transcript_blocked: bool = False        # True when YouTube blocks server IP
    transcript_paste_open: bool = False     # Whether the manual-paste UI is visible
    transcript_paste_draft: str = ""        # The user's pasted transcript before save

    # ── Summary ───────────────────────────────────────────────
    summary: str = ""
    summary_loading: bool = False

    # ── Chat ──────────────────────────────────────────────────
    chat_messages: list[LearnChatMessage] = []
    chat_input: str = ""
    chat_busy: bool = False

    # ── Quiz ──────────────────────────────────────────────────
    quiz_questions: list[LearnQuizQuestion] = []
    quiz_loading: bool = False
    quiz_revealed: bool = False

    # ── Notes (AI suggestions + user-editable) ───────────────
    note_draft: str = ""
    notes_saved: bool = False        # Flash flag after saving
    note_save_status: str = ""       # "", "saved", "already"
    last_saved_note_text: str = ""
    note_save_feedback_id: int = 0

    # ── Active right-panel tab: chat | summary | quiz | notes ──
    active_tab: str = "chat"

    # ── Rate-limit feedback ───────────────────────────────────
    rate_limit_msg: str = ""      # Non-empty → show banner

    @rx.var
    def has_video(self) -> bool:
        return bool(self.video_id)

    @rx.var
    def mobile_panel_index(self) -> int:
        """0=chat 1=summary 2=quiz 3=notes — drives the swipe carousel transform."""
        return {"chat": 0, "summary": 1, "quiz": 2, "notes": 3}.get(self.active_tab, 0)

    @rx.var
    def has_transcript(self) -> bool:
        return bool(self.transcript) and not self.transcript_error

    @rx.var
    def video_watch_url(self) -> str:
        if not self.video_id:
            return ""
        return f"https://www.youtube.com/watch?v={self.video_id}"

    @rx.var
    def chat_count(self) -> int:
        return len(self.chat_messages)

    @rx.var
    def can_send_chat(self) -> bool:
        return bool((self.chat_input or "").strip()) and not self.chat_busy and bool(self.video_id)

    @rx.var
    def quiz_score(self) -> str:
        if not self.quiz_questions:
            return ""
        correct = sum(
            1 for q in self.quiz_questions
            if q.get("picked", -1) == q.get("answer", -2)
        )
        return f"{correct}/{len(self.quiz_questions)}"

    # ── Setters ──────────────────────────────────────────────
    def set_url_input(self, v: str): self.url_input = v
    def set_chat_input(self, v: str): self.chat_input = v
    def set_note_draft(self, v: str):
        self.note_draft = v
        if (v or "").strip() != (self.last_saved_note_text or "").strip():
            self.notes_saved = False
            self.note_save_status = ""

    def set_active_tab(self, v: str): self.active_tab = v

    def set_rate_limit_msg(self, v: str):
        self.rate_limit_msg = v

    def handle_chat_enter(self, key: str):
        if key == "Enter" and self.can_send_chat:
            return LearnState.send_chat

    @rx.event
    def on_load_learn(self):
        real_uid = self._uid()
        uid = real_uid if real_uid >= 0 else self._active_data_uid()
        self._cached_uid = uid
        if real_uid >= 0:
            self._load_profile(real_uid)
        else:
            self._load_guest_memory(uid)
        if not self.is_started:
            return rx.redirect(SELECTION_ROUTE)
        if _degree_is_custom(self.degree):
            self.active_scope = "home"
            self.view_mode = "home"
        elif not (self.active_scope or "").strip():
            if self.selected_year and self.selected_semester:
                self.active_scope = self._scope_key(self.selected_year, self.selected_semester)
                self.view_mode = "semester"
            else:
                self.active_scope = "home"
                self.view_mode = "home"
        if real_uid >= 0:
            try:
                self._load_home_sessions(uid)
            except Exception as e:
                print(f"[LEARN] home session load error: {e}")

    def reset_session(self):
        """Clear current session — back to URL input."""
        self.video_id = ""
        self.video_url = ""
        self.video_title = ""
        self.session_id = 0
        self.transcript = ""
        self.transcript_error = ""
        self.transcript_blocked = False
        self.transcript_paste_open = False
        self.transcript_paste_draft = ""
        self.summary = ""
        self.chat_messages = []
        self.chat_input = ""
        self.quiz_questions = []
        self.quiz_revealed = False
        self.note_draft = ""
        self.notes_saved = False
        self.note_save_status = ""
        self.last_saved_note_text = ""
        self.note_save_feedback_id += 1
        self.url_error = ""
        self.active_tab = "chat"

    # ── Manual transcript paste fallback ─────────────────────
    def set_transcript_paste_draft(self, v: str):
        self.transcript_paste_draft = v

    def open_transcript_paste(self):
        self.transcript_paste_open = True

    def close_transcript_paste(self):
        self.transcript_paste_open = False
        self.transcript_paste_draft = ""

    def submit_transcript_paste(self):
        text = (self.transcript_paste_draft or "").strip()
        if len(text) < 30:
            return  # too short to be useful
        self.transcript = text
        self.transcript_error = ""
        self.transcript_blocked = False
        self.transcript_paste_open = False
        self.transcript_paste_draft = ""
        self._persist_session_transcript()

    def _persist_session_transcript(self):
        sid = self.session_id
        if not sid:
            return
        try:
            with rx.session() as session:
                row = session.get(LearnVideoSession, sid)
                if row:
                    row.transcript_cached = self.transcript or ""
                    session.add(row)
                    session.commit()
        except Exception as e:
            logger.error(f"transcript cache save error (manual): {e}")

    # ── Load a video (parse URL → fetch/load session row) ────
    @rx.event(background=True)
    async def load_video(self):
        async with self:
            url = (self.url_input or "").strip()
            if not url:
                self.url_error = "Paste a YouTube link first."
                return
            vid = youtube_utils.extract_video_id(url)
            if not vid:
                self.url_error = "That doesn't look like a YouTube link."
                return
            self.url_error = ""
            self.video_id = vid
            self.video_url = youtube_utils.embed_url(vid)
            self.video_title = ""
            self.transcript = ""
            self.summary = ""
            self.chat_messages = []
            self.quiz_questions = []
            self.quiz_revealed = False
            self.note_draft = ""
            self.notes_saved = False
            self.note_save_status = ""
            self.last_saved_note_text = ""
            self.note_save_feedback_id += 1
            self.active_tab = "chat"
            uid = self._active_data_uid()

        # GA funnel event: a video learning session started; YouTube URL/video ID is not sent.
        yield track_ga_event("video_learning_started", {})

        # Load or create the session row
        try:
            with rx.session() as session:
                row = session.exec(
                    select(LearnVideoSession)
                    .where(LearnVideoSession.user_id == uid)
                    .where(LearnVideoSession.video_id == vid)
                    .limit(1)
                ).first()
                if row is None:
                    row = LearnVideoSession(
                        user_id=uid,
                        video_id=vid,
                        title="",
                        transcript_cached="",
                        summary_cached="",
                        chat_history_json="[]",
                        quiz_json="",
                    )
                    session.add(row)
                    session.commit()
                    session.refresh(row)
                # Load cached state
                async with self:
                    self.session_id = row.id or 0
                    self.video_title = row.title or ""
                    self.transcript = row.transcript_cached or ""
                    self.summary = row.summary_cached or ""
                    try:
                        self.chat_messages = json.loads(row.chat_history_json or "[]")
                    except Exception:
                        self.chat_messages = []
                    try:
                        if row.quiz_json:
                            qd = json.loads(row.quiz_json)
                            if isinstance(qd, list):
                                self.quiz_questions = qd
                    except Exception:
                        self.quiz_questions = []
        except Exception as e:
            logger.error(f"load_video session error: {e}")

        # If no transcript cached, fetch it now
        async with self:
            need_transcript = not self.transcript
            current_vid = self.video_id
            current_sid = self.session_id

        if need_transcript and current_vid:
            async with self:
                self.transcript_loading = True
                self.transcript_error = ""
                self.transcript_blocked = False
            try:
                # Run the sync transcript fetch in a thread
                fetched, reason = await asyncio.to_thread(
                    youtube_utils.fetch_transcript, current_vid
                )
            except Exception as e:
                fetched, reason = None, "unknown"
                logger.warning(f"transcript fetch threw: {e}")
            async with self:
                self.transcript_loading = False
                if fetched:
                    self.transcript = fetched
                else:
                    if reason == "youtube_blocked":
                        self.transcript_blocked = True
                        self.transcript_error = (
                            "YouTube is blocking transcript fetches from our server "
                            "(common on cloud hosts). Paste the transcript below to enable AI features."
                        )
                    elif reason == "no_transcript":
                        self.transcript_error = (
                            "This video doesn't have captions. Paste a transcript "
                            "yourself below, or pick a video with captions enabled."
                        )
                    elif reason == "video_unavailable":
                        self.transcript_error = "This video is unavailable or private."
                    else:
                        self.transcript_error = (
                            "Couldn't load the transcript. Paste it below to "
                            "enable chat, summary, and quiz."
                        )

            # Save transcript to session row
            if fetched and current_sid:
                try:
                    with rx.session() as session:
                        row = session.get(LearnVideoSession, current_sid)
                        if row:
                            row.transcript_cached = fetched
                            session.add(row)
                            session.commit()
                except Exception as e:
                    logger.error(f"transcript cache save error: {e}")

    # ── Persist state to DB row ──────────────────────────────
    def _persist_session(self, *, chat: bool = False, summary: bool = False, quiz: bool = False):
        """Best-effort save of the in-memory state to the session row."""
        sid = self.session_id
        if not sid:
            return
        try:
            with rx.session() as session:
                row = session.get(LearnVideoSession, sid)
                if row is None:
                    return
                if chat:
                    row.chat_history_json = json.dumps(self.chat_messages or [])
                if summary:
                    row.summary_cached = self.summary or ""
                if quiz:
                    row.quiz_json = json.dumps(self.quiz_questions or [])
                session.add(row)
                session.commit()
        except Exception as e:
            logger.error(f"learn session persist error: {e}")

    # ── AI: send a chat message ──────────────────────────────
    @rx.event(background=True)
    async def send_chat(self):
        async with self:
            user_msg = (self.chat_input or "").strip()
            if not user_msg or self.chat_busy or not self.video_id:
                return
            uid = self._active_data_uid()
            # 20 messages per minute per user
            if not _rl.is_allowed(f"chat:{uid}", 20, 60):
                wait = _rl.seconds_until_reset(f"chat:{uid}", 60)
                self.rate_limit_msg = f"Slow down — you've sent a lot of messages. Try again in {wait}s."
                return
            self.rate_limit_msg = ""
            self.chat_busy = True
            self.chat_input = ""
            self.chat_messages = self.chat_messages + [
                {"role": "user", "content": user_msg, "ts": int(time.time())}
            ]
            transcript = self.transcript
            history = list(self.chat_messages)

        # GA funnel event: user sent a message in the Learn video chat; text is never sent.
        yield track_ga_event("chat_message_sent", {"scope": "learn_video"})

        # Build LLM messages with the transcript as system context
        if transcript:
            transcript_section = (
                "Use the transcript below to ground your answers — quote specifics when relevant. "
                "If the answer isn't in the transcript, say so honestly and offer a general explanation.\n\n"
                f"TRANSCRIPT:\n{youtube_utils.truncate_for_llm(transcript, 10000)}\n"
            )
        else:
            transcript_section = (
                "No transcript is available for this video. Answer based on your general knowledge, "
                "but let the student know you don't have the specific video content to reference.\n"
            )
        system = (
            "You are an expert tutor helping a student learn from a YouTube video. "
            "Answer their questions clearly, accurately, and concisely (2-4 short paragraphs).\n\n"
            + transcript_section
        )
        messages = [{"role": "system", "content": system}]
        for m in history[-10:]:
            messages.append({"role": m["role"], "content": m["content"]})

        try:
            resp = await asyncio.to_thread(
                _openrouter_complete, OPENROUTER_TEACHER_MODEL, messages, 1024, 0.5
            )
            reply = (resp.text or "").strip() or "I couldn't think of an answer just now."
        except Exception as e:
            reply = f"Couldn't reach the AI: {e}"

        async with self:
            self.chat_messages = self.chat_messages + [
                {"role": "assistant", "content": reply, "ts": int(time.time())}
            ]
            self.chat_busy = False
            self._persist_session(chat=True)

    # ── AI: generate NotebookLM-style summary ────────────────
    @rx.event(background=True)
    async def generate_summary(self):
        async with self:
            if self.summary_loading or not self.video_id:
                return
            if not self.has_premium_access:
                self.active_tab = "summary"
                return
            if not self.transcript:
                self.summary = "No transcript available — can't summarize this video."
                return
            uid = self._active_data_uid()
            # 5 summaries per hour per user
            if not _rl.is_allowed(f"summary:{uid}", 5, 3600):
                wait = _rl.seconds_until_reset(f"summary:{uid}", 3600)
                self.rate_limit_msg = f"Summary limit reached. Try again in {wait // 60}m."
                return
            self.rate_limit_msg = ""
            self.summary_loading = True
            transcript = self.transcript

        system = (
            "You are creating a comprehensive study guide for a YouTube video, "
            "in the style of Google's NotebookLM. Output well-formatted Markdown with:\n\n"
            "1. **TL;DR** — one or two sentences capturing the core point.\n"
            "2. **Key concepts** — 4-7 bulleted concepts, each with a short explanation.\n"
            "3. **Detailed walkthrough** — 3-5 paragraphs explaining the content in order.\n"
            "4. **Why it matters** — 2-3 sentences on real-world relevance or applications.\n"
            "5. **Things to remember** — 3-5 punchy takeaways.\n\n"
            "Be accurate, clear, and aim for the level of a strong textbook."
        )
        user = f"Generate the study guide for this video transcript:\n\n{youtube_utils.truncate_for_llm(transcript, 10000)}"
        messages = [{"role": "system", "content": system}, {"role": "user", "content": user}]

        try:
            resp = await asyncio.to_thread(_openrouter_complete, OPENROUTER_TEACHER_MODEL, messages, 1800, 0.4)
            text = (resp.text or "").strip() or "Couldn't generate a summary right now."
        except Exception as e:
            text = f"Couldn't reach the AI: {e}"

        async with self:
            self.summary = text
            self.summary_loading = False
            self._persist_session(summary=True)

    # ── AI: generate a 5-question multiple-choice quiz ──────
    @rx.event(background=True)
    async def generate_quiz(self):
        async with self:
            if self.quiz_loading or not self.video_id:
                return
            if not self.has_premium_access:
                self.active_tab = "quiz"
                return
            if not self.transcript:
                self.quiz_questions = []
                return
            uid = self._active_data_uid()
            # 10 quiz generations per hour per user
            if not _rl.is_allowed(f"quiz:{uid}", 10, 3600):
                wait = _rl.seconds_until_reset(f"quiz:{uid}", 3600)
                self.rate_limit_msg = f"Quiz limit reached. Try again in {wait // 60}m."
                return
            self.rate_limit_msg = ""
            self.quiz_loading = True
            self.quiz_revealed = False
            transcript = self.transcript

        system = (
            "You are creating a 5-question multiple-choice quiz to test understanding "
            "of a YouTube video. Output ONLY valid JSON in this exact shape:\n\n"
            "{\n"
            "  \"questions\": [\n"
            "    {\"q\": \"question text?\", \"choices\": [\"A\", \"B\", \"C\", \"D\"], \"answer\": 0, \"explain\": \"why A is right\"},\n"
            "    ...\n"
            "  ]\n"
            "}\n\n"
            "Rules:\n"
            "- Exactly 5 questions.\n"
            "- 4 choices per question.\n"
            "- 'answer' is the 0-based index of the correct choice.\n"
            "- 'explain' is one short sentence.\n"
            "- Test conceptual understanding, not trivia.\n"
            "- Output ONLY the JSON, no surrounding text."
        )
        user = f"Generate the quiz from this transcript:\n\n{youtube_utils.truncate_for_llm(transcript, 9000)}"
        messages = [{"role": "system", "content": system}, {"role": "user", "content": user}]

        questions: list[dict] = []
        try:
            resp = await asyncio.to_thread(_openrouter_complete, OPENROUTER_TEACHER_MODEL, messages, 1500, 0.3)
            raw = (resp.text or "").strip()
            # Extract JSON object even if wrapped in fences/commentary
            m = re.search(r"\{[\s\S]*\}", raw)
            if m:
                data = json.loads(m.group(0))
                qs = data.get("questions") if isinstance(data, dict) else None
                if isinstance(qs, list):
                    for q in qs[:5]:
                        if not isinstance(q, dict):
                            continue
                        text_q = str(q.get("q", "")).strip()
                        choices = q.get("choices") or []
                        if not isinstance(choices, list) or len(choices) != 4:
                            continue
                        ans = int(q.get("answer", 0))
                        if ans < 0 or ans > 3:
                            ans = 0
                        questions.append({
                            "q": text_q,
                            "choices": [str(c) for c in choices],
                            "answer": ans,
                            "explain": str(q.get("explain", "")).strip(),
                            "picked": -1,
                        })
        except Exception as e:
            logger.warning(f"quiz parse error: {e}")

        async with self:
            self.quiz_questions = questions
            self.quiz_loading = False
            self._persist_session(quiz=True)

    def quiz_pick(self, q_index: int, choice_index: int):
        """User picks an answer for question q_index."""
        if q_index < 0 or q_index >= len(self.quiz_questions):
            return
        new_qs = list(self.quiz_questions)
        q = dict(new_qs[q_index])
        q["picked"] = int(choice_index)
        new_qs[q_index] = q
        self.quiz_questions = new_qs

    def quiz_reveal(self):
        self.quiz_revealed = True
        self._persist_session(quiz=True)

    def quiz_reset(self):
        if not self.quiz_questions:
            return
        new_qs = []
        for q in self.quiz_questions:
            qq = dict(q)
            qq["picked"] = -1
            new_qs.append(qq)
        self.quiz_questions = new_qs
        self.quiz_revealed = False
        self._persist_session(quiz=True)

    # ── AI: copy last assistant reply into the note draft ──
    def copy_last_reply_to_note(self):
        for m in reversed(self.chat_messages):
            if m.get("role") == "assistant":
                addition = (m.get("content") or "").strip()
                if not addition:
                    return
                if self.note_draft.strip():
                    self.note_draft = self.note_draft.rstrip() + "\n\n" + addition
                else:
                    self.note_draft = addition
                self.notes_saved = False
                self.note_save_status = ""
                self.active_tab = "notes"
                return

    def copy_summary_to_note(self):
        if not self.summary.strip():
            return
        if self.note_draft.strip():
            self.note_draft = self.note_draft.rstrip() + "\n\n" + self.summary
        else:
            self.note_draft = self.summary
        self.notes_saved = False
        self.note_save_status = ""
        self.active_tab = "notes"

    # ── Save current note draft into the StudentNote workspace ──
    def save_note_to_workspace(self):
        text = (self.note_draft or "").strip()
        if not text:
            return
        uid = self._active_data_uid()
        title = (self.video_title or f"YouTube — {self.video_id}").strip()[:120]
        target_scope = self._notes_scope_key()
        if target_scope.startswith("learn:"):
            target_scope = "home"
        legacy_scope = f"learn:{self.video_id}"
        # Add the source link at the bottom of the note
        source = f"\n\n---\nSource: https://www.youtube.com/watch?v={self.video_id}"
        body = text + source
        try:
            with rx.session() as session:
                existing = session.exec(
                    select(StudentNote)
                    .where(StudentNote.user_id == uid)
                    .where(StudentNote.scope == target_scope)
                    .where(StudentNote.body == body)
                    .limit(1)
                ).first()
                if existing is not None:
                    self.last_saved_note_text = text
                    self.notes_saved = False
                    self.note_save_status = "already"
                    self.note_save_feedback_id += 1
                    return LearnState.clear_note_save_feedback_later(self.note_save_feedback_id)
                legacy_row = None
                if legacy_scope != target_scope:
                    legacy_row = session.exec(
                        select(StudentNote)
                        .where(StudentNote.user_id == uid)
                        .where(StudentNote.scope == legacy_scope)
                        .where(StudentNote.body == body)
                        .limit(1)
                    ).first()
                if legacy_row is not None:
                    legacy_row.scope = target_scope
                    legacy_row.title = title
                    session.add(legacy_row)
                else:
                    row = StudentNote(
                        user_id=uid,
                        scope=target_scope,
                        title=title,
                        body=body,
                        attachments_json="[]",
                        source_message_db_id=0,
                    )
                    session.add(row)
                session.commit()
            self.notes_saved = True
            self.note_save_status = "saved"
            self.last_saved_note_text = text
            self.note_save_feedback_id += 1
            self._reload_notes_items()
            return LearnState.clear_note_save_feedback_later(self.note_save_feedback_id)
        except Exception as e:
            logger.error(f"save_note_to_workspace error: {e}")
            self.notes_saved = False
            self.note_save_status = ""

    def clear_notes_saved_flash(self):
        self.notes_saved = False
        self.note_save_status = ""

    @rx.event(background=True)
    async def clear_note_save_feedback_later(self, feedback_id: int):
        await asyncio.sleep(2.4)
        async with self:
            if self.note_save_feedback_id == feedback_id:
                self.notes_saved = False
                self.note_save_status = ""


