class HTTPSRedirectMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request, call_next):
        if ENFORCE_HTTPS:
            proto = (
                request.headers.get("x-forwarded-proto") or ""
            ).split(",")[0].strip().lower()
            if proto == "http":
                https_url = str(request.url).replace("http://", "https://", 1)
                return StarletteRedirect(https_url, status_code=301)
        return await call_next(request)


class SecurityHeadersMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request, call_next):
        response = await call_next(request)
        h = response.headers
        # Prevent MIME-type sniffing
        h.setdefault("X-Content-Type-Options", "nosniff")
        # strict-origin-when-cross-origin lets YouTube iframes work
        # (no-referrer breaks YouTube embed Error 153)
        h.setdefault("Referrer-Policy", "strict-origin-when-cross-origin")
        # Block clickjacking — only allow our own domain to frame us
        h.setdefault("X-Frame-Options", "SAMEORIGIN")
        # Force HTTPS for 1 year (only sent over HTTPS)
        h.setdefault("Strict-Transport-Security", "max-age=31536000; includeSubDomains")
        # Restrict browser features
        h.setdefault("Permissions-Policy", "camera=(), microphone=(self), geolocation=()")
        content_type = h.get("content-type", "")
        if "text/html" in content_type:
            # Keep Chrome from reusing an older app shell after deploys.
            h.setdefault("Cache-Control", "no-store, max-age=0")
            h.setdefault("Pragma", "no-cache")
            h.setdefault("Expires", "0")
        # Content Security Policy — allows YouTube iframes + our own assets
        h.setdefault(
            "Content-Security-Policy",
            "default-src 'self'; "
            "script-src 'self' 'unsafe-inline' 'unsafe-eval' "
            "https://www.googletagmanager.com https://www.google-analytics.com "
            "https://www.youtube.com https://s.ytimg.com "
            "https://unpkg.com https://cdn.jsdelivr.net; "
            "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; "
            "font-src 'self' https://fonts.gstatic.com; "
            "img-src 'self' data: blob: https: http:; "
            "media-src 'self' blob:; "
            "frame-src https://www.youtube.com https://www.youtube-nocookie.com; "
            "connect-src 'self' wss: ws: https:; "
            "worker-src 'self' blob:; "
            "wasm-src 'self' https://unpkg.com https://cdn.jsdelivr.net;",
        )
        return response


