async def google_start(request: Request):
    if not GOOGLE_OAUTH_ENABLED:
        return RedirectResponse(url=f"{_frontend_base_url(request)}{auth_routes.LOGIN_ROUTE}", status_code=302)
    oauth_nonce = secrets.token_urlsafe(24)
    params = {
        "client_id": GOOGLE_CLIENT_ID,
        "redirect_uri": _google_callback_url(request),
        "response_type": "code",
        "scope": "openid email profile",
        "state": _google_make_state_for_nonce(oauth_nonce),
        "prompt": "select_account",
    }
    response = RedirectResponse(url=f"{GOOGLE_AUTH_URL}?{urlencode(params)}", status_code=302)
    response.set_cookie(
        GOOGLE_STATE_COOKIE_NAME,
        oauth_nonce,
        max_age=GOOGLE_STATE_MAX_AGE_SECONDS,
        httponly=True,
        secure=_request_is_https(request),
        samesite="lax",
    )
    return response


async def google_callback(request: Request):
    if not GOOGLE_OAUTH_ENABLED:
        return RedirectResponse(url=f"{_frontend_base_url(request)}{auth_routes.LOGIN_ROUTE}", status_code=302)
    try:
        state = str(request.query_params.get("state", "") or "")
        state_payload = _google_parse_state(state)
        expected_nonce = str(request.cookies.get(GOOGLE_STATE_COOKIE_NAME, "") or "").strip()
        if state_payload is None or not expected_nonce or state_payload.get("n") != expected_nonce:
            response = RedirectResponse(url=f"{_frontend_base_url(request)}{auth_routes.LOGIN_ROUTE}", status_code=302)
            response.delete_cookie(GOOGLE_STATE_COOKIE_NAME)
            return response

        if request.query_params.get("error"):
            print(f"[Google CB] error param: {request.query_params.get('error')}")
            response = RedirectResponse(url=f"{_frontend_base_url(request)}{auth_routes.LOGIN_ROUTE}", status_code=302)
            response.delete_cookie(GOOGLE_STATE_COOKIE_NAME)
            return response

        code = str(request.query_params.get("code", "") or "")
        if not code:
            print("[Google CB] no code")
            response = RedirectResponse(url=f"{_frontend_base_url(request)}{auth_routes.LOGIN_ROUTE}", status_code=302)
            response.delete_cookie(GOOGLE_STATE_COOKIE_NAME)
            return response

        async with httpx.AsyncClient(timeout=20.0) as client_http:
            token_resp = await client_http.post(
                GOOGLE_TOKEN_URL,
                data={
                    "code": code,
                    "client_id": GOOGLE_CLIENT_ID,
                    "client_secret": GOOGLE_CLIENT_SECRET,
                    "redirect_uri": _google_callback_url(request),
                    "grant_type": "authorization_code",
                },
                headers={"Accept": "application/json"},
            )
            token_resp.raise_for_status()
            token = token_resp.json()
            access_token = str(token.get("access_token", "") or "")
            if not access_token:
                raise ValueError("Google token response missing access token.")

            userinfo_resp = await client_http.get(
                GOOGLE_USERINFO_URL,
                headers={"Authorization": f"Bearer {access_token}"},
            )
            userinfo_resp.raise_for_status()
            payload = userinfo_resp.json() or {}
            if not isinstance(payload, dict):
                raise ValueError("Google userinfo response was not a JSON object.")
            userinfo = payload

        subject = str((userinfo or {}).get("sub", "")).strip()
        google_email = _normalize_email(str((userinfo or {}).get("email", "") or ""))
        if not subject:
            print("[Google CB] no subject in userinfo")
            raise ValueError("Google userinfo missing subject.")

        username = _google_username_from_sub(subject)

        with rx.session() as session:
            user = session.exec(
                select(LocalUser).where(func.lower(LocalUser.username) == username.lower())
            ).one_or_none()

            if user is None:
                user = LocalUser(
                    username=username,
                    password_hash=LocalUser.hash_password(secrets.token_urlsafe(40)),
                    enabled=True,
                )
                session.add(user)
                session.commit()
                session.refresh(user)

            if user.id is None:
                raise ValueError("Unable to create a valid local user for Google login.")

            if google_email:
                _store_user_profile_email(int(user.id), google_email)

            auth_token = secrets.token_urlsafe(32)
            session.add(
                LocalAuthSession(
                    user_id=int(user.id),
                    session_id=auth_token,
                    # Long-lived session (90 days) — this token IS the auth
                    # token the browser keeps in localStorage. Originally
                    # short-lived because handle_google_complete used to
                    # exchange it for a long-lived one, but our simpler
                    # post-login bridge skips that step.
                    expiration=datetime.now(timezone.utc) + timedelta(seconds=AUTH_SESSION_MAX_AGE_SECONDS),
                )
            )
            session.commit()

        bootstrap_html = f"""<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="referrer" content="strict-origin-when-cross-origin">
    <meta http-equiv="Cache-Control" content="no-store, max-age=0">
    <meta http-equiv="Pragma" content="no-cache">
    <meta http-equiv="Expires" content="0">
    <title>Signing you in...</title>
  </head>
  <body style="margin:0;background:#050505;color:#fff;font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;display:flex;min-height:100vh;align-items:center;justify-content:center;">
    <div>Signing you in...</div>
	    <script>
	      (function() {{
	        try {{
	          // JSON.stringify wraps the token in quotes so rx.LocalStorage
	          // (and other JSON.parse readers) decode it cleanly. Storing
	          // the raw token without quotes makes Reflex's auth check see
	          // an empty string, treating the user as a guest.
	          localStorage.setItem({json.dumps(AUTH_TOKEN_LOCAL_STORAGE_KEY)}, JSON.stringify({json.dumps(auth_token)}));
	          localStorage.setItem('alex_ga_auth_method', 'google');
	        }} catch (e) {{}}
	        window.location.replace("/auth/post-login");
	      }})();
	    </script>
  </body>
</html>"""
        response = HTMLResponse(
            bootstrap_html,
            status_code=200,
            headers={
                "Cache-Control": "no-store, max-age=0",
                "Pragma": "no-cache",
                "Expires": "0",
                "Referrer-Policy": "strict-origin-when-cross-origin",
            },
        )
        response.delete_cookie(GOOGLE_STATE_COOKIE_NAME)
        response.delete_cookie(GOOGLE_COMPLETE_COOKIE_NAME)
        response.set_cookie(
            AUTH_TOKEN_LOCAL_STORAGE_KEY,
            auth_token,
            max_age=AUTH_SESSION_MAX_AGE_SECONDS,
            httponly=False,
            secure=_request_is_https(request),
            samesite="lax",
            path="/",
        )
        return response

    except Exception as e:
        print(f"[Google CB] ERROR: {e}")
        traceback.print_exc()
        response = RedirectResponse(url=f"{_frontend_base_url(request)}{auth_routes.LOGIN_ROUTE}?oauth_error=1", status_code=302)
        response.delete_cookie(GOOGLE_STATE_COOKIE_NAME)
        return response
    

api.add_route("/auth/google/start", google_start, methods=["GET"])
api.add_route("/auth/google/callback", google_callback, methods=["GET"])
api.add_route("/oauth/google/start", google_start, methods=["GET"])

async def legacy_auth_complete_redirect(request: Request):
    token = str(request.path_params.get("token", "") or "").strip()
    target = f"{_frontend_base_url(request)}/auth/complete"
    if token:
        target = f"{target}?{urlencode({'token': token})}"
    return RedirectResponse(url=target, status_code=302)


async def legacy_google_complete_redirect(request: Request):
    code = str(request.path_params.get("code", "") or "").strip()
    state = str(request.path_params.get("state", "") or "").strip()
    origin_b64 = str(request.path_params.get("origin_b64", "") or "").strip()
    params = {k: v for k, v in {"code": code, "state": state, "origin_b64": origin_b64}.items() if v}
    target = f"{_frontend_base_url(request)}/auth/google/complete"
    if params:
        target = f"{target}?{urlencode(params)}"
    return RedirectResponse(url=target, status_code=302)


api.add_route("/auth/complete/{token}", legacy_auth_complete_redirect, methods=["GET"])
api.add_route(
    "/auth/google/complete/{code}/{state}/{origin_b64}",
    legacy_google_complete_redirect,
    methods=["GET"],
)


async def serve_chat_media(request: Request):
    rel_path = str(request.path_params.get("path", "") or "").strip("/")
    token = str(request.query_params.get("mt", "") or "").strip()
    if not _media_token_is_valid(token, rel_path):
        return PlainTextResponse("forbidden", status_code=403)

    target = (CHAT_MEDIA_ROOT / rel_path).resolve()
    root = CHAT_MEDIA_ROOT.resolve()
    if not str(target).startswith(str(root)) or not target.is_file():
        return PlainTextResponse("not found", status_code=404)

    media_type = _safe_chat_media_type(target)
    if not media_type:
        return PlainTextResponse("forbidden", status_code=403)
    return FileResponse(
        target,
        media_type=media_type,
        headers={
            "Cache-Control": "private, max-age=300",
            "X-Content-Type-Options": "nosniff",
        },
    )


api.add_route("/media/chat/{path:path}", serve_chat_media, methods=["GET"])

